-- ----------------------------
-- Table structure for st_article
-- ----------------------------
DROP TABLE IF EXISTS `st_article`;
CREATE TABLE `st_article` (
  `article_id` int(8) unsigned NOT NULL AUTO_INCREMENT,
  `article_cat_id` int(8) unsigned NOT NULL DEFAULT '0',
  `article_title` varchar(250) NOT NULL DEFAULT '',
  `article_ts` varchar(255) DEFAULT NULL,
  `article_summary` text NOT NULL,
  `article_des` longtext,
  `article_pic` varchar(100) DEFAULT NULL,
  `article_pic_pos` tinyint(1) unsigned NOT NULL DEFAULT '2',
  `article_visitor` int(8) unsigned NOT NULL DEFAULT '0',
  `article_is_new` tinyint(1) DEFAULT '1',
  `article_priority` tinyint(1) DEFAULT '0',
  `article_active_vote` int(1) unsigned DEFAULT '1',
  `article_active_hint` int(1) unsigned DEFAULT '1',
  `article_active` tinyint(1) unsigned NOT NULL DEFAULT '0',
  `article_date` date DEFAULT NULL,
  `article_pic_active` tinyint(1) unsigned DEFAULT '0',
  `article_last_article` tinyint(1) DEFAULT '0',
  `article_publisher_id` int(8) unsigned NOT NULL DEFAULT '0',
  `article_source` varchar(255) DEFAULT NULL,
  `article_source_url` text,
  `article_youtube_id` varchar(100) DEFAULT NULL,
  `article_file` varchar(100) DEFAULT NULL,
  `article_user_add_hint_nsup` tinyint(1) DEFAULT '1',
  PRIMARY KEY (`article_id`),
  KEY `wg_id` (`article_id`)
) ENGINE=MyISAM AUTO_INCREMENT=39 DEFAULT CHARSET=utf8;

