-- Records of st_article
-- ----------------------------
BEGIN;
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (1, 1, 'حول قوله تعالى : { فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَكِنَّ الظَّالِمِينَ بِآَيَاتِ اللَّهِ يَجْحَدُونَ }', '', 'قوله تعالى مخبراً عن المشركين : {  فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَكِنَّ الظَّالِمِينَ بِآَيَاتِ اللَّهِ يَجْحَدُونَ } والمعنى فإنهم لا يعتقدون أنك كاذب بل يعرفون أنك صادق فيما جئت به وأنك رسول الله حقاً ولكنهم جحدوا ذلك ولم يعترفوا به ، والجحود هو الإنكار بعد علم .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قوله تعالى مخبراً عن المشركين : { &nbsp;فَإِنَّهُمْ لَا يُكَذِّبُونَكَ وَلَكِنَّ الظَّالِمِينَ بِآَيَاتِ اللَّهِ يَجْحَدُونَ }&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والمعنى فإنهم لا يعتقدون أنك كاذب بل يعرفون أنك صادق فيما جئت به وأنك رسول الله حقاً ولكنهم جحدوا ذلك ولم يعترفوا به ، والجحود هو الإنكار بعد علم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما الآيات كقوله تعالى :{ فإن كذبوك فقد كذبت رسل من قبلك }&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فالمعنى فإن نسبوا إليك الكذب لتبرير كفرهم وجحودهم فهم في الحقيقة لا يكذبونك ولكنهم ينسبون إليك الكذب تبريراً لكفرهم وإعراضهم كما نسبوا إليك السحر والشعر والجنون والكهانة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ونظير هذا قوله تعالى : { الَّذِينَ آَتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ &nbsp;} أي يعرفون أنه أي القرآن هو كلام الله حقاً وأنك رسول الله حقاً {وَإِنَّ فَرِيقًا مِنْهُمْ لَيَكْتُمُونَ الْحَقَّ وَهُمْ يَعْلَمُونَ } أي يعلمون أنه حق</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ونظير هذا قوله تعالى مخبراً عن آل فرعون : { وجحدوا بها واستيقنتها أنفسهم ظلماً وعلواً } أي أعرضوا وأنكروا الآيات التي جاء بها موسى عليه السلام بعد أن أيقنوا أنها حقاً من عند الله وما ذلك إلا بسبب ظلمهم وكبرهم وعلوهم - أي تكبرهم و طغيانهم - وذلك لأنه لا يكفي في الإيمان مجرد العلم والمعرفة بل لا بد من الإذعان والاعتراف والتصديق بهذا العلم .</span></span></span></p>', 'default.png', 1, 6624, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (2, 1, 'التغالي في المهور', '', 'وروي أن عمر رضي الله عنه  نهى عن التغالي في المهور أكثر من أربعمائة درهم فلما نزل اعترضته امرأة بقولها : ألم تسمع قول الله تعالى :{وآتيتم إحداهن قنطاراً } فقال اللهم عفواً ،  كل الناس أفقه منك يا عمر ، ثم صعد المنبر وقال :  كنت نهيتكم عن زيادة المهر أكثر من أربعمائة درهم فمن شاء أن يعطي من ماله ما أحب فليفعل .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وروي أن عمر رضي الله عنه &nbsp;نهى عن التغالي في المهور أكثر من أربعمائة درهم فلما نزل اعترضته امرأة بقولها : ألم تسمع قول الله تعالى :{وآتيتم إحداهن قنطاراً } فقال اللهم عفواً ، &nbsp;كل الناس أفقه منك يا عمر ، ثم صعد المنبر وقال : &nbsp;كنت نهيتكم عن زيادة المهر أكثر من أربعمائة درهم فمن شاء أن يعطي من ماله ما أحب فليفعل .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا تفهم من هذا وجوب التغالي في المهور فهو جائز ، ولكن هناك فرق كبير بين الإباحة والوجوب والأمر والنهي إذ إن المعتبر الدين والخلق كما في الحديث عن أبي هريرة قال : قال رسول الله صلى الله عليه وسلم :[ إذا أتاكم من ترضون خلقه ودينه فزوجوه إلا تفعلوا تكن فتنة في الأرض وفساد عريض ] &nbsp;وجاء في الحديث :[ إن الله جعل الحق على لسان عمر وقلبه ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال ابن عمر رضي الله عنهما :[ ما سمعت عمر لشيء قط يقول إني لأظنه كذا إلا كان كما يظن] &nbsp;وروى البخاري عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : [ لقد كان فيما قبلكم من الأمم محدثون فإن يك في أمتي أحد فإنه عمر] أي ومنهم من أمتي وعمر منهم والمحدث أعلى درجة من الملهم إذ تحدثه الملائكة حديثاً قلبياً أو شفهياً عن أمور غيبية .</span></span></span></p>', 'default.png', 1, 7326, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (3, 1, 'حول قوله تعالى : { العزيز الحكيم }', '', 'العزة تقتضي الترفع عن الغير والغلبة عليه كما في قوله  : [ وعزني في الخطاب ] أي غلبني في الخطاب .فاقتران اسم الحكيم بالعزيز لأن الحكمة لابد لتنفيذها من قوة وقدرة وغلبة  أي فهو القادر على تنفيذ حكمته سبحانه  { والله غالب على أمره} أي على تنفيذ ما أراد سبحانه', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">العزة تقتضي الترفع عن الغير والغلبة عليه كما في قوله &nbsp;: [ وعزني في الخطاب ] أي غلبني في الخطاب .فاقتران اسم الحكيم بالعزيز لأن الحكمة لابد لتنفيذها من قوة وقدرة وغلبة &nbsp;أي فهو القادر على تنفيذ حكمته سبحانه &nbsp;{ والله غالب على أمره} أي على تنفيذ ما أراد سبحانه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد قام صلى الله عليه وسلم مرة طيلة الليل يقرأ بهذه الآية : { إن تعذبهم فإنهم عبادك وإن تغفر لهم فإنك أنت العزيز الحكيم } وهذا ما ذكره الله سبحانه عن عيسى عليه السلام وقال تعالى مخبراًعن سيدنا إبراهيم عليه السلام : { فمن تبعني فإنه مني ومن عصاني فإنك غفور رحيم } أما عيسى عليه السلام فقد دعا متأسياً ومتأدباً بآداب الملائكة من حملة العرش والملأ الأعلى { &nbsp;الَّذِينَ يَحْمِلُونَ الْعَرْشَ وَمَنْ حَوْلَهُ يُسَبِّحُونَ بِحَمْدِ رَبِّهِمْ وَيُؤْمِنُونَ بِهِ وَيَسْتَغْفِرُونَ لِلَّذِينَ آَمَنُوا رَبَّنَا وَسِعْتَ كُلَّ شَيْءٍ رَحْمَةً وَعِلْمًا فَاغْفِرْ لِلَّذِينَ تَابُوا وَاتَّبَعُوا سَبِيلَكَ وَقِهِمْ عَذَابَ الْجَحِيمِ رَبَّنَا وَأَدْخِلْهُمْ جَنَّاتِ عَدْنٍ الَّتِي وَعَدْتَهُمْ وَمَنْ صَلَحَ مِنْ آَبَائِهِمْ وَأَزْوَاجِهِمْ وَذُرِّيَّاتِهِمْ إِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ}</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما الخليل عليه السلام فقد طرق باب الرجاء والرحمة فقال &nbsp;:{فمن تبعني فإنه مني } - أي من ملتي .{ومن عصاني فإنك غفور رحيم } أي بأنه يؤمن ويتوب وتغفر له بقدرتك ورحمتك .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد جمع الحبيب الأعظم صلى الله عليه وسلم كمال الأدب أدب عيسى وأدب إبراهيم عليهما السلام ودعا بالآيتين لأمته صلى الله عليه وسلم ، كما روى الإمام مسلم عن عبد الله بن عمرو بن العاص رضي الله عنهما أن النبي صلى الله عليه وسلم تلا قول الله عز وجل في إبراهيم { رب إنهن أضللن كثيرا من الناس فمن تبعني فإنه مني } الآية ، وقول عيسى عليه السلام : { إن تعذبهم فإنهم عبادك وإن تغفر لهم فإنك أنت العزيز الحكيم } ، فرفع يديه وقال اللهم أمتي أمتي وبكى فقال الله عز وجل يا جبريل اذهب إلى محمد وربك أعلم فسله ما يبكيك فأتاه جبريل عليه السلام فسأله فأخبره رسول الله صلى الله عليه وسلم بما قال وهو أعلم فقال الله يا جبريل اذهب إلى محمد فقل إنا سنرضيك في أمتك ولا نسوءك &nbsp;حول قوله سبحانه وتعالى : { كتاب أحكمت آياته ثم فصلت من لدن حكيم خبير }.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إن المراد من الإحكام في الآية هو أن نصوص الآيات القرآنية محكمة المعنى من حيث متانتها وتركيبها اللغوي وبلاغتها فهي في غاية المتانة والبلاغة والإعجاز ولا حشو فيها ثم فصلت هذه الآيات القرآنية إلى سور وجاءت كل سورة بمنزلة كتاب فيما تناولته من مواضيع أو قصص أو غير ذلك .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما المراد من قوله تعالى : { هو الذي أنزل عليك الكتاب منه آيات محكمات } أي في المعنى والمبنى &nbsp;{ وأخر متشابهات } أي في المعنى إن كانت الآية تتعلق بخبر أو حكم شرعي أو قصص أو أمر أو نهي وأما إن كانت الآية تتعلق بالصفات الإلهية فقد تكون محكمة المعنى أي ظاهرة المعنى والمبنى أيضاً كقوله تعالى :{ ليس كمثله شيء وهو السميع البصير }، وقد تكون الآية متشابهة المعنى وإن كانت محكمة المبنى كقوله تعالى : { الرحمن على العرش استوى } والاستواء هو العلو لكن علوه سبحانه فوق عرشه لا يشبه علو المخلوقين فليس هو علواً مكانياً أو انتقالياً أو روحياً بل هو علو لائق به سبحانه ، &nbsp;فهمنا ذلك برد هذه الآية المتشابه فهمها إلى المحكمة ، قال تعالى : { ليس كمثله شيء } لأن فهم المتشابه لا يمكن إلا برده إلى المحكم لقوله تعالى &nbsp;{ هن أم الكتاب } أي أصله ومرجعه فكانت المتشابهات بمنزلة الفروع فيجب رد الفروع إلى الأصول لبيانها وفهمها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وخلاصة القول :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أن آيات الكتاب كلها محكمة المبنى والمعنى أما الآيات التي تتعلق بالصفات الإلهية قد تكون متشابهة المعنى , وبردها إلى المحكمة تصير محكمة مفهومة وأما قوله تعالى :{ كتاباً متشابهاً } فوصف الكتاب كله بالمتشابه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نعم أي يشبه بعضه بعضاً في تركيب الآيات اللغوي ويؤيد بعضها بعضاً في الفهم والبيان فترى آية تبين معنى آية أخرى أو تؤيد معناها وهكذا . وليس المراد تشابه الفهم إذ تبين ذلك فيما سبق .</span></span></span></p>', 'default.png', 1, 10990, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (4, 1, 'إن القرآن أنزل على سبعة أحرف', '', 'اختلف العلماء من قوله صلى الله عليه وسلم [ على سبعة أحرف ] على أربعين قولاً .والجمع بين هذه الأقوال والتحقيق فيها أن المراد على سبعة وجوه في قراءة الكلمة وذلك أن رد اختلاف القراءات يرجع إلى سبعة أصول في قراءة الكلمة', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اختلف العلماء من قوله صلى الله عليه وسلم [ على سبعة أحرف ] على أربعين قولاً .والجمع بين هذه الأقوال والتحقيق فيها أن المراد على سبعة وجوه في قراءة الكلمة وذلك أن رد اختلاف القراءات يرجع إلى سبعة أصول في قراءة الكلمة , والحرف هو الطرف قال تعالى { ومن الناس من يعبد الله على حرف } أي طرف فقد يطلق على طرف الكلمة &nbsp;ويكون المراد منه الحرف الذي تتألف منه الكلمة وهي حروف الهجاء وقد يطلق الحرف ويراد منه الكلمة على اعتبار أنها طرف الكلمة له أو الآية والحديث الذي يؤيد هذا المعنى قوله صلى الله عليه وسلم : [ من قرأ حرفا من كتاب الله فله به حسنة ، والحسنة بعشر أمثالها ، لا أقول الم حرف - أي بل كلمة - ، ولكن ألف حرف ولام حرف وميم حرف ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهنا أطلق اسم الحرف وأراد الحرف لأن اللام مثلاً هي اسم للحرف وأما حقيقة الحرف فهي ل .وفي الحديث : أبشر بنورين أوتيتهما لم يؤتهما نبي قبلك : فاتحة الكتاب ، وخواتيم سورة البقرة ، لن تقرأ بحرف منهما - أي بكلمة - إلا أعطيته - أي في الأجر والثواب &nbsp;القضاء والقدر اختلف العلماء في معنيهما على أن أحدهما حكم والآخر تنفيذ وليس هذا موضعاً للخلاف إذ أن المهم أن تفهم معنى القضاء أو القدر فخلاصة البحث أنك لما تقول قدر الله كذا أو قضى كذا فهذا يعني أنه بحانه علم فأراد فكتب &nbsp; فخلق وكل أفعاله مقترنة بحكمته سبحانه ولا يصح أن تفسر القضاء بالعلم فقط .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">واعلم أن علم الله تعالى بالأشياء سابق على وجودها وأنه سبحانه أوجدها على حسب ما علم { ألا يعلم من خلق } وهذا يدل على أن المعلومات تابعة للعلم الإلهي وأما الإنسان فعلمه تابع للمعلومات إذ أنه لو لم يرى أو يسمع للأشياء لما علمها لأن نوافذ العلم إلى العقل عند الإنسان هي السمع والبصر .</span></span></span></p>', 'default.png', 1, 5855, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (5, 1, 'من هو الذبيح ؟', '', 'إن إسماعيل عليه السلام هو الذي أمر الله تعالى والده سيدنا إبراهيم عليه السلام أن يذبحه وذلك بالرؤيا لأن رؤيا الأنبياء وحي من الله بخلاف غيرهم وليس الذبيح اسحاق كما قال بعضهم لأن اسحاق ولد بعد إسماعيل أي لما كان إسماعيل فتى وهذا ما يدل عليه سياق الآيات ومفهومها .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إن إسماعيل عليه السلام هو الذي أمر الله تعالى والده سيدنا إبراهيم عليه السلام أن يذبحه وذلك بالرؤيا لأن رؤيا الأنبياء وحي من الله بخلاف غيرهم وليس الذبيح اسحاق كما قال بعضهم لأن اسحاق ولد بعد إسماعيل أي لما كان إسماعيل فتى وهذا ما يدل عليه سياق الآيات ومفهومها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقد كانت السيدة سارة زوجة إبراهيم عليه السلام لم تكن تلد فلما أهدى الملك الجبار لإبراهيم جارية وهي هاجر ولدت له إسماعيل فتأثرت السيدة سارة لذلك وشكت أمرها إلى الله فأجابها الله تعالى وولد منها إسحاق عليه السلام &nbsp;؟, يقول تعالى &nbsp;:{ فأرادوا به كيداً فجعلناهم الأسفلين وقال إني ذاهب إلى ربي سيهدين رب هب لي من الصالحين فبشرناه بغلام حليم } وهو إسماعيل عليه السلام { فَلَمَّا بَلَغَ مَعَهُ السَّعْيَ قَالَ يَا بُنَيَّ إِنِّي أَرَى فِي الْمَنَامِ أَنِّي أَذْبَحُكَ فَانْظُرْ مَاذَا تَرَى قَالَ يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ سَتَجِدُنِي إِنْ شَاءَ اللَّهُ مِنَ الصَّابِرِينَ فَلَمَّا أَسْلَمَا وَتَلَّهُ لِلْجَبِينِ &nbsp;وَنَادَيْنَاهُ أَنْ يَا إِبْرَاهِيمُ قَدْ صَدَّقْتَ الرُّؤْيَا إِنَّا كَذَلِكَ نَجْزِي الْمُحْسِنِينَ &nbsp;إِنَّ هَذَا لَهُوَ الْبَلَاءُ الْمُبِينُ &nbsp;وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ } ثم قال جل وعلا :{ وبشرناه باسحق نبياً من الصالحين وباركنا عليه وعلى إسحق ومن ذريتهما محسن وظالم لنفسه مبين } فلما قال { وبشرناه باسحق } دل على أن الذبيح ليس بإسحق .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن ناحية أخرى فقد قال تعالى :{ ووهبنا له اسحق ويعقوب نافلة } وقال سبحانه :{ وبشرناه باسحق ومن وراء اسحق يعقوب } أي أن اسحق سيلد يعقوب .ولو كان الذبيح إسحاق فكيف يبشره سبحانه بأنه سيلد له يعقوب ولم يكن له علم أن الله سيفدي ولده إسماعيل بذبح عظيم إذ أن الله تعالى لما أمر إبراهيم بذبح إسماعيل لم يكن إبراهيم يعلم أن الله سيفدي إسماعيل بذبح عظيم إذ أنه باشر ذلك وتله للجبين وناديناه أن يا إبراهيم قد صدقت الرؤيا &nbsp; ولو كان الذبيح إسحق فكيف &nbsp;يبشره الله تعالى بأن إسحق سيلد يعقوب ؟؟</span></span></span></p>', 'default.png', 1, 9742, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (6, 2, 'ما هي حقيقة التقوى ؟', '', 'وقال ابن عمر رضي الله عنهما : لا يبلغ العبد حقيقة التقوى حتى يدع ما حاك في الصدر  وفي الحديث المرفوع : لا يبلغ العبد أن يكون من المتقين ، حتى يدع ما لا بأس به ، حذرا لما به البأس  أي يتجنب المباحات خشية الوقوع في المكروهات والمحرمات', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال ابن عمر رضي الله عنهما : لا يبلغ العبد حقيقة التقوى حتى يدع ما حاك في الصدر &nbsp;وفي الحديث المرفوع : لا يبلغ العبد أن يكون من المتقين ، حتى يدع ما لا بأس به ، حذرا لما به البأس &nbsp;أي يتجنب المباحات خشية الوقوع في المكروهات والمحرمات ولذلك فإن أهل الله رضي الله عنهم ليس عندهم شيء مباح وإنما يفعلون المباحات على أنها عبادات وذلك بالنية ، وبالنية الصالحة تنقلب العادات والمباحات إلى عبادات وطاعات ومن هنا تفهم قول معاذ رضي الله عنه :[ إني لأحتسب الأجر عند الله تعالى في نومتي كما أحتسب في قومتي ] &nbsp;لأنه يستعين بنومه على القيام والعبادة فصار نومه عبادة بهذه النية.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكذا أفعالهم في الأكل والشرب واللباس والذهاب والمجيء .كما قال صلى الله عليه وسلم :[ وفي بضع أحدكم صدقة ] &nbsp;أي إذا أتى أهله ونوى بذلك الإحصان وغض البصر وكبح الشهوة فإن فعله هذا عبادة مأجور عليها.</span></span></span></p>', 'default.png', 1, 9643, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (7, 2, 'وصفه صلى الله عليه وسلم بالسيادة', '', 'استحب الفقهاء علاوة عن المحدثين أن يذكر صلى الله عليه وسلم بلفظ السيادة [ سيدنا محمد ] في الصلاة الإبراهيمية وغيرها وكذلك المحدثين . ولم لا وقد قال صلى الله عليه وسلم :[ أنا سيد ولد آدم ]   فقلنا له يا سيدنا ألا ترى لما قال صلى الله عليه وسلم : [ أنا رسول الله ]  قلنا له وخاطبناه بقولنا يا رسول الله .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">استحب الفقهاء علاوة عن المحدثين أن يذكر صلى الله عليه وسلم بلفظ السيادة [ سيدنا محمد ] في الصلاة الإبراهيمية وغيرها وكذلك المحدثين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولم لا وقد قال صلى الله عليه وسلم :[ أنا سيد ولد آدم ] &nbsp; فقلنا له يا سيدنا ألا ترى لما قال صلى الله عليه وسلم : [ أنا رسول الله ] &nbsp;قلنا له وخاطبناه بقولنا يا رسول الله .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما أخبر صلى الله عليه وسلم أنه نبي الله وقال أنا نبي الله &nbsp;قال له الصحابة وخاطبوه بقولهم يا نبي الله وكذلك أنه حبيب الله وأكرم الأولين والآخرين على الله وغيرها مما أخبر عنه صلى الله عليه وسلم من خصائصه وكذلك قال صلى الله عليه وسلم أنا سيد ولد آدم فوجب علينا أن نقول يا سيدنا فافهم وتعقل ولا تقل بدعة وانظر تفصيل ذلك في موضعه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما ما رواه الأصبهاني &nbsp; أن رجلاً قال لرسول الله : يا رسول الله ، أنت سيدنا وفي رواية قال : يا سيدنا ، فنهاه صلى الله عليه وسلم وقال السيد هو الله .فرواية هذا الحديث ضعيفة لأنها خالفت ما هو أصح منها فيما يتعلق بهذا المعنى وتحمل على أنه صلى الله عليه وسلم آنس من هذا الرجل السيادة المطلقة وهذه لا تكون إلا لله فنهاه صلى الله عليه وسلم عن ذلك حتى يصح إيمانه بالله ورسوله صلى الله عليه وسلم لأنه صلى الله عليه وسلم &nbsp;نهى عن أمور كثيرة في بدء الدعوة حتى يتمكن الإيمان الصحيح والتوحيد الخالص في قلوب الصحابة فلما آنس منهم ذلك أباح ما قد نهاه ومن ذلك قوله &nbsp;صلى الله عليه وسلم &nbsp;:كنت قد نهيتكم ، عن زيارة القبور ألا فزوروها &nbsp;وقوله : ونهيتكم عن الانتباذ - &nbsp;نقع عصير الفواكه بحيث لا يصير خمراً -فانتبذوا &nbsp;ومنها قوله صلى الله عليه وسلم :[ إنه لا يستغاث بي ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">مع أنه صلى الله عليه وسلم أمر بإغاثة الملهوف وفي حديث الشفاعة الذي رواه الإمام البخاري : استغاثوا بآدم ثم بموسى ثم بمحمد صلى الله عليه وسلم أما السيد بالسيادة المطلقة وهي سيادة الألوهية فهي لله وحده فالخلق كلهم عبيد له سبحانه ولم يرد في دعائه صلى الله عليه وسلم قوله عن الله تعالى :[ يا سيدنا ] بل ورد هذا بطريق الخبر [ السيد هو الله ] أي بالسيادة المطلقة كما تقدم فافهم ولا تحتج بهذا الحديث على فهمك الخاطئ إذ إن الفهم الصحيح لابد له من رد الآيات والأحاديث إلى بعضها البعض وفهمها جملة واحدة قال تعالى مخبراً عن نبيه يحيى عليه السلام {وسيداً وحصوراً ونبياً من الصالحين }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وصح عنه صلى الله عليه وسلم قوله :[ إن ابني هذا سيد ] &nbsp;يريد الحسن رضي الله عنه وقال صلى الله عليه وسلم &nbsp;للأنصار قوموا إلى سيدكم - يريد سعد بن معاذ رضي الله عنه &nbsp;وإن أقواله وأعماله صلى الله عليه وسلم دائماً هي من شرع الله الذي يجب أن نتبعه</span></span></span></p>', 'default.png', 1, 7699, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (8, 2, 'رؤية الله تعالى في عالم البرزخ', '', 'ومما يدل على  ان هناك من الصالحين الأكابر من يرى الله تعالى في عالم البرزخ ما رواه الترمذي وابن حبان واللفظ له  عن جابر بن عبد الله بن حرام رضي الله عنهما قال : لقيني النبي صلى الله عليه وسلم ، فقال لي : &quot; يا جابر ، ما لي أراك منكسرا &quot; ؟', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما يدل على &nbsp;ان هناك من الصالحين الأكابر من يرى الله تعالى في عالم البرزخ ما رواه الترمذي وابن حبان واللفظ له &nbsp;عن جابر بن عبد الله بن حرام رضي الله عنهما قال : لقيني النبي صلى الله عليه وسلم ، فقال لي : &quot; يا جابر ، ما لي أراك منكسرا &quot; ؟ فقلت : يا رسول الله ، استشهد أبي ، وترك عيالا ودينا ، فقال : &quot; ألا أبشرك بما لقي الله به أباك &quot; ؟ قلت : بلى ، يا رسول الله ، قال : &quot; ما كلم الله أحدا قط إلا من وراء حجاب ، وإن الله أحيا أباك فكلمه كفاحا - أي بدون حجاب &nbsp;- ، فقال : يا عبدي ، تمن أعطك ، قال : تحييني فأقتل قتلة ثانية ، قال الله : إني قضيت أنهم لا يرجعون &quot; ، ونزلت هذه الآية : ولا تحسبن الذين قتلوا في سبيل الله أمواتا بل أحياء عند ربهم يرزقون * &nbsp;ورؤي سفيان الثوري &nbsp;بعد وفاته في النوم فسئل: ما فعل بك ربك؟ &nbsp;فقال:</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نظرت إلى ربي كفاحاً فقال لي</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">&nbsp;هنيئاً رضائي عنك يا بن سعيد فقد كنت قواماً إذا أقبل الدجى</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">بعبرة مشتاق وقلب عميد فدونك فاختر أي قصر أردته&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وزرني فإني منك غير بعيد</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">روى الطبراني وغيره عن سلمان الفارسي رضي الله عنه &nbsp;عن النبي صلى الله عليه وسلم قال : &quot; من توضأ في بيته فأحسن الوضوء ، ثم أتى المسجد ، فهو زائر الله ، وحق على المزور أن يكرم الزائر &quot;&nbsp;</span></span></span></p>', 'default.png', 1, 5044, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (9, 3, 'بيان الشيخ عن الحجاب', '', 'عبارة الفقهاء أن المرأة كلها عورة إلا وجهها وكفيها وقدميها ويجب ستر الوجه مع أنه ليس بعورة إذا خشيت الفتنة أما ظاهر الكف والقدم فيجب ستره عند بعض الفقهاء وبعضهم جوز كشفه .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عبارة الفقهاء أن المرأة كلها عورة إلا وجهها وكفيها وقدميها ويجب ستر الوجه مع أنه ليس بعورة إذا خشيت الفتنة أما ظاهر الكف والقدم فيجب ستره عند بعض الفقهاء وبعضهم جوز كشفه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والأخذ بالأحوط عند الفتنة أولى ولو لم يكن ستر الوجه واجباً على المرأة فما وجه الإباحة للمخاطب أن ينظر إلى وجهها مرة أو أكثر كما نص عليه الفقهاء إذ لو أبيح لها كشف الوجه على إطلاقه لنظر إليها الخاطب متى شاء وكيف شاء&nbsp;\r\nوهناك دليل قاطع للشيخ الإمام حول ذلك يدور بين الآيتين :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ &nbsp;وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ }{ &nbsp;يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ وَبَنَاتِكَ وَنِسَاءِ الْمُؤْمِنِينَ يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ ذَلِكَ أَدْنَى أَنْ يُعْرَفْنَ فَلَا يُؤْذَيْنَ وَكَانَ اللَّهُ غَفُورًا رَحِيمًا }</span></span></span></p>', 'default.png', 1, 6427, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 8, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (10, 3, 'صدقة الفطر صاع تمر أو صاع حنطة أو ..', '', 'ذهبت طائفة من علماء العصر إلى تقسيم صدقة الفطر بمقدارها فتختلف من الغني إلى المتوسط إلى الفقير ، فالغني يدفع صدقة الفطر صاعاً من تمر لأن ثمنه مرتفع في بلدنا والمتوسط حنطة لأنها معتدلة القيمة والفقير شعيراً وهذه التقسيمات باطلة', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ذهبت طائفة من علماء العصر إلى تقسيم صدقة الفطر بمقدارها فتختلف من الغني إلى المتوسط إلى الفقير ،&nbsp;فالغني يدفع صدقة الفطر صاعاً من تمر لأن ثمنه مرتفع في بلدنا والمتوسط حنطة لأنها معتدلة القيمة والفقير شعيراً وهذه التقسيمات باطلة لأن المقادير الشرعية التي سنها رسول الله صلى الله عليه وسلم لا تتغير بتغير الزمن بل هي ثابتة على جميع أصناف المجتمع .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولو كان لهذه التقسيمات أصل شرعي لبينه رسول الله صلى الله عليه وسلم إذ في عهده عليه الصلاة والسلام كانت الحنطة متضاعفاً ثمنها عن ثمن التمر بكثير .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكانت الحنطة نادرة تستورد أما التمر فكثير فلم لم يأمر صلى الله عليه وسلم عبد الرحمن بن عوف أو عثمان بن عفان وباقي أغنياء الصحابة بإخراج صدقة الفطر من الحنطة ويأمر الفقراء بإخراجها من التمر .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم ليس المقصود من صدقة الفطر الكثرة إنما لإغناء الفقير عن المسألة في يوم العيد فقط لما ورد في الحديث [أغنوهم عن طواف هذا اليوم ] &nbsp;أي عن المسألة فيه إذاً صدقة الفطر حسب المتوفر لديك والممكن ولا بأس أكان تمراً أم حنطة ولا حاجة لإلزام الفقير بنوع والغني بآخر .اهـ</span></span></span></p>', 'default.png', 1, 6815, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (11, 3, 'نفقة الآباء على الأبناء', '', 'نفقة الآباء على الأبناء ليست واجبة على الأب إلا عند عجز الابن عن العمل من حين بلوغه نفقة الآباء على الأبناء ليست واجبة على الأب إلا عند عجز الابن عن العمل من حين بلوغه نفقة الأبناء على الآباء واجبة في جميع الأحوال', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نفقة الآباء على الأبناء ليست واجبة على الأب إلا عند عجز الابن عن العمل من حين بلوغه نفقة الآباء على الأبناء ليست واجبة على الأب إلا عند عجز الابن عن العمل من حين بلوغه نفقة الأبناء على الآباء واجبة في جميع الأحوال فلو طلب الأب من أبناءه أن ينفقوا عليه ولو كان ميسوراً لوجب عليهم ذلك وذلك احتراماً لمقام الأبوة</span></span></span></p>', 'default.png', 1, 5537, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (12, 3, 'ما حكم قبول الموظف الهدية', '', 'لا يجوز أن يقبل الموظف الهدية من شخص له عند الموظف حاجة ولو كانت خالصة من كل شائبة أو تنازل عن حق أو غير ذلك فهي رشوة لأنه لو لم يكن موظفاً لما أهدي له شيء وهي من باب سد الذرائع', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لا يجوز أن يقبل الموظف الهدية من شخص له عند الموظف حاجة ولو كانت خالصة من كل شائبة أو تنازل عن حق أو غير ذلك فهي رشوة لأنه لو لم يكن موظفاً لما أهدي له شيء وهي من باب سد الذرائع لئلا تمتد الأمور إلى أشياء محرمة وقد نهى النبي صلى الله عليه وسلم عن ذلك .</span></span></span></p>', 'default.png', 1, 6249, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (13, 3, 'منع الحمل', '', 'لا يجوز في حالة خوف الفقر أما بنية تربية الأولاد والحفاظ على دينهم والخشية من ذلك فلا مانع من منع الحمل حسب الطريقة التي لا تؤدي إلى إيذاء المرأة', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لا يجوز في حالة خوف الفقر أما بنية تربية الأولاد والحفاظ على دينهم والخشية من ذلك فلا مانع من منع الحمل حسب الطريقة التي لا تؤدي إلى إيذاء المرأة&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قديماً كان يسميه الفقهاء [ العزل ]</span></span></span></p>', 'default.png', 1, 6401, 0, 0, 0, 1, 0, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (14, 4, 'فضل طلب العلم وتحمل الشدائد في طلبه', '', 'وقال : إن الشباب والفراغ والجدة *** مفسدة للمرء أي مفسدة ، والجدة : كثرة المال وقال الشافعي رضي الله عنه في بيان فضل طلب العلم وتحمل الشدائد في طلبه', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال :</span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إن الشباب والفراغ والجدة &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; مفسدة للمرء أي مفسدة</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والجدة : كثرة المال&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال الشافعي رضي الله عنه في بيان فضل طلب العلم وتحمل الشدائد في طلبه :</span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">واصبر على مر الجفا من معلم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;فإن رسوب العلم في نبراته ومن لم يذق ذل التعلم ساعة &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; تجرع كأس الجهل طول حياته ومن فاته التعليم وقت شبابه &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; كبر عليه أربعاً لوفاته&nbsp; حياة الفتى والله بالعلم والتقى &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; إذا لم يكونا لا اعتبار لذاته</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال رضي الله عنه في بيان الترفع عن حطام الدنيا وعزة النفس وكرامتها:</span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أنا إن عشت لست أعدم قوتاً &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; وإن مت لست أعدم قبراً همتي همة الملوك ونفسي &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; نفس حر ترى المذلة كفرا</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما سئل عن زيارة أحمد بن حنبل له وزيارته لأحمد قال :</span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قالوا يزورك أحمد وتزوره &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; قلت المكارم لا تغادر منزله إن زرته فلفضله أو زارني &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;فبفضله فالفضل في الحالين له</span></span></p>', 'default.png', 1, 5816, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (15, 4, 'حالة أهل الحقيقة مع الله تعالى', '', 'كتاب سيدي أحمد الرفاعي [ حالة أهل الحقيقة مع الله تعالى ] يعني حال أهل الحقيقة الإيمانية مع الله تعالى وهم الذين تحققوا بحقيقة الإيمان الذين ذكرهم سبحانه بقوله :{ أولئك هم المؤمنون حقاً } ولما سأل رسول الله صلى الله عليه وسلم حارثة بن النعمان', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كتاب سيدي أحمد الرفاعي [ حالة أهل الحقيقة مع الله تعالى ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">يعني حال أهل الحقيقة الإيمانية مع الله تعالى وهم الذين تحققوا بحقيقة الإيمان الذين ذكرهم سبحانه بقوله :{ أولئك هم المؤمنون حقاً }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما سأل رسول الله صلى الله عليه وسلم حارثة بن النعمان ، فقال له : &quot; كيف أصبحت يا حارثة ؟ &quot; قال : أصبحت مؤمنا حقا ، فقال رسول الله صلى الله عليه وسلم : &quot; انظر ما تقول ، فإن لكل حق حقيقة فما حقيقة إيمانك ؟ &nbsp; الحديث</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فكلمة الحقيقة التي وردت على لسان الشارع وأصحاب رسول الله صلى الله عليه وسلم وأتباعهم وأئمة القوم مرادهم الحقيقة الإيمانية وليس مرادهم التفرقة بين الشريعة والحقيقة إذ أن هذه التفرقة نشأت في العصور المتأخرة واصطلحوا على أن الحقيقة هي قضاء الله وقدره التكويني النافذ - أي إرادته التكوينية - المشار إليها بقوله تعالى :{ إنما أمره إذا أراد شيئاً أن يقول له كن فيكون }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما الشريعة فهي إرادته سبحانه التشريعية ومحبته ورضاه كما قال سبحانه :{ ولا يرضى لعباده الكفر وإن تشكروا يرضه لكم }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">مع أن الكفر بقضائه سبحانه وإرادته لكن ليس يرضاه سبحانه واعلم أنه لا تعارض بين الشريعة والحقيقة ولو عارضت الحقيقة الشريعة فهي باطلة كما أن قصة موسى مع الخضر ليس لها في الحقيقة مكان إذ أن عمل الخضر كان بموجب شريعة وأقره موسى لما تبينت له حكمة أفعاله .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وليس للعبد أن يحتج بالحقيقة بل عليه أن يعمل بظاهر الشريعة ألا ترى إلى قوله تعالى :{ إن الذين كفروا سواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون} هذه حقيقة لكنه صلى الله عليه وسلم لم يترك إنذارهم وإبلاغهم الدعوة إلى الله تعالى كما أن الاحتجاج بمشيئة الله وقدره على أمر لم يأت بعد أو على أمر مستمر صاحبه عليه - هذا الاحتجاج مردود على صاحبه لأنه من الذي أطلعه على مشيئة الله المستقبلية بذلك ؟</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد رد سبحانه على الكفار احتجاجهم بذلك لما أرادوا تبرير استمرارهم على الكفر فقال تعالى :{ سَيَقُولُ الَّذِينَ أَشْرَكُوا لَوْ شَاءَ اللَّهُ مَا أَشْرَكْنَا وَلَا آَبَاؤُنَا وَلَا حَرَّمْنَا مِنْ شَيْءٍ }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال تعالى :{ وإذا قيل لهم أنفقوا مما رزقكم الله قال الذين كفروا للذين آمنوا أنطعم من لو يشاء الله أطعمه } فاحتجوا بالمشيئة لتبرير بخلهم ومنعهم وشحهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وما أدراهم أن الله تعالى قد شاء إلى الأبد استمرارهم في الكفر أو شاء عدم إطعام الطعام هؤلاء ؟</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولذلك فلا يصح للمؤمن العاصي إذا نصحه أحد &nbsp;أن يقول حتى يريد الله بل عليه الإقلاع عن ذنبه لأنه ما أدراه أن الله قد شاء له الاستمرار على ذنبه أما الاحتجاج بالمشيئة على أمر قد مضى وحصل &nbsp;ثم تاب منه العبد فلا بأس كأن تقول شاء الله لي وقضى علي أن أفعل كذا وكذا ثم تبت إلى الله تعالى ومن ذلك احتجاج آدم بأن الله قد قضى عليه الأكل من الشجرة قبل أن يخلقه بأربعين سنة وذلك لما احتج آدم وموسى عليهما السلام فقال له موسى أنت آدم الذي أخرجت ذريتك من الجنة ، فقال آدم : أنت موسى الذي اصطفاك الله برسالاته ، وكلامه ثم تلومني على أمر قد قدر علي قبل أن أخلق ؟</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال صلى الله عليه وآله وسلم : &nbsp;فحج آدم موسى ولكن آدم عليه السلام قبل أن يأكل من الشجرة لم يكن يعلم أن الله قد قضى عليه الأكل منها فلما أكل منها لم يحتج بقضاء الله عليه بذلك بل اعترف بذنبه وتاب إلى الله لكن لما حاجه موسى احتج بقدر الله وقضائه فافهم .</span></span></span></p>', 'default.png', 1, 16368, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (16, 4, 'كيف تعرف أولياء الله تعالى', '', 'ذكر عن الإمام سهل بن عبد الله وقد سأله بعض تلاميذه كيف تعرف أولياء الله تعالى ؟فقال : إن الله تعالى لا يعرفهم إلا لأشكالهم أو من أراد أن ينفعه بهم ولو أظهرهم حتى يعرفهم الناس لكانوا حجة عليهم ومن خالفهم بعد علمه بهم كفر ومن قعد عنهم خرج', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ذكر عن الإمام سهل بن عبد الله وقد سأله بعض تلاميذه كيف تعرف أولياء الله تعالى ؟</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقال : إن الله تعالى لا يعرفهم إلا لأشكالهم أو من أراد أن ينفعه بهم ولو أظهرهم حتى يعرفهم الناس لكانوا حجة عليهم ومن خالفهم بعد علمه بهم كفر ومن قعد عنهم خرج - أي تأخر عنهم - ولكن الله تعالى جعل اختياره تغطية أمورهم رحمة منه لخلقه ورأفة ولكن الله تعالى قد أخبر بكرامتهم فقال عز وجل : { الله ولي الذين آمنوا } { والله ولي المؤمنين } فأفردهم به ولو أظهرهم حتى يبرزهم لكان في النظر إليهم حجة وكان الاستماع لحديثهم فرضاً</span></span></span></p>', 'default.png', 1, 6474, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (17, 4, 'مناجات الله عند الدعاء', '', 'قال سيدي أبو الحسن رضي الله عنه :[ لا يكن همك بدعائك الظفر بقضاء حوائجك فتكون محجوباً وليكن همك مناجاة مولاك ] وقال الإمام أبو القاسم القشيري رضي الله عنه : شر الناس من يبتهل إلى الله تعالى', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال سيدي أبو الحسن رضي الله عنه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ لا يكن همك بدعائك الظفر بقضاء حوائجك فتكون محجوباً وليكن همك مناجاة مولاك ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال الإمام أبو القاسم القشيري رضي الله عنه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">شر الناس من يبتهل إلى الله تعالى عند هجوم البلاء بخلوص الدعاء وشدة التضرع والبكاء فإذا زالت شكايته ورفعت عنه آفته ضيع الوفاء ونسي البلاء وقابل الرفد &nbsp; بنقض العهد وأبدل العقد &nbsp; برفض الود أولئك الذين أبعدهم الله في سابق الحكم وأدرجهم في سلك أهل الرد وقد قيل : بلاء يلجئك إلى الانتصاب بين يدي معبودك خير من عطاء ينسيك إياه ويقصيك عنه اهـ</span></span></span></p>', 'default.png', 1, 7433, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (18, 4, 'ثلاثة سمعوا منادياً ينادي', '', 'ثلاثة سمعوا منادياً ينادي :[ يا سعتر بري ] ففهم كل واحد منهم مخاطبة عن الله خوطب بها في سره فسمع الواحد [ اسع تر بري ] وسمع الآخر [ الساعة ترى بري] وسمع الآخر [ ما أوسع بري ] فالمسموع واحد واختلفت أفهام المسامعين', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثلاثة سمعوا منادياً ينادي :[ يا سعتر بري ] ففهم كل واحد منهم مخاطبة عن الله خوطب بها في سره فسمع الواحد [ اسع تر بري ] وسمع الآخر [ الساعة ترى بري] وسمع الآخر [ ما أوسع بري ] فالمسموع واحد واختلفت أفهام المسامعين كما قال تعالى : { يسقى بماء واحد ونفضل بعضها على بعض في الأكل } وقال سبحانه :{ قد علم كل أناس مشربهم }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فأما الذي سمع : اسع تر بري فمريد دل على الله تعالى بالنهوض إلى الله عزوجل بالأعمال فيستقبل الطريق بالجد فقيل له اسع إلينا بصدق المعاملة تر برنا بوجود المواصلة ، وأما الثاني : فكان واصلاً إلى الله تعالى طاولته الأوقات فخاف أن تفوته المواصلة فقيل له ترويحاً على قلبه لما أحرقته نار الشغف الساعة ترى بري &nbsp;وأما الآخر فعارف كشف له عن وسع الكرم فخوطب من حيث أشهد فسمع &nbsp;ما أوسع بري</span></span></span></p>', 'default.png', 1, 11261, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (19, 4, 'طعام من يرى لك الفضل ...', '', 'وقيل لا تأكل إلا طعام من يرى لك الفضل عليه في أكله ولا تأكل إلا طعام من يرى أنه وديعة عنده ولا تأكل إلا طعام زاهد لأنه يسر بأكلك ولا تأكل إلا طعاماً يراك صاحبه أفضل من الطعام', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقيل لا تأكل إلا طعام من يرى لك الفضل عليه في أكله ولا تأكل إلا طعام من يرى أنه وديعة عنده ولا تأكل إلا طعام زاهد لأنه يسر بأكلك ولا تأكل إلا طعاماً يراك صاحبه أفضل من الطعام</span></span></span></p>', 'default.png', 1, 7911, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (20, 4, 'اوقات العبد', '', 'قال سهل بن عبد الله التستري رضي الله عنه : ما من نفس ولا قلب إلا والله مطلع عليه في ساعات الليل والنهار فأيما نفس أو قلب رأى فيه حاجة إلى سواه سلط عليه إبليس', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال سهل بن عبد الله التستري رضي الله عنه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ما من نفس ولا قلب إلا والله مطلع عليه في ساعات الليل والنهار فأيما نفس أو قلب رأى فيه حاجة إلى سواه سلط عليه إبليس</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال سيدي أبو العباس المرسي رضي الله عنه : أوقات العبد أربعة لا خامس لها النعمة والبلية والطاعة والمعصية ولله تعالى عليك في كل وقت منها سهم من العبودية يقتضيه الحق منك بحكم الربوبية فمن كان وقته الطاعة فسبيله شهود المنة من الله أن هداه لها ووفقه للقيام بها ومن كان وقته المعصية فمقتضى الحق منه وجود الاستغفار والندم ومن كان وقته النعمة فسبيله الشكر وهو فرح القلب بالله ومن كان وقته البلية فسبيله الرضا بالقضاء والصبر&nbsp;</span></span></span></p>', 'default.png', 1, 8911, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (21, 4, 'ما قال عن العيد', '', 'وخرج الإمام الشبلي رضي الله عنه من المسجد بعد أن صلى مع الناس صلاة العيد ورأى كلاً منهم قد تزين بلباسه فقال : إذا لم تكن عيدي فما أصنع بالعيد *** جرى حبك في قلبي كجري الماء في العود', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وخرج الإمام الشبلي رضي الله عنه من المسجد بعد أن صلى مع الناس صلاة العيد ورأى كلاً منهم قد تزين بلباسه فقال :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إذا لم تكن عيدي فما أصنع بالعيد &nbsp; &nbsp; &nbsp; جرى حبك في قلبي كجري الماء في العود</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وسمي العيد بذلك لمعاودته على الناس ، وعند العارفين لأن الله تعالى يعود فيه على عباده بالرحمة والإحسان ولذلك يسمى عيد الفطر بيوم الجائزة كما جاء ذلك في الحديث &nbsp; وعيد الفطر هو يوم واحد وهو أول شهر شوال وأما عيد الأضحى فهو أربعة أيام تسمى أيام التشريق كما جاء في الحديث :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أيام التشريق أيام أكل وشرب وذكر الله عز وجل ، وتسمى أيام التشريق لأنهم كانوا يشرقون فيها اللحم لئلا يفسد .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفيه معنى لطيف وهو ظهور إشراقات أنوار الله تعالى على عباده الحجاج وغيرهم لأنهم راحوا يبتغون المنى في منى وذلك بعد أن غفر الله لهم يوم عرفة ثم قربهم في مزدلفة ثم أكرمهم وأتحفهم وأعطاهم مناهم في منى</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال بعضهم</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عيد وعيد وعيد صرن مجتمعة &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;وجه الحبيب ويوم العيد والجمعة</span></span></span></p>', 'default.png', 1, 6961, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (22, 4, 'إيضاح لما ورد في حزب الفرج من عبارة :[ ولا يعلم العرش مستقرك ]', '', 'إن النفي في قوله :[ ولا يعلم العرش مستقرك ] مسلط على الاستقرار وعلم العرش به وكأنه يقال [ لااستقرار لك حتى يعلم به العرش ] أي لا استقرار لله تعالى على عرشه حتى يعلم به العرش', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إن النفي في قوله :[ ولا يعلم العرش مستقرك ] مسلط على الاستقرار وعلم العرش به وكأنه يقال [ لااستقرار لك حتى يعلم به العرش ] أي لا استقرار لله تعالى على عرشه حتى يعلم به العرش .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولهذا نظائر كثيرة في القرآن كقوله تعالى :{ ما للظالمين من حميم ولا شفيع يطاع }فالنفي مسلط على الشفيع وما وراءه فلا يوجد شفيع حتى يطاع كما لا يوجد استقرار لله حتى يعلم به العرش وكذلك قوله تعالى :{ أين شركائي الذين زعمتم }فهذا استفهام إنكاري يفيد النفي فظاهر الآية أين الشركاء الذين زعمتم&nbsp;\r\nفالمفهوم كأنهم موجودون فأين هم ولكن النفي نفي الشركاء ونفي وجودهم وحاشا لله أن يكون له شريك .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبهذا ما يقنع العاقل ويفهم الجاهل عن معنى [ ولا يعلم العرش مستقرك ] &nbsp;بل وغيرها وغيرها فهناك النفي المسلط على الصفة والموصوف والنفي المسلط على المضاف والمضاف إليه</span></span></span></p>', 'default.png', 1, 5526, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (23, 4, 'العمل والعبادة', '', 'ما يروى عن الجنيد رضي الله عنه وقوله طاحت تلك الإشارات وضاعت تلك العبارات ولم ينفعنا إلا ركيعات  كنا نركعها في السحرفي السحر إن صح عنه ذلك فمحمول على أن العلم والمعرفة لا تكفيان ولا يصل العبد إلى مراتب الكمال ما لم يصحبه العمل والعبادة', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ما يروى عن الجنيد رضي الله عنه وقوله طاحت تلك الإشارات وضاعت تلك العبارات ولم ينفعنا إلا ركيعات &nbsp;كنا نركعها في السحرفي السحر إن صح عنه ذلك فمحمول على أن العلم والمعرفة لا تكفيان ولا يصل العبد إلى مراتب الكمال ما لم يصحبه العمل والعبادة وهذا مستدل من قول النبي صلى الله عليه وسلم : [ أنا أتقاكم لله ، وأعلمكم بحدود الله ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي رواية : والله ، إني لأرجو أن أكون أخشاكم لله ، وأعلمكم بما أتقي &nbsp;فقد قرن النبي صلى الله عليه وسلم التقوى مع العلم بحدود الله والتقوى أي العمل الصالح</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي أحد وجوه تفسير الآية { إليه يصعد الكلم الطيب والعمل الصالح يرفعه } أن الكلم الطيب لا يرفع إلا بالعمل الصالح فهو الذي يرفع الكلم الطيب فلابد من عمل</span></span></span></p>', 'default.png', 1, 5754, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (24, 4, 'الموجودات على أربعة أنواع', '', 'موجود كلامي : مثلاً قلت الله  موجود كتابي : مثلاً كتبت الله  موجود خارجي : معاين بالوجود موجود علمي في علم الخالق وذهني في علم المخلوق', '<p style=\"text-align:justify\"><span style=\"line-height:30px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\">موجود كلامي : مثلاً قلت الله&nbsp;\r\nموجود كتابي : مثلاً كتبت الله&nbsp;\r\nموجود خارجي : معاين بالوجود&nbsp;\r\nموجود علمي في علم الخالق وذهني في علم المخلوق</span></span></span></p>', 'default.png', 1, 5052, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (25, 4, 'سلام الخروج من الصلاة', '', 'اعلم أن السلام نوعان سلام المتاركة وسلام المقابلة فسلام الخروج من الصلاة على اليمين هو سلام متاركة لأن المصلي كان قد دخل في حضرة قرب خاصة في قعوده وأثناء قراءته التشهد فعندما حيى رب العالمين بالتحيات والصلوات اللائقة به تعالى', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اعلم أن السلام نوعان سلام المتاركة وسلام المقابلة فسلام الخروج من الصلاة على اليمين هو سلام متاركة لأن المصلي كان قد دخل في حضرة قرب خاصة في قعوده وأثناء قراءته التشهد فعندما حيى رب العالمين بالتحيات والصلوات اللائقة به تعالى وسلم على سيد أهل الحضرة وهو رسول الله صلى الله عليه وسلم ، وسلم على جميع من في الحضرة من عباد الله الصالحين وأشهدهم أنه يشهد أن لا إله إلا الله وأن محمداً رسول الله فعند خروجه من الصلاة يجب عليه أن يخرج من هذه الحضرة بالسلام على أهلها كما بدأ بالسلام على أهلها عند دخول الحضرة فيلاحظ في سلامه على اليمين أنه يسلم على رسول الله صلى الله عليه وسلم وجميع عباد الله الصالحين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما السلام على اليسار فهو سلام مقابلة فيلاحظ المصلي فيه أنه يسلم على من وراءه من مقتدين إن كان إماماً و إن كان منفرداً فإنه يلاحظ أنه يسلم على من اقتدى به من ملائكة وجن وأرواح مؤمنين .</span></span></span></p>', 'default.png', 1, 5801, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (26, 4, 'وقال رضي الله عنه : حضر مرة عند الشيخ الإمام الرفاعي رضي الله عنه عشرة آلاف مريد', '', 'وقال رضي الله عنه : حضر مرة عند الشيخ الإمام الرفاعي رضي الله عنه عشرة آلاف مريد - بضم الميم وليس بفتحها - [ لأن المريد من يتمرد على شيخه ] وسمعوا الدرس', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال رضي الله عنه : حضر مرة عند الشيخ الإمام الرفاعي رضي الله عنه عشرة آلاف مريد - بضم الميم وليس بفتحها - [ لأن المريد من يتمرد على شيخه ] وسمعوا الدرس ثم لما خرج قال : حشرني الله مع فرعون وقارون إن رأيت لنفسي فضلاً على أحد من هؤلاء أو مشيخة على أحد منهم .</span></span></span></p>', 'default.png', 1, 7267, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (27, 4, 'يا من ألوذ به فيما أأمله ويا من أعوذ به مما أحاذره', '', 'ألوذ : ألتجأ إليه في مهماتي ورغباتي  , أعوذ : أتحصن به من مخاوفي', '<p style=\"text-align:justify\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ألوذ : ألتجأ إليه في مهماتي ورغباتي&nbsp;\r\nأعوذ : أتحصن به من مخاوفي</span></span></p>', 'default.png', 1, 5815, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (28, 4, 'امرأة تشكو من زوجها', '', 'وجاءت امرأة إلى الإمام الجنيد رضي الله عنه تشكو إليه من زوجها وأنه يريد أن يطلقها فقالت له : لو كشف لك عن وجهي يا إمام ونظرت إلى جمالي  لتعجبت كيف يريد أن يطلقني  فلما سمع الإمام هذا الكلام منها صاح وأغشي عليه', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وجاءت امرأة إلى الإمام الجنيد رضي الله عنه تشكو إليه من زوجها وأنه يريد أن يطلقها فقالت له : لو كشف لك عن وجهي يا إمام ونظرت إلى جمالي &nbsp;لتعجبت كيف يريد أن يطلقني &nbsp;فلما سمع الإمام هذا الكلام منها صاح وأغشي عليه</span></span></span></p>', 'default.png', 1, 5864, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (29, 4, 'جاء رجل إلى سيدي أحمد الرفاعي وطلب منه أن يوصله إلى الله', '', 'جاء رجل إلى سيدي أحمد الرفاعي وطلب منه أن يوصله إلى الله فقال له اذهب إلى تلميذنا في القدس واطلب منه ذلك [ وفعل ذلك ليتأكد من صدق طلبه ]', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">جاء رجل إلى سيدي أحمد الرفاعي وطلب منه أن يوصله إلى الله فقال له اذهب إلى تلميذنا في القدس واطلب منه ذلك [ وفعل ذلك ليتأكد من صدق طلبه ]</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فذهب الرجل إليه وسماه له وطلب منه ذلك فقال له : وهل عرفت رسول الله قبل أن تصل إلى الله قال أعرفه &nbsp;كما يعرفه الناس [ المؤمنون ] فقال له اذهب وصل ركعتين في بيت المقدس ثم احضر فذهب وفعل ولما خرج من المسجد رأى نور النبي صلى الله عليه وسلم قد ملأ ما بين السموات والأرض فذهب إلى الشيخ وقال له :[ الآن عرفت ] وأعطاه العهد .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهكذا سيدنا رسول الله صلى الله عليه وسلم هو أصل الأنوار ومن نوره خلق الله كل شيء&nbsp;</span></span></p>', 'default.png', 1, 10693, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (30, 4, 'الصلاة الخامسة من الصلوات الإدريسية', '', 'اللهم إني أسألك بنور الأنوار الذي هو عينك لا غيرك أن تريني وجه نبيك محمد صلى الله عليه وسلم كما هو عندك . آمين', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم إني أسألك بنور الأنوار الذي هو عينك لا غيرك أن تريني وجه نبيك محمد صلى الله عليه وسلم كما هو عندك . آمين</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{يتوسل بذات الله تعالى الذي هو نور الأنوار }</span></span></span></p>', 'default.png', 1, 11855, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (31, 4, 'فائدة : مما ينفع لخفقان القلب', '', 'الإكثار من قولك : حبيب الله رسول الله ** صلوات الله على الحبيب', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">الإكثار من قولك :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">حبيب الله رسول الله &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; صلوات الله على الحبيب&nbsp;</span></span></span></p>', 'default.png', 1, 11523, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (32, 4, 'فائدة لدفع المضار والحفظ من المكاره والأهوال', '', 'كتابة البسملة / 113/ مرة في أول شهر محرم ثم تعلقها أو تحملها ليس لها أصل في الحديث إنما هي من مجربات السلف الصالح ولكن العدد له خصوصيات لا تنكر', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كتابة البسملة / 113/ مرة في أول شهر محرم ثم تعلقها أو تحملها ليس لها أصل في الحديث إنما هي من مجربات السلف الصالح ولكن العدد له خصوصيات لا تنكر فهو بمثابة أسنان المفتاح إذا زادت لا يفتح وإذا نقصت لا يفتح</span></span></span></p>', 'default.png', 1, 14421, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (33, 4, 'نقل الشيخ الأكبر رضي الله عنه عن المعري قوله', '', 'زعم المنجم والطبيب كلاهما *** لن يبعث  الأموات قلت لهم بلى  :: إن صح قولكما فلست بخاسر *** أو صح قولي فالوبال عليكما :: هذا أسلوب أولي في المجادلة مع المنكرين وهو الأخذ بالاحتياط لدفع الإنكار وهو من طرق الاستدلال العقلي على وجود الآخرة في مجادلة المنكرين', '<p style=\"text-align:justify\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">زعم المنجم والطبيب كلاهما &nbsp; &nbsp; &nbsp; &nbsp;لن يبعث &nbsp;الأموات قلت لهم بلى&nbsp;\r\nإن صح قولكما فلست بخاسر &nbsp; &nbsp; &nbsp; أو صح قولي فالوبال عليكما</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">هذا أسلوب أولي في المجادلة مع المنكرين وهو الأخذ بالاحتياط لدفع الإنكار وهو من طرق الاستدلال العقلي على وجود الآخرة في مجادلة المنكرين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد جاء في الآية : { قل أرأيتم إن كان من عند الله ثم كفرتم به من أضل ممن هو في شقاق بعيد } أما المعري فقد زعم جماعة أنه عارف زاهد وآخرون قالوا : زنديق ملحد والفصل بينهما أنه مسلم رحمه الله كان مبتلى وقال تعالى : { ليس على الأعمى حرج } وليس كل ما ينسب إليه بصحيح من جهة النقل أو الثبوت</span></span></span></p>', 'default.png', 1, 7993, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (34, 4, 'هل يرى الملائكة ربهم؟', '', 'الملائكة على أصناف وهم يرون ربهم حسب التجليات وليس رؤية دائمة وكل يرى على حسب حاله ورتبته وقربه .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\">الملائكة على أصناف وهم يرون ربهم حسب التجليات وليس رؤية دائمة وكل يرى على حسب حاله ورتبته وقربه .</span></span></span></p>', 'default.png', 1, 8096, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (35, 4, 'دعاء لإذهاب الألم والشفاء من المرض', '', 'اللهم صل على سيدنا محمد وعلى آله وصحبه وسلم تسليماً  أعوذ بالله من الشيطان الرجيم  بسم الله الرحمن الرحيم [بسم الله الشافي بسم الله الكافي', '<p style=\"text-align:center\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم صل على سيدنا محمد وعلى آله وصحبه وسلم تسليماً&nbsp;\r\nأعوذ بالله من الشيطان الرجيم&nbsp;\r\nبسم الله الرحمن الرحيم&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[بسم الله الشافي بسم الله الكافي بسم الله المعافي بسم الله خير الأسماء بسم الله رب الأرض والسماء بسم الله الذي بيده &nbsp;الشفاء بسم الله الذي اسمه بركة وشفاء بسم الله الذي لا يضر مع اسمه سم ولا داء&nbsp;بسم الله الذي لا يضر مع اسمه شيء في الأرض ولا في السماء وهو السميع العليم ]&nbsp;</span></span></p>', 'default.png', 1, 80839, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (36, 3, 'افطار يوم من رمضان عمداً', '', 'عند الحنفية تجب عليه الكفارة وهي صيام /60/ يوم على المستطيع والقضاء وعند غيرهم لا كفارة عليه بل توبة وقضاء يوم .', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عند الحنفية تجب عليه الكفارة وهي صيام /60/ يوم على المستطيع والقضاء وعند غيرهم لا كفارة عليه بل توبة وقضاء يوم .</span></span></span></p>', 'default.png', 1, 100, 0, 0, 0, 1, 0, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (37, 5, 'المجلس الأول', '', 'وكان من عادته رضي الله عنه  أن يستقبل الناس في عيدي الفطر والأضحى ، وذلك في اليوم الأول والثاني من كل عيد بعد صلاة العصر . فيبقى باب الدار مفتوحاً ويتوافد الناس على مختلف طبقاتهم جماعة بعد جماعة حتى إذا لم يتسع المكان لأهله', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان من عادته رضي الله عنه &nbsp;أن يستقبل الناس في عيدي الفطر والأضحى ، وذلك في اليوم الأول والثاني من كل عيد بعد صلاة العصر .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فيبقى باب الدار مفتوحاً ويتوافد الناس على مختلف طبقاتهم جماعة بعد جماعة حتى إذا لم يتسع المكان لأهله قام جماعة وودعوا الشيخ الإمام رضي الله عنه &nbsp;وانصرفوا ليجلس مكانهم آخرون .. وهكذا ..</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويجلس الحاضرون مصغين لكلام شيخنا الإمام رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا يتكلم منهم أحد تأدباً في حضرة الشيخ وحرصاً على سماع كلامه الذي سأذكر منه جملة واسعة إن شاء الله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبعد أن قدم رضي الله عنه &nbsp;من المدينة المنورة بأنوار رسول الله صلى الله عليه وسلم - وكان قد جاور فيها ما يزيد على ثلاث سنوات - تزاحم الناس إلى مجالسه وربما ضاق المكان بهم فجعل يستقبل الناس في جامع الشعبانية إذ تهيأ الكراسي والمناضد لذلك في ساحة الجامع إذ كانت أيام الصيف تعين على ذلك ..</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وربما حضر مجلسه رضي الله عنه &nbsp;بعض المنشدين ممن كان في حلب آنذاك فيومئ إليهم الشيخ الإمام رضي الله عنه &nbsp;بالإنشاد فيصغي الحاضرون وترتفع الأصوات بالصلاة على النبي صلى الله عليه وسلم .. ثم يعاود الشيخ الإمام رضي الله عنه &nbsp;حديثه وهكذا .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن كلامه في أحد المجالس ، - وقد عثرنا عليه في تسجيلات من بعض الأحباب وكان ذلك ما بين الأعوام 1405 &ndash; 1408 هـ - عندما سلم عليه رجل من أهل العلم . ولم تكن عمته فوق رأسه فنبهه رضي الله عنه &nbsp;إلى ذلك وقال له : إن شعار العلم شرف لأهل العلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم رحب بالحاضرين وقال : أسأل الله تعالى أن يعيد علينا وعليكم أعواماً بعد أعوام هذه المواسم الطيبة المباركة بالخير والعافية والبركة ورضا الله تعالى ورضا رسوله صلى الله عليه وسلم .. وأسأله سبحانه أن يجعلنا وإياكم ممن أكرمهم الله تعالى وأسعدهم وتولاهم في قوله تعالى :{ وَهُوَ يَتَوَلَّى الصَّالِحِينَ }.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأن يجعلنا وإياكم من المقبولين ومن العتقاء الذين أعتقهم في تلك الليالي الرمضانية التي قد مرت بنا وقد ورد في الحديث عنه صلى الله عليه وسلم :[لله تعالى عند كل فطر من شهر رمضان كل ليلة عتقاء من النار ستون ألفا] &nbsp;شعب الإيمان للبيهقي عن عبد الله بن مسعود وفي رواية [ ستمائة ألف ] &nbsp;شعب الإيمان للبيهقي عن الحسن مرسلاً.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد جاء في الحديث عنه صلى الله عليه وسلم :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[إن لله فى كل يوم جمعة ستمائة ألف عتيق يعتقهم من النار كلهم قد استوجبوا النار &nbsp;] عزاه في الجامع الكبيرلأبي يعلى و شعب الإيمان للبيهقي &nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي رواية :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[إن يوم الجمعة وليلة الجمعة أربع وعشرون ساعة ليس منها ساعة إلا ولله فيها ست مائة عتيق من النار كلهم قد استوجبوا النار] &nbsp;عزاه في كنز العمال &nbsp;لأبي يعلى عن أنس .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فإن فاتنا شيء من بركات شهر رمضان ومغفرته فإن غداً يوم جمعة ونسأل الله تعالى أن يشملنا فيه بالغفران .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإن من فضائل أمة سيدنا محمد صلى الله عليه وسلم أن الله تعالى قال لحبيبه صلى الله عليه وسلم : &nbsp;{ فَبَشِّرْ عِبَادِ } يعني : بشر أمتك يا رسول الله ، وهذا من الدواعي التي تدعو المؤمن المحمدي لأن يكون دائماً على بشارة من الله تعالى ..</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد جاءت أحاديث كثيرة عن رسول الله صلى الله عليه وسلم تبين فضل أمة سيدنا محمد وكرامتها على الله تعالى ، ويجب على كل مؤمن أن يطلع على ذلك ليعرف فضل الله ونعمته عليه بأن جعله من أمة سيدنا محمد صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولكي يزداد المؤمن معرفة بفضل الله عليه يجب أن يعلم أن الله تعالى قد امتن على المؤمنين من أمة سيدنا محمد صلى الله عليه وسلم بنعمتين عظيمتين أفرد سبحانه كل واحدة منهما بالذكر وهما : نعمة الإيمان أولاً ونعمة أن جعلنا الله من أمة خير الأنام سيدنا محمد وأن بعثه فينا نبياً رسولاً صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقال سبحانه في بيان نعمة الإيمان { بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَاكُمْ لِلْإِيمَانِ } وقال تعالى في بيان نعمة إرساله لسيدنا محمد صلى الله عليه وسلم في هذه الأمة : { لَقَدْ مَنَّ اللَّهُ عَلَى الْمُؤْمِنِينَ إِذْ بَعَثَ فِيهِمْ رَسُولًا مِنْ أَنْفُسِهِمْ يَتْلُو عَلَيْهِمْ آيَاتِهِ وَيُزَكِّيهِمْ وَيُعَلِّمُهُمُ الْكِتَابَ وَالْحِكْمَةَ وَإِنْ كَانُوا مِنْ قَبْلُ لَفِي ضَلَالٍ مُبِينٍ }&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما ذكره سبحانه في بيان فضل المؤمنين أنه اصطفاهم وأورثهم القرآن عن رسولهم سيدنا محمد صلى الله عليه وسلم وأن هذا هو الفضل الكبير ..&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال تعالى :{ ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا } - أي وهم المؤمنون من أمة سيدنا محمد صلى الله عليه وسلم الذين ورثوا الكتاب عن رسول الله صلى الله عليه وسلم ،{ فَمِنْهُمْ ظَالِمٌ لِنَفْسِهِ } أي : واقع في التقصير سواء بارتكاب المناهي أو التقصير في أداء الأوامر ، { وَمِنْهُمْ مُقْتَصِدٌ } أي : قائم بما عليه دون زيادة&nbsp; { وَمِنْهُمْ سَابِقٌ بِالْخَيْرَاتِ بِإِذْنِ اللَّهِ } أي : وهم المقربون الذين سبقوا غيرهم بفعل النوافل والطاعات .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ ذَلِكَ } أي : إشارة إلى الميراث والتوريث والاصطفاء للمؤمنين على غيرهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ هُوَ الْفَضْلُ الْكَبِيرُ } أي : هو فضل الله تعالى على أمة سيدنا محمد صلى الله عليه وسلم وذلك لأن شرف المقتدي على شرف إمامه ، وشرف الأمة على شرف رسولها صلى الله عليه وسلم وهو صلى الله عليه وسلم سيد العالمين كلهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما يجدر ذكره أن حظ كل مؤمن من الميراث المحمدي على حسبه . &nbsp;إذ إن كل مؤمن هو وارث عن سيدنا رسول الله صلى الله عليه وسلم فمنهم من نال حظاً وافراً كالعلماء والعارفين ، ومنهم دون ذلك ، ومنهم ، ومنهم &nbsp;فكما تختلف مقادير الميراث في الأموال تختلف أيضاً في العلوم والمعارف والمقامات الإيمانية وهكذا ..</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد حظيت أمة سيدنا محمد صلى الله عليه وسلم بسلام خاص من الله تعالى ، قال تعالى : { قُلِ الْحَمْدُ لِلَّهِ وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى } الآية .. وقد نالت هذه الأمة سلاماً من الله تعالى مع جملة الأمم المؤمنة بالله تعالى فقال سبحانه لنوح عليه السلام : { قِيلَ يَا نُوحُ اهْبِطْ بِسَلَامٍ مِنَّا وَبَرَكَاتٍ عَلَيْكَ وَعَلَى أُمَمٍ مِمَّنْ مَعَكَ }&nbsp; ومن سلم الله عليه فقد أدخله في سلامه وأمانه سبحانه ..</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن قال أن الآية { قُلِ الْحَمْدُ لِلَّهِ وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى } أن المراد هو الأنبياء والرسل فيقال : لقد سلم سبحانه على الأنبياء والرسل بقوله تعالى :{ وَسَلَامٌ عَلَى الْمُرْسَلِينَ } فذكرهم بوصف الرسالة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإن سياق الآية من قوله تعالى :{ وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى } يدل على أن الخطاب يجري حكمه في عالم الشهادة المادي ولم يقابل سيدنا محمد صلى الله عليه وسلم الأنبياء والمرسلين حتى يبلغهم سلام الله عليهم وإن كانت هناك اجتماعات روحانية برزخية لكن الآية في عالم الشهادة فقوله سبحانه : { ثُمَّ أَوْرَثْنَا الْكِتَابَ الَّذِينَ اصْطَفَيْنَا مِنْ عِبَادِنَا } وهم أمة سيدنا محمد صلى الله عليه وسلم وهم أيضاً الذين ذكرهم سبحانه بقوله :{ وَسَلَامٌ عَلَى عِبَادِهِ الَّذِينَ اصْطَفَى }&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نعم إن كل ذلك يحمل المؤمن على أن يذكر نعمة الله عليه وقد قال سبحانه : { يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا نِعْمَةَ اللَّهِ عَلَيْكُمْ } .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن المحافظة على الميراث القرآني أن يتمسك المؤمن بالقرآن الكريم عملاً وقولاً وخلقاً وأدباً وتلاوة وتدبراً في معانيه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما يقرب العبد إلى الله تعالى كثرة تلاوته لكتاب الله تعالى ففي الحديث : لما سئل صلى الله عليه وسلم : أي العمل أحب إلى الله ؟ - والمعنى : ما هي خير الأعمال التي تقرب إلى الله تعالى ؟ &nbsp;- &nbsp;قال : [ الحال المرتحل ] قيل : و ما الحال المرتحل ؟ قال : [ الذي يضرب &ndash; أي يقرأ &ndash; من أول القرآن إلى آخره كلما حل ارتحل ] &nbsp;سنن الترمذي كتاب القراءات عن ابن عباس أي : كلما ختم القرآن تلاوة شرع في ختمة أخرى ، وهكذا ، كالذي يقطع المسافات حتى يصل إلى مقصوده .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقارئ القرآن تقرباً إلى الله تعالى يطوي مراحل في التقرب إلى الله تعالى ومن جملة خصائص أمة سيدنا محمد صلى الله عليه وسلم أن رسول الله صلى الله عليه وسلم هو الذي يفتح باب الشفاعة على اختلاف مراتبها إذ لا يتقدم إلى الشفاعة إلا من كان له وزن ومقدار وكرامة عند المشفوع عنده . كما أن المشفوع عنده لا يقرب إليه إلا من يحب . فلا يتقدم لكشف التجلي الإلهي بالغضب الأكبر ويشفع في ذلك إلا صاحب الوجه الأول والمرآة الأولى لنور رب العالمين والمجلى الأول والحبيب الأعظم والإمام الذي لا إمام له والشفيع الذي لا شفيع له وهو سيدنا محمد صلى الله عليه وسلم ، وذلك في موقف تراجع واعتذر فيه جميع الأنبياء والرسل عليهم السلام واعترفوا بالعجز عن التقدم لهذا المقام العظيم وهو المقام المحمود الذي خص الله به رسوله صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم يسأل صلى الله عليه وسلم ربه أن يفتح باب الشفاعة لأمته بأن يشفع بعضهم لبعض وفي هذا يقول صلى الله عليه وسلم : [إن من أمتي من يشفع للفئام &ndash; أي القبائل من الناس - ومنهم من يشفع للقبيلة ومنهم من يشفع للعصبة ومنهم من يشفع للرجل حتى يدخلوا الجنة] &nbsp; &nbsp;سنن الترمذي كتاب صفة القيامة والرقائق والورع &nbsp;أي : فكل على حسب مقامه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وورد في حق عثمان رضي الله عنه أنه يشفع يوم القيامة في مثل ربيعة ومضر &nbsp; انظر سنن الترمذي كتاب صفة القيامة والرقائق والورع فانظر أيها المؤمن في هذا الفضل الكبير وهو أن رسول الله صلى الله عليه وسلم تشفع في أمته ، وتشفع فيهم أيضاً أن يشفع بعضهم لبعض .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهذا ما يحتم محبته وتعظيمه صلى الله عليه وسلم على كل مؤمن وأن لا يغفل عن ذكره صلى الله عليه وسلم والصلاة عليه دائماً وأبداً ، وأن يحكم الصلة بينه وبين رسول الله صلى الله عليه وسلم كصلة المقتدي بإمامه فهو أمامه وهو إمامه ، ولابد لكل مؤمن من يوم لا يسأل فيه عن أحد إلا عن سيدنا محمد صلى الله عليه وسلم وهو لما يصير الإنسان في قبره ويسأل : [ ما كنت تقول في هذا الرجل ؟] &nbsp;طرف حديث في صحيح البخاري كتاب الجنائز عن أنس بن مالك رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن لم يكن بينه وبين رسول الله صلى الله عليه وسلم صلة وارتباط ومحبة تلكأ في الجواب ووقع في الشدة ، ولما سئل سيدنا علي رضي الله عنه &nbsp;: كيف كان حبكم لرسول الله صلى الله عليه وسلم ؟ - أي يا معشر الصحابة &ndash; ، قال : لقد كان رسول الله صلى الله عليه وسلم أحب إلينا من أنفسنا وأهلينا وأموالنا وأحب إلينا من الماء البارد على الظمأ. انظر كتاب الشمائل ص 592 للشيخ الإمام رضي الله عنه وإن الصلاة عليه صلى الله عليه وسلم هي صلة به إذ يذكر رسول الله صلى الله عليه وسلم من يصلي عليه ويثني عليه ويدعو له ، نسأل الله تعالى أن يجعلنا مظللين بالنور المحمدي وأن يجعل قلوبنا متعلقة متعشقة لسيدنا رسول الله صلى الله عليه وسلم أبد الآبدين وأن يجعله نصب أعيننا وقبلة قلوبنا في كل أوقاتنا .</span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم أنشد بعض المنشدين مديحاً لرسول الله صلى الله عليه وسلم :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بشرى لنا نلنا المنى&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; زال العنا وافى الهنا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">والدهر أنجز وعده&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; والبشر أضحى معلنا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">يا نفس طيبي باللقا&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; يا نفس قري أعينا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">هذا جمال المصطفى&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أنواره لاحت لنا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">إن رمت عزاً لذ به&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; واسأل به تعط المنى</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">لقربه من ربه&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; اطلب ولا تخشى العنا </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم فرد المنشد عبد القادر راجح المعروف بـ رديف : هذه الأبيات :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">أينما وجهت وجهي أنتم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وكذا ذكراكم في مسمعي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وبسوداء فؤادي دائماً&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ما برحتم وسوادي ناظري</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">أين مني سلوة عنكم وما&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; برحت أخباركم تتلى علي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ليت شعري هل أرى في ظلهم&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;بعد بعدي وترى عيني الحمي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">إن عيدي يوم آتي دارهم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وأمرغ في ثراهم وجنتي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">أحمد الهادي إلى دين الهدى&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ببيان محكم من عند حي </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">عربي الأصل شهم بطل&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; سيف رب العرش نور النيري</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وجهه الوضاح حسبي حيث في&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; كل آن لم يغب عن مقلتي </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">يا حبيبي قصر المدح وما&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; فهته بالنظم لا يبلغ شي </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بعد مدح الله يا تاج العلا&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ونزول الآي من رب علي </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم أنشدت الفرقة :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">يا أعظم شافع جد برضاك&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ليهنأ قلبي بطيب لقاك </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;وأنسى الشقا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بمدحك ألقى كل الخير&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ومن لي سواك لكشف الضر</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">أنا والله عظيم الوزر&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; بتذلل دخلت حماك</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; فكن لي وقا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">سعادتنا بك يا ذا الفضل&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وأنت المرجى ليوم الفصل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ألا فامنن وجد بالوصل&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; لمتيم لا يبغي سواك</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أنله اللقا </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم أنشد عبد الوهاب :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">الله ربي ولا أشرك به أحداً&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; تبارك الله ربي حسبي دائماً أبداً </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">الله عوني وحسبي في الخطوب فلا&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أرجو سواه لكشف الضر معتمدا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم أنشدت الفرقة :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ما مد لخير الخلق يدا&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أحد إلا وبه سعدا </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">فلذاك مددت إليه يدي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;وبذلك كنت من السعدا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وعلينا تعطف يا أملي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; بشفاء القلب من العلل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">أيكون محبك في وجل&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وبجاهك لا نشقى أبدا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم فرد المنشد إبراهيم قلعة جي :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">والله ما حملت أنثى ولا وضعت&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; كمثل أحمد من قاص ولا داني</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">مهذب شرف الله الوجود به&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وخصه بدلالات وبرهان </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">يا صاح إن خفت في الأيام نائبة&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; من ظالم قاهر أو جور سلطان</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ولم تجد في الورى حراً له كرم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; يرجى نداه ولا صفح عن الجاني </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">فلذ بمن سبح الحصباء في يده&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; واقصد كريم السجايا مطلق العاني</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">يا سيدي يا رسول الله يا أملي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; يا موئلي يا ملاذي يوم تلقاني</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">هبني بجاهك ما قدمت من ذلل&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;جوداً ورجح بفضل منك ميزاني </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">واسمع دعائي واكشف ما يساورني&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;من الخطوب ونفس كل أحزاني </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وفيك يا ابن خليل الله يوم غد&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ألوذ من سوء زلاتي وعصياني </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">نوالك الجم يطويني وينشرني&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;بالمكرمات وعين اللطف ترعاني </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم أنشدت الفرقة :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">عيدي شهودي وعوني أنت يا عيني </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; والعيد عندي دوام المحو عن عيني</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">إثبات غيرك شرك في عقيدتنا </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;محو السوى ديننا يا قرة العين </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وأنشدت الفرقة أيضاً :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">تباهى الناس بالعيد&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وعيدي أنت يا سيدي </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">مباهاتي وتعييدي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; مناجاتي لمعبودي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">تجلى لي على طوري&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; بدا نوراً على نور</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وقد أعطيت منشوري &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;بأني غير مردود </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم فرد المنشد عبد القادر راجح هذه الأبيات :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وفي العيد عادات الكرام لقد جرت&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ببر اليتامى وافتقاد الأرامل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">إلهي تدارك ضعف حالي برحمة&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ولطف خفي عاجل غير آجل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">فإني جزوع لا صبور على البلا&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ودائي عضال لا محالة قاتلي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">فإني بطه مستغيث وراغب&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; إلى الله فهو الغوث في كل هائل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وإخوانه الرسل الكرام جميعهم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وباقي النبيين البدور الكوامل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وبالخلفاء الراشدين وآله&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وأصحابه غر الثقات الأماثل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">خصوصاً رفيق الغار ذي الرأي والحجا&nbsp;&nbsp; أبي بكر الصديق صدر المحافل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">إمام فدى خير الأنام بنفسه&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وفي ماله ما كان قط بباخل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وفي درء تلك الفتنة اختص وحده&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ولولاه لارتدت جميع القبائل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">كذلك أمير المؤمنين وعزهم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أبو حفص الفاروق محيي النوافل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بعثمان ذي النورين من جمعت به&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; بجمع كتاب الله كل الفضائل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بعلي أبي السبطين حيدرة الوغى&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; مبيد العدى ليث الحروب المداحل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بطلحتهم ثم الزبير وسعدهم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; كذا سعيد من سما بالفضائل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بصدق ابن عوف صاحب الهمة التي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; يدك لها في الحرب صم الجنادل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بغانم قطر الشام سيدنا أبي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; عبيدة كشاف الكروب العواطل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بسطوة سيف الله ذي البأس خالد&nbsp;&nbsp; &nbsp;فتى الحزم ماضي العزم زاكي الخصائل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بحمزة بالعباس عمي نبينا&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; بسبطيه بالزهراء عين الأماثل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">بأحمد بالنعمان ثم بمالك&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; وبالشافعي بحر الندى والمسائل</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">وبالأولياء الصالحين وبازهم&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أبو صالح من قال ما في المناهل </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ثم أنشدت الفرقة :</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">يا إمام الرسل يا سندي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; أنت باب الله ومعتمدي</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ففي دنياي وآخرتي&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; يا رسول الله خذ بيدي </span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">أنت سر الكون سيده&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; روحه مولاه أوحده</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">عبدكم مدت لكم يده&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;مددك يا صاحب المدد</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">ما رأت عين وليس ترى&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; مثل طه في الورى بشرا</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:18.0pt\"><span style=\"line-height:115%\">خير من فوق السماء سرى&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; طاهر الأخلاق والشيم</span></span></span></span></span></p>\r\n\r\n<p dir=\"RTL\" style=\"text-align:right\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم استأنف الشيخ الإمام رضي الله عنه &nbsp;حديثه فكان مما قال : لقد دلت الأحاديث على أن من صلى على سيدنا رسول الله صلى الله عليه وسلم مرة صلى الله عليه عشراً وصلى عليه رسول الله صلى الله عليه وسلم .. ففي الحديث : [من صلى علي من أمتي صلاة مخلصا من قلبه صلى الله عليه بها عشر صلوات ] &nbsp; سنن النسائي الكبرى كتاب عمل اليوم والليلة وقال صلى الله عليه وسلم :[ من صلى علي بلغتني صلاته وصليت عليه ] &nbsp;المعجم الأوسط للطبراني عن أبي جعفر رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما فضائل وآثار صلاة رسول الله صلى الله عليه وسلم على أحد من أمته فيكفيك في بيان ذلك قوله تعالى : { خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا وَصَلِّ عَلَيْهِمْ إِنَّ صَلَاتَكَ سَكَنٌ لَهُمْ }&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فلقد كان أصحاب رسول الله صلى الله عليه وسلم يتقدمون بمال الزكاة والصدقات في سبيل الله تعالى يتقدمون بها إلى سيدنا رسول الله صلى الله عليه وسلم حتى ينفقها على الفقراء والمحتاجين وغير ذلك ويسألون رسول الله صلى الله عليه وسلم أن يصلي عليهم فيقول صلى الله عليه وسلم :[ اللهم صل على فلان وآل فلان ] وهكذا</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن ذلك قوله صلى الله عليه وسلم :[ اللهم صل على آل بن أبي أوفى ] &nbsp;صحيح البخاري كتاب الدعوات .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أي : صل عليه وعلى آله من أولاده وأهله وذريته .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال تعالى في أثر صلاة رسول الله صلى الله عليه وسلم عليهم : { إِنَّ صَلَاتَكَ سَكَنٌ لَهُمْ } &nbsp;أي : تبعث السكينة في نفوسهم والطمأنينة في قلوبهم والسعة في عيشهم مما يزيدهم إيماناً ورفعة في المقام ، ولذلك كان الصحابة يحرصون على أن يصلي عليهم رسول الله صلى الله عليه وسلم ويسألونه ذلك حتى إنهم كانوا يحتسبون صلاته صلى الله عليه وسلم عليهم قربات إلى الله تعالى كما قال سبحانه :{ مِنَ الْأَعْرَابِ مَنْ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَيَتَّخِذُ مَا يُنْفِقُ قُرُبَاتٍ عِنْدَ اللَّهِ وَصَلَوَاتِ الرَّسُولِ أَلَا إِنَّهَا قُرْبَةٌ لَهُمْ سَيُدْخِلُهُمُ اللَّهُ فِي رَحْمَتِهِ إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ }&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والمعنى : أنهم يتخذون نفقاتهم في سبيل الله قربات إلى الله تعالى لأنهم مخلصون في إنفاقها ويتخذون أيضاً صلوات الرسول صلى الله عليه وسلم عليهم قربات إلى الله تعالى لما لها من منزلة وكرامة على الله تعالى وقد قال سبحانه : { أَلَا إِنَّهَا قُرْبَةٌ لَهُمْ &nbsp;} ، فمن أراد أن يحظى بصلاة رسول الله صلى الله عليه وسلم عليه فعليه أن يكثر من الصلاة عليه صلى الله عليه وسلم كما قال صلى الله عليه وسلم : [ من صلى علي بلغتني صلاته &ndash; أي فوراً &ndash; وصليت عليه ] &nbsp; المعجم الأوسط للطبراني .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وصلاته صلى الله عليه وسلم على من صلى عليه هي سكينة في المصلي فيجد في قلبه اطمئناناً وفي صدره انشراحاً وفي نفسه سعة بمقتضى قوله تعالى :{ إِنَّ صَلَاتَكَ سَكَنٌ لَهُمْ } ويتحتم على كل مؤمن الإكثار من الصلاة عليه صلى الله عليه وسلم سيما يوم الجمعة وليلتها لما جاء عنه صلى الله عليه وسلم : [أكثروا الصلاة علي في الليلة الغراء واليوم الأزهر ليلة الجمعة ويوم الجمعة ] &nbsp; أخرجه البيهقي عن ابن عباس كما في الفتح الكبير</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقوله صلى الله عليه وسلم :[ إن من أفضل أيامكم يوم الجمعة فيه خلق آدم عليه السلام وفيه قبض وفيه النفخة وفيه الصعقة فأكثروا علي من الصلاة فيه فإن صلاتكم معروضة علي .. قالوا : يا رسول الله كيف تعرض عليك صلاتنا وقد أرمت &ndash; يعني : بليت أي بعد الموت فقال : إن الله عز وجل حرم على الأرض أن تأكل أجساد الأنبياء ] &nbsp; قال المنذري في موضعين في الترغيب : رواه أحمد وابو داود والنسائي وابن ماجه وابن حبان في صحيحه والحاكم وصححه . اهـ انظر : 1 :491 ،2 :503</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وجزى الله عنا أصحاب رسول الله صلى الله عليه وسلم خير الجزاء إذ سألوه هذا ليبين لنا أن عرض الصلاة عليه صلى الله عليه وسلم مستمر في حياته وبعد وفاته صلى الله عليه وسلم فهي تعرض عليه لما كان في الحياة الدنيا ، ويصلي على من صلى عليه ، وتعرض عليه أيضاً بعد انتقاله إلى الحياة البرزخية العالية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبين صلى الله عليه وسلم أن الأنبياء عليهم السلام أحياء في قبورهم وأن الأرض لا تأكل أجسادهم ، فهو صلى الله عليه وسلم بعد وفاته كما هو بذاته وذراته وصفاته ومقاماته وكمالاته صلى الله عليه وسلم وقد انتقل إلى الحياة البرزخية العالية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما حكم الصلاة على النبي صلى الله عليه وسلم يوم الجمعة وفضلها فيبدأ من عصر يوم الخميس إلى طلوع شمس يوم السبت الذي بعد الجمعة ..</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وجاء عنه صلى الله عليه وسلم أن لله ملائكة ينزلون ليلة الجمعة ومعهم أقلام من ذهب وألواح من فضة يكتبون أجور المصلي على رسول الله صلى الله عليه وسلم وترفع إلى الدواوين العالية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">روى ابن عساكر عن أبي هريرة رضي الله عنه أن رسول الله صلى الله عليه وسلم قال : إذا كان يوم الخميس بعث الله ملائكة معهم صحف من فضة وأقلام من ذهب يكتبون يوم الخميس وليلة الجمعة أكثر الناس علي صلاة&quot;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما طالبنا رسول الله صلى الله عليه وسلم &nbsp;أن نكثر من الصلاة عليه صلى الله عليه وسلم فقد طالبنا بحق وجدير بنا أن نقوم بأداء حقه علينا صلى الله عليه وسلم ، وبها نتقرب إلى الله تعالى لأنها مقابلة بصلاته علينا صلى الله عليه وسلم كما تقدم بيانه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي الحديث عنه صلى الله عليه وسلم : &nbsp;[من صلى علي مائة كتب الله بين عينيه براءة من النفاق وبراءة من النار وأسكنه الله يوم القيامة مع الشهداء] &nbsp;المعجم الأوسط للطبراني عن أنس بن مالك رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال صلى الله عليه وسلم :[ من صلى علي في يوم ألف مرة لم يمت حتى يرى مقعده من الجنة ] &nbsp;ذكره ابن شاهين في فضائل الأعمال وانظر كتاب الصلاة على النبي صلى الله عليه وسلم ص 91 &nbsp;للشيخ الإمام رضي الله عنه ، &nbsp;فإذا علم المؤمن ذلك فكيف يتقاعس أن يقوم بالصلاة عليه صلى الله عليه وسلم ويحسب أنه على شيء ؟!&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">&nbsp;ثم اختتم رضي الله عنه &nbsp;حديثه بالدعاء فقال : إننا نرحب بزوارنا الأحباب ونسأل الله تعالى أن يجعلنا وإياهم من عباد الله الصالحين وكما جمعنا هنا نسأله أن يجمعنا في حضرة سيدنا رسول الله صلى الله عليه وسلم ، وفي مقعد صدق عند مليك مقتدر . وكل عام وأنتم بخير ، ثم شرع بالدعاء : اللهم صل على سيدنا محمد حبيبك الأكرم ونبيك المعظم وعلى آله وأصحابه وأزواجه وذريته وأتباعه وعلينا معهم أجمعين كررها ثلاثاً.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">صلاة ترضيك وترضيه وترضى بها عنا يا رب العالمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">صلاة تغفر بها ذنوبنا وتفرج بها كروبنا وتنور بها قلوبنا وتستر وتصلح بها عيوبنا وتشفينا بها من كل داء وتعافينا بها من كل بلاء صلاة تجعلنا بها من عبادك المقربين .. من عبادك الصالحين الذين قلت فيهم : { وَهُوَ يَتَوَلَّى الصَّالِحِينَ } صلاة تعطف بها علينا برحمتك التي عطفت بها على أحبابك ومقربيك ، صلاة تعطف بها علينا قلب سيدنا محمد صلى الله عليه وسلم عطف الأحباب على الأحباب يا رب الأرباب . صلاة يرضاها رسول الله صلى الله عليه وسلم ويفرح بها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم إنا نسألك ونتوجه إليك بأوجه الوجهاء إليك وأكرم الخلق عليك وأقرب المقربين لديك إمام عبادك وعبادك وخيرتك من خليقتك سيدنا محمد صلى الله عليه وسلم صاحب الوجه المقبول والمقام المحمود &nbsp;نسألك اللهم بجاهه عندك وبوجاهته عندك وبكرامته عليك أن تملأنا من الأنوار المحمدية والأسرار المحمدية والنفحات المحمدية وأن ترزقنا من بركاته وتفيض علينا من فيوضاته ، وتحفنا بحفاوته وتجعلنا في نظراته وأن ترزقنا من مسحاته الشريفة مسحات تباشر قلوبنا وذاتنا وذراتنا وذرياتنا .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم صلاة تفيض بها علينا كل خير وتحفظنا بها من كل شر ، صلاة تجمعنا بها برسول الله صلى الله عليه وسلم يقظة ومناماً .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم إنك أمرتنا بدعائك ووعدتنا بإجابتك وأنت قلت في محكم كتابك : { وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ } اللهم إنا دعوناك كما أمرتنا فاستجب لنا كما وعدتنا إنك لا تخلف الميعاد .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم إنا واقفون ببابك منطرحون على أعتابك ومتوجهون إلى جنابك ومتوسلون إليك بأحب أحبابك فلا تردنا خائبين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اجعلنا من الذين إذا دعوك أجبتهم وإذا سألوك أعطيتهم وإذا استرضوك رضيت عنهم وإذا استغاثوك أغثتهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نسألك اللهم بجاه رسول الله صلى الله عليه وسلم عندك أن تكرمنا إكراماً محمدياً وتجعلنا خير وراث لسيدنا محمد صلى الله عليه وسلم ، وأن تجعلنا متمسكين بشريعته متبعين لسنته ، معتزين بعزته صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم اغفر لنا وارحمنا ولوالدينا ولمشايخنا ولكل من له حق علينا ولجميع المسلمين والمسلمات الأحياء منهم والأموات وصلى الله على سيدنا محمد وعلى آله وصحبه أجمعين وعلى جمعنا هذا بغفرانك وإحسانك لا تدع فينا شقياً ولا محروماً .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهؤلاء ضيوفنا وزوارنا أكرمهم يا رب بإكرامك وأتحفهم بإتحافك واجمعنا وإياهم في حضرة نبيك سيدنا محمد صلى الله عليه وسلم في الدنيا وفي الآخرة يا أرحم الراحمين يا أرحم الراحمين يا أرحم الراحمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">سبحان ربك رب العزة عما يصفون وسلام على المرسلين والحمد لله رب العالمين &nbsp;.</span></span></span></p>', 'default.png', 1, 8759, 0, 0, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
INSERT INTO `st_article` (`article_id`, `article_cat_id`, `article_title`, `article_ts`, `article_summary`, `article_des`, `article_pic`, `article_pic_pos`, `article_visitor`, `article_is_new`, `article_priority`, `article_active_vote`, `article_active_hint`, `article_active`, `article_date`, `article_pic_active`, `article_last_article`, `article_publisher_id`, `article_source`, `article_source_url`, `article_youtube_id`, `article_file`, `article_user_add_hint_nsup`) VALUES (38, 5, 'المجلس الثاني', '', 'وفي مجلس آخر افتتح رضي الله عنه  الجلسة بالترحيب بالضيوف والزائرين وقال : كل عام وأنتم بخير وأسأل الله تعالى أن يجعلنا وإياكم والمسلمين بخير وعافية وعلى رضا من الله تعالى ورسوله صلى الله عليه وسلم', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي مجلس آخر افتتح رضي الله عنه &nbsp;الجلسة بالترحيب بالضيوف والزائرين وقال : كل عام وأنتم بخير وأسأل الله تعالى أن يجعلنا وإياكم والمسلمين بخير وعافية وعلى رضا من الله تعالى ورسوله صلى الله عليه وسلم .، وأن يعيد هذا العيد علينا وعليكم وعلى المسلمين بكل خير وعافية ، ثم رحب بالحاضرين وقال : مرحباً يا شباب وإن كان فيكم كبار السن إلا أنكم شباب في طاعة الله إن شاء الله تعالى .. لأن الشاب الحقيقي هو القوي في طاعة الله وإن علاه الشيب ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويدل على ذلك قوله تعالى في سيدنا إبراهيم عليه السلام :{ سَمِعْنَا فَتًى يَذْكُرُهُمْ يُقَالُ لَهُ إِبْرَاهِيمُ } ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">مع أن إبراهيم عليه السلام كان متقدماً في السن آنذاك ، ووصف سبحانه أصحاب الكهف بأنهم فتية فقال تعالى : { إِنَّهُمْ فِتْيَةٌ آمَنُوا بِرَبِّهِمْ وَزِدْنَاهُمْ هُدًى }&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وكانت هذه الجلسة بعد صلاة المغرب وتأخرت عن الوقت المعروف بسبب شدة الحر .. وكان أحد القائمين على خدمة الجلسة زاد في إنارة المصابيح فقال الشيخ الإمام رضي الله عنه :إن من شأن النور أن يظهر الأشياء الموجودة التي لم تكن ظاهرة للعيان .. وكل هذه الأنوار مخلوقة ، وإن كان الشيء الذي يظهر الموجودات للعيان يسمى نوراً بعدما كانت في ظلمة ولا تراها الأعين فإن الذي خلق الموجودات وأظهرها من العدم هو الله نور السماوات والأرض .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أي : مظهر السماوات والأرض بعد أن كانت في العدم الإمكاني فلم يظهر شيء في الوجود إلا بنور الله تعالى .. قال تعالى : { اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ } أي : به ظهورها .. فهي ثابتة الوجود في العلم الإلهي . وذلك لأن الأشياء العدمية على نوعين : الأول معدوم مستحيل الوجود لا يمكن وجوده إطلاقاً كالشريك والولد في حق الله تعالى .. فهذا المعدوم المستحيل هو في ظلمة عدمية لا تقبل الظهور وهناك المعدوم الممكن كالإنسان قبل وجوده مثلاً كان في ظلمة عدم تحتاج إلى نور حتى يظهرها فأفاض سبحانه عليها النور فظهرت الممكنات من العدم ، فما من ظاهر إلا وقد ظهر بنور الله تعالى .. وما من نور ظاهر ويظهر لك الأمور إلا والذي أظهره أشد ظهوراً منه .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والذي أظهر نور الشمس من ظلمة العدم أشد ظهوراً من نور الشمس ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والذي أظهر الظاهرات أشد ظهوراً منها ولذلك فإن نور البصر يقع على نور الله تعالى قبل أن يقع على نور المخلوقات لكن نوره سبحانه لطيف لا تدركه الأبصار فيقتصر نور البصر على رؤية الموجودات ولا يرى نور الله تعالى الذي أظهر الموجودات ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي هذه المعاني قال الإمام الغزالي رضي الله عنه :</span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">الله أكبر ما في الدار ديار &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; وإنما هي نيران وأنوار لقد أماطت سليمى عن براقعها &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; فوجهها مشرق والطرف سحار &nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فسبحان من أظهر الأشياء من ظلمة العدم بنوره جل وعلا ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهذا قوله صلى الله عليه وسلم :[ أعوذ بنور وجهك الذي أضاءت له السماوات والأرض وأشرقت له الظلمات ] &nbsp; عزاه السيوطي في الجامع الصغير للطبراني عن عبد الله بن جعفر أي : ظلمات العدم التي أشرق عليها نور الله فظهرت .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد ذكر سبحانه في هذه الآية نور الإيجاد ونور الإمداد فقال تعالى : { &nbsp;اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ مَثَلُ نُورِهِ كَمِشْكَاةٍ فِيهَا مِصْبَاحٌ } .. الآية &nbsp;أما نور الإيجاد فهو المراد من قوله تعالى : { اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ } &nbsp;أي : أوجد وأظهر سبحانه السماوات والأرض بنوره ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكذلك سائر الموجودات كالعرش والكرسي وما هنالك إنما وجدت بنوره سبحانه ولكنه اقتصر على ذكر السماوات والأرض لأنها مرئية مشهودة للعيان لا ينكر وجودها عاقل .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما نور الإمداد فهو المراد من قوله تعالى :{ مَثَلُ نُورِهِ كَمِشْكَاةٍ } &nbsp;وهاء الضمير في قوله تعالى :{ نُورِهِ } لا يعود إلى النور الأول بل إلى معنى آخر وهو معروف في علم البلاغة بالاستخدام .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والمعنى : { مَثَلُ نُورِهِ } أي نور الإمداد الإيماني في قلب عبده المؤمن كمشكاة .. وهذا النور خاص بالمؤمنين فقط .. وجهه سبحانه على قلوب المؤمنين فآمنوا بالله تعالى ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن فقد نور الإمداد ولم يفقد الاستعداد لتقبله فعليه أن يتوجه إلى النور فينال منه ويستمد .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما من فقد الاستعداد لتقبل النور فلا يفيده النور وإن توجه إليه لأنه لا استعداد عنده ولا قابلية لتلقي النور .. كالمرآة والخشبة والحجرة فترى أن المرآة لما يتوجه عليها النور تظهر فيها الأشياء لتقبلها للنور .. وأما الخشبة وغيرها فلا تعكس النور .. مع أن النور توجه إلى الكل على حد سواء ولم يظلم أحداً منها ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولذلك فإن القلوب المستعدة لتقبل النور الإلهي قبلته وعرفت ربها وآمنت بالله تعالى .. قال تعالى :{ أَفَمَنْ شَرَحَ اللَّهُ صَدْرَهُ لِلْإِسْلَامِ فَهُوَ عَلَى نُورٍ مِنْ رَبِّهِ } وقال سبحانه :{ فَمَنْ يُرِدِ اللَّهُ أَنْ يَهْدِيَهُ يَشْرَحْ صَدْرَهُ لِلْإِسْلَامِ } &nbsp;وقوله تعالى :{ فَهُوَ عَلَى نُورٍ مِنْ رَبِّهِ } أي : هو نور الإيمان فعرفوا الله تعالى بنوره ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما قلوب الكافرين فقد توجه إليها النور ولكنها لم تقبله لعدم استعدادها لتلقيه فلم يظهر فيها نور الله تعالى كما لم تظهر الأشياء في الخشبة لما توجه عليها النور .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال تعالى :{ وَمَا ظَلَمَهُمُ اللَّهُ وَلَكِنْ كَانُوا أَنْفُسَهُمْ يَظْلِمُونَ } &nbsp;ونسأل الله تعالى أن يثبت علينا إيماننا وأن يحيينا مؤمنين ويميتنا مؤمنين ويحشرنا مؤمنين في زمرة سيدنا محمد سيد المرسلين صلى الله عليه وسلم وأن يدخلنا في قوله تعالى :{ يَوْمَ لَا يُخْزِي اللَّهُ النَّبِيَّ وَالَّذِينَ آمَنُوا مَعَهُ }&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ونقرأ الفاتحة على هذه النية ، ثم استأنف رضي الله عنه &nbsp;حديثه فقال : إن أول مرآة تقبلت النور عن الله تعالى هو سيدنا محمد صلى الله عليه وسلم وذلك لأن نور الحق قوي قاهر باهر لا يثبت أمامه إلا من خصه الله تعالى بقوة قابلية عالية وأعده وأمده لذلك وهذا هو سيدنا محمد صلى الله عليه وسلم وهذا ما يعرف عند أهل الله تعالى بـ [ الحقيقة المحمدية ] أو الحقيقة الكلية &nbsp;أو الحقيقة الجامعة ، وتسمى أحياناً [ كل شيء ] ، والمجلى الأول الذي تجلت وظهرت فيه أنوار الله تعالى .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وعن قلب رسول الله صلى الله عليه وسلم ومرآته استمدت قلوب المؤمنين واستفاضت النور .&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأخذ كل مؤمن على قدره واستعداده ، والفضل الأول لسيدنا محمد صلى الله عليه وسلم الذي قال : [ إنما أنا قاسم والله يعطي ] &nbsp; صحيح البخاري كتاب العلم عن معاوية رضي الله عنه والقسمة تكون على حسب الرتبة ، ولا يمكن لأحد أن يستغني عن سيدنا محمد صلى الله عليه وسلم لا من الأولين ولا من الآخرين . ولا يمكن لأحد أن يتلقى عن الله جل وعلا مباشرة إلا من واسطة سيدنا محمد صلى الله عليه وسلم .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولو أمكن ذلك لأحد لخرج عن الأمر باتباعه صلى الله عليه وسلم في جميع ما جاء عنه ولا يستثنى من الأمر باتباعه صلى الله عليه وسلم أحد . ولو أمكن ذلك لأحد لأمكنه دخول الجنة بمفرده دون أن يدخل وراء رسول الله صلى الله عليه وسلم ولا يمكن ذلك لأحد ، فهو صلى الله عليه وسلم أول شافع ومشفع وأول من يدخل الجنة والناس من ورائه على حسب مراتبهم .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد لفت سبحانه قلوب عباده للسؤال عنه والفهم عنه لفتهم في ذلك وأحالهم إلى سيدنا محمد صلى الله عليه وسلم فمن ذلك : قوله تعالى :{ وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي لَعَلَّهُمْ يَرْشُدُونَ } &nbsp;ولم يقل سبحانه : وإذا سأل عبادي عني ، وهم العباد أهل القرب والطاعة لله تعالى نسبهم إليه سبحانه تشريفاً وتكريماً لهم مع أن الخلق كلهم عباده سبحانه .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما قوله تعالى :{ وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ } فهو خطاب عام لجميع الناس بما فيهم الكافرين . ولو دعا الكافر ربه أجابه . وذلك في أمور نفسية أو دنيوية .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما قوله تعالى :{ وَمَا دُعَاءُ الْكَافِرِينَ إِلَّا فِي ضَلَالٍ } فهو في أمور الآخرة وقد أثبت سبحانه للكافرين رجاء منه فقال تعالى :{ وَتَرْجُونَ مِنَ اللَّهِ مَا لَا يَرْجُونَ } فلهم رجاء من الله تعالى ودعاء لله تعالى لكنهم يجابون في أمور الدنيا وأموالها فقط لا في مراتب الآخرة وأحوالها .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقوله تعالى :{ وَقَالَ رَبُّكُمُ } وهو رب كل المخلوقات سبحانه .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ ادْعُونِي أَسْتَجِبْ لَكُمْ } وإجابته للمؤمنين من باب أولى . وأما قوله تعالى :{ وَإِذَا سَأَلَكَ عِبَادِي عَنِّي } أضاف إليه سبحانه عباده المقربين إضافة تشريف وتكريم على غيرهم .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقوله تعالى :{ وَإِذَا سَأَلَكَ } أي : أنت يا رسول الله أنت المسؤول عني والجواب سيأتيك مني لتبلغهم إياه .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما أن أحداً يسأل الحق مباشرة فلا يمكن ذلك . فهو صلى الله عليه وسلم الواسطة في سؤال الخلق لله تعالى وهو واسطتهم في جواب الحق تعالى لهم &nbsp;وهكذا لا تنكر واسطته صلى الله عليه وسلم في كل الأمور .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قوله تعالى :{ فَإِنِّي قَرِيبٌ } أي : بالقرب المنزه اللائق به جل وعلا فليس هو قرباً زمانياً كأن تقول : فلان قريب مني وبيني وبينه ساعتا زمن ، وليس هو قريباً مكانياً كأن تقول : فلان قريب مني وبيني وبينه كذا من المسافة مثلاً .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما قرب العبد من الله تعالى فهو قرب قلبي بمعنى أن يشعر العبد أن قلبه قريب من الله تعالى .&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما قربه سبحانه من العبد فلا مثيل له . بل هو قرب من ليس كمثله شيء فقربه ليس كمثله قرب ، وهكذا سبحانه في سائر صفاته وشؤوناته .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي الآية الكريمة يقول سبحانه :{ وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ } &nbsp;فهو سبحانه أقرب إليك منك ، ومن هنا تفهم أن قربه سبحانه قرب مطلق ، &nbsp;ولو كان قرباً حسياً مادياً فإن أقرب شيء من الإنسان هو حبل الوريد .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قوله تعالى :{ فَلْيَسْتَجِيبُوا لِي وَلْيُؤْمِنُوا بِي } أي : عليهم أن يستجيبوا لدعائي لهم بالطاعة فأجيب دعائهم ، &nbsp;فهم يدعونني وأنا أدعوهم .&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فإن أجابوني لما دعوتهم أجبتهم فيما دعوا ، وأما دعوة الله لعباده فهي بقوله سبحانه :{ يَا أَيُّهَا الَّذِينَ آمَنُوا اسْتَجِيبُوا لِلَّهِ وَلِلرَّسُولِ إِذَا دَعَاكُمْ لِمَا يُحْيِيكُمْ } &nbsp;ومن استجاب دعوة الله ورسوله صلى الله عليه وسلم كانت إجابة الله لدعائه مضمونة ، وأما من قصر في ذلك فقد يستجيب سبحانه دعاءه وقد لا يستجيب .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما تقدم يتبين للإنسان أن سيدنا محمداً صلى الله عليه وسلم هو الواسطة الكبرى بين الحق والخلق وهو المقصود بقولهم [ الحجاب الأعظم ] إذ ليس كل حجاب حاجباً فقد يكون الحجاب نوراً كما في الحديث :[ حجابه النور &nbsp;] طرف حديث في صحيح مسلم كتاب الإيمان . والنور لا يحجب .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما سيدنا محمد صلى الله عليه وسلم فهو الحجاب الأعظم بمعنى أنه صلى الله عليه وسلم الواسطة بين الحق والخلق الذي يتلقى عن الله ويفيض على خلق الله وهو الناطق عن الله تعالى والمبلغ عن الله تعالى وهكذا لأن الخلق لا يمكنهم الأخذ من الله تعالى مباشرة لعدم الاستعداد والقابلية فيهم كما تقدم &nbsp;وليعلم كل واحد فينا أن كلام العارفين رضي الله عنهم كلام ذو معان شرعية ولا نقص ولا خلل فيه على من تفهمه بموجب المعاني الشرعية .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما يحكى في هذا الباب أن رجلاً مسرفاً على نفسه بتضييع عمره في القيل والقال ، وكان له قصر مشرف على الطريق ، وهذا في عهد الخلافة العباسية ، فقال في نفسه : سأجلس على الشرفة وأكتب كلام كل من يمر بهذا الطريق ثم أنظر في منظومة ما كتبت&nbsp; ففعل ذلك ، فمر رجل يبيع خلاً وينادي : خل خل فكتب : خل ومر آخر يقول لصاحبه : درج أمير المؤمنين له شأنه وجماله فكتب : درج أمير المؤمنين ، ثم نظر الرجل فيما كتب [ خل درج أمير المؤمنين ] &nbsp;فلم يجد لما كتب معنى ولا مناسبة ولا فائدة بل كان خلطاً .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فمن الناس من يقرأ كتب العارفين رضي الله عنهم ويظن أن كلامهم&nbsp; [ خل درج أمير المؤمنين ] لأنه لا يفهم من كلامهم شيئاً وربما فهم غير المراد فتكون المصيبة أعظم .&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وما درى هذا الأحمق أنه هو الذي يخلط في فهمه وأنه ليس في كلامهم رضي الله عنهم خلط ، ونقص كبير في حق العالم أن يقول : أنا أعلم كل شيء ، فقد يعلم أموراً في علوم معينة وتغيب عنه علوم أخرى .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فما بال من يدعي العلم في زمننا يتناول أحدهم كتب القوم العارفين رضي الله عنهم ويفهم منها ما لا يتفق فهمه مع نصوص الكتاب والسنة .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد يتهم العارفين بكلام هم منه براء . كل ذلك لعدم أهلية من قرأ كتبهم وقلة علمه وعدم اطلاعه الواسع على أحاديث رسول الله صلى الله عليه وسلم وعدم اطلاعه على مصطلحات الصحابة ، لأن علومهم كلها مقيدة بالكتاب والسنة كما جاء ذلك عن الإمام الجنيد رضي الله عنه .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وليعلم كل مؤمن أن الذي أعطاه الله العلوم كلها هو سيدنا محمد صلى الله عليه وسلم الذي قال : [ فتجلى لي كل شيء وعرفت ] &nbsp;طرف حديث في &nbsp;سنن الترمذي كتاب تفسير القرآن عن معاذ بن جبل رضي الله عنهما . أي : من علوم تتعلق بهذا الكون من عالم العرش إلى الفرش .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما تولى سيدنا علي رضي الله عنه &nbsp;الخلافة سأله رجل عن مسألة فقال له سيدنا علي رضي الله عنه &nbsp;: لا علم لي بها ، فقال له الرجل : هذا مكان من يعلم ، وكان رضي الله عنه قد وقف على المنبر يخطب في الناس ، فقال سيدنا علي رضي الله عنه &nbsp;: هذا مكان من يعلم شيئاً ولا يعلم أشياء . أما من يعلم كل شيء فلا مكان له . أي : وهو الله جل وعلا ، فسكت الرجل وكان في قلبه مرض وانصرف .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد قال العلماء رضي الله عنهم : يتحتم على العالم مهما عظم علمه أن يعلم تلامذته قوله [ لا أدري ] حتى قال بعضهم : [ نصف العلم لا أدري ] ثم إن رجلاً سأل الشيخ الإمام رضي الله عنه &nbsp;: هل تعتبر نفس ابن آدم شيئاً ؟ فقال الشيخ الإمام رضي الله عنه &nbsp;: إن كلمة النفس تطلق على معان ويعرف كل معنى من سياق البحث ، فقد تطلق كلمة النفس على ذات الشيء كما تقول : رأيت فلاناً بنفسه ، أي : بذاته.</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تطلق على الروح الإنساني كما في قوله تعالى :{ اللَّهُ يَتَوَفَّى الْأَنْفُسَ حِينَ مَوْتِهَا } أي : يقبض الأرواح .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تطلق النفس في علم التصوف الأخلاقي العملي على مرتبة من المراتب التي وصل إليها الإنسان في سيره وسلوكه إلى الله تعالى ، ومنها النفس الأمارة والنفس اللوامة والنفس المطمئنة .. الخ ..</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن هذا تفهم قوله صلى الله عليه وسلم في الجهاد الأكبر أنه جهاد نفس [عن جابر قال : قدم على النبي صلى الله عليه وسلم قوم غزاة فقال : قدمتم خير مقدم ، قدمتم من الجهاد الاصغر إلى الجهاد الاكبر مجاهدة العبد هواه ، عزاه في كنز العمال للديلمي والخطيب &nbsp;] &nbsp; أي تهذيبها وتطهيرها من النقائص والرذائل ، وتحليتها بالفضائل والمكارم التي جاء بها رسول الله صلى الله عليه وسلم . والنفس المطمئنة هي التي اطمأنت على شرع الله تعالى وأقامت عليه وسكنت ولم تضطرب .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">روى الحاكم وغيره عن سعيد بن جبير قال : &laquo; مات ابن عباس بالطائف ، فشهدت جنازته ، فجاء طير لم ير على خلقته ودخل في نعشه فنظرنا وتأملنا هل يخرج فلم ير أنه خرج من نعشه ، فلما دفن تليت هذه الآية على شفير &nbsp;القبر ، ولا يدرى من تلاها : يا أيتها النفس المطمئنة ارجعي إلى ربك راضية مرضية فادخلي في عبادي وادخلي جنتي &nbsp; المستدرك كتاب معرفة الصحابة والمعجم الكبير للطبراني وهذه النفس التي أمر الله تعالى بتزكيتها هي التي ذكرها سبحانه بقوله : &nbsp;{ وَنَفْسٍ وَمَا سَوَّاهَا فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا &nbsp;قَدْ أَفْلَحَ مَنْ زَكَّاهَا } أي : سعى في تطهيرها .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان صلى الله عليه وسلم يدعو بقوله :[ اللهم آت نفسي تقواها وزكها أنت خير من زكاها أنت وليها ومولاها ] &nbsp;صحيح مسلم كتاب الذكر والدعاء والتوبة عن زيد بن أرقم رضي الله عنه .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا يدخل الجنة إلا من زكى نفسه كما قال تعالى : { جَنَّاتُ عَدْنٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَذَلِكَ جَزَاءُ مَنْ تَزَكَّى }&nbsp; أي : من تطهر من الرعونات النفسية ودعاوى الأنانية وروائح الربوبية من التكبر والتجبر .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">روى أبو داود وغيره عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم : قال الله عز وجل : &quot; الكبرياء ردائي ، والعظمة إزاري &ndash; وفي رواية : العز إزاري - &nbsp;، فمن نازعني واحدا منهما ، قذفته في النار &nbsp; الأدب المفرد للبخاري وشعب الإيمان للبيهقي - سنن أبي داود كتاب الباس وسنن ابن ماجه كتاب الزهد ولذلك نجد أن منهاج الصوفية أهل السير والسلوك إلى الله تعالى يقوم على تهذيب النفس ، فبحثوا في رعونات النفس وأمراضها وبينوا طرق تهذيبها ورياضتها وتزكيتها ، وصنفوا في ذلك كتباً كثيرة ، كل ذلك حتى تطهر نفس المؤمن وتطيب فلا يصدر منها إلا الخير وتصير أهلاً لأن تحل في مقعد صدق عند مليك مقتدر .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومتى تحقق الإنسان بحقيقته التي هي صفة العبودية لله تعالى والذل والانكسار له سبحانه فقد سلك طريقاً سريعاً في التقرب إلى الله تعالى وإن قصر في فعل النوافل ، لأن من أكثر من النوافل والطاعات وهو يرى في نفسه أنه على شيء ، وأنه ذلك الرجل صاحب الأذكار والأوراد وأعجب من نفسه فهيهات له أن يصل إلى ربه جل وعلا .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن ذلك يفهم الإنسان ما قيل لأبي يزيد البسطامي رضي الله عنه &nbsp;لما سأل الله تعالى : بم يتقرب إليه ؟ &nbsp;قيل له : [ تقرب إلي بما ليس في ].&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أي : بصفة ليست لله تعالى وهي صفة الذل والانكسار لله تعالى لا بالعزة والاستكبار التي هي من صفات الرب جل وعلا . فالتقرب إلى الله تعالى لا يكون إلا بصفة العبد التي لا تفارقه وهي حقيقته في العبودية والذل والافتقار والانكسار لله رب العالمين لا بصفة الرب التي ليس للعبد حق فيها .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن هنا يفهم الإنسان قول رسول الله صلى الله عليه وسلم : [ لا يدخل الجنة من كان في قلبه مثقال ذرة من كبر ] &nbsp;صحيح مسلم كتاب الإيمان عن عبد الله بن مسعود رضي الله عنهما . &nbsp;أي : حتى يطهر منه وتلين نفسه ولو بغمسة في جهنم عافانا الله من ذلك كله ، وإن فيما جرى لإبليس لعنه الله تعالى عبرة لكل إنسان ، فلقد بين سبحانه سبب شقاوة إبليس وطرده له من رحمته سبحانه وذلك هو إعجابه بنفسه وتكبره .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فلقد كان إبليس من عباد الجن ولم يترك مكاناً في الأرض إلا وسجد فيه لله تعالى ، حتى استأذن الله تعالى أن يسجد له في السماء بين صفوف الملائكة فأذن له سبحانه ، فلما جاء أمر الله تعالى للملائكة بالسجود لآدم عليه السلام ، وجاء الأمر الإلهي لإبليس خاصة بالسجود كما في قوله تعالى :{ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ } &nbsp;امتنع إبليس عن السجود بسبب كبره ، وأظهر ما أضمره في نفسه من الأنانية وأنه خير من آدم واعترض على حكمة الله تعالى في ذلك وكان ذلك سبب طرده وشقائه الأبدي . نسأل الله العافية .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد ذكر سبحانه هذه القصة لخلقه مع أنها جرت قبل أن يخلقهم وذلك لتكون لهم عبرة ، وليعلموا ويوقنوا أن التكبر والتعالي ليس من صفات العبد وأن مصيره إلى الهلاك إن هو ادعى ما ليس له .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم استأذن أحد القائمين على الجلسة بتقديم الحلوى للزائرين فأذن له الشيخ الإمام رضي الله عنه &nbsp;وجعل الشيخ الإمام يرحب بالحاضرين ويبارك لهم في العيد .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم سأله بعض أهل العلم المتقدمين في السن : هل يجوز التكبر على المتكبر؟ فقال الشيخ الإمام رضي الله عنه &nbsp;: نعم يجوز فقط في سياق الإغلاظ عليهم بعد دعوتهم وإقامة الحجة عليهم وإفحامهم بالحجة والبرهان .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما في مجال الدعوة فتكون بلين الكلام واللطف والموعظة الحسنة ، كما قال تعالى لسيدنا موسى عليه السلام لما أرسله إلى فرعون وأرسل معه هارون : { فَقُولَا لَهُ قَوْلًا لَيِّنًا لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى } ، وكان هذا الأسلوب اللين بأسلوب العرض وعدم التعنيف فقال كما بين تعالى :{ هَلْ لَكَ إِلَى أَنْ تَزَكَّى وَأَهْدِيَكَ إِلَى رَبِّكَ فَتَخْشَى } ، ولم يقل له : زك نفسك ، أو غير ذلك مما فيه صيغة الأمر والشدة ثم جرت عدة مناظرات بين موسى عليه السلام وفرعون وملئه ، وظهر صدق موسى عليه السلام وأقام عليه الحجة بدعوته إلى الله تعالى لكن فرعون أبى واستكبر فلجأ موسى عليه السلام إلى أسلوب التهديد والقوة وألقى عصاه وكان ما كان &nbsp;وقد قال تعالى في بيان الإغلاظ على الكافرين المعاندين بعد أن أعرضوا عن دعوة رسول الله صلى الله عليه وسلم :{ يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ } الآية.</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال تعالى :{ يَا أَيُّهَا الَّذِينَ آمَنُوا قَاتِلُوا الَّذِينَ يَلُونَكُمْ مِنَ الْكُفَّارِ وَلْيَجِدُوا فِيكُمْ غِلْظَةً } ، ومجمل القول أنك إذا دعوت فلاناً وأحسنت إليه وألنت له الكلام لكنه قابلك بالغلظة والتكبر وفحش الكلام ، فلا حرج عليك بعد ذلك أن تغلظ عليه في الكلام من باب المقابلة ، ومن المؤسف في زمننا أنك ترى بعض أدعياء العلم أو أدعياء التصوف يتكبرون على غيرهم من المؤمنين بدعوى أنهم ليسوا من طريقتهم أو غير ذلك ويترفعون عليهم ، وقد يمر أحدهم ولا يسلم على فلان ترفعاً وتكبراً عليه ، وإذا سألته عن سبب ذلك يزعم أن عزة العلم تحتم عليه ذلك !! ، وما درى هذا الأحمق أن التواضع للمؤمنين هو تواضع لله تعالى لأنك إذا تواضعت للمؤمن إنما تواضعت له بسبب إيمانه بالله تعالى لا لماله أو جاهه وقد وصف سبحانه أصحاب رسول الله صلى الله عليه وسلم الذين هم صدر هذه الأمة وقد تحققوا بأوامر الله تعالى على مشهد ومسمع من سيدنا رسول الله صلى الله عليه وسلم ، قال تعالى : { مُحَمَّدٌ رَسُولُ اللَّهِ وَالَّذِينَ مَعَهُ أَشِدَّاءُ عَلَى الْكُفَّارِ رُحَمَاءُ بَيْنَهُمْ } ، وقال تعالى :{ وَاخْفِضْ جَنَاحَكَ لِلْمُؤْمِنِينَ } .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وليعلم كل مؤمن أن في نفسه استعداداً لدعوى فرعون إن هو لم يوقف نفسه عند حدود الشريعة ، فلابد لفرعون النفس من موسى الشريعة ، أي : لابد لمعالجة دعاوى النفس بالأنانية والكبر والتعالي من إيقافها عند أوامر الشريعة حينئذ تطهر وتطيب ، والموسى في اللغة : القاطع ، وقد قال العارفون رضي الله عنهم : النفس حية تسعى ما دامت حية تسعى ولذلك جاءت العبادات الشرعية تعبد النفس أي تذللها لربها جل وعلا ، كي تتواضع للمؤمنين من خلق الله تعالى كما قال تعالى :{ أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ } ، أما كلمة [ الصوفية ] فقيل : إنها مأخوذة من الصوف وذلك لأن جل لباس الصحابة رضي الله عنهم كان من الصوف مع أنهم قد فتحوا البلاد وغنموا الغنائم الكبيرة بما فيها من الحرير والخز والذهب والفضة ، وأما لباس الصوف فيكسب النفس خشوعاً وتعوداً على الخشونة ويحمل النفس على الزهد في زخارف الدنيا .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد كان الحسن البصري رضي الله عنه &nbsp;، وهو من كبار التابعين وعلمائهم وزهادهم وقد اجتمع بعدد كبير من أصحاب رسول الله صلى الله عليه وسلم ، قال للتابعين : والله لقد أدركت سبعين بدريا &ndash; أي : من أصحاب رسول الله صلى الله عليه وسلم الذين حضروا غزوة بدر- &nbsp;أكثر لباسهم الصوف ولو رأيتموهم قلتم : مجانين - أي : لشدة زهدهم وكثرة عباداتهم وذكرهم لله تعالى &nbsp;- ، ولو رأوا خياركم لقالوا : ما لهؤلاء من خلاق ، ولو رأوا شراركم لقالوا : ما يؤمن هؤلاء بيوم الحساب &nbsp; انظر حلية الاولياء لأبي نعيم ولقد نال الإمام الحسن البصري رضي الله عنه &nbsp;ذلك المبلغ العظيم في العلم والمعرفة والتقى والورع بسبب نفحة من بيت النبوة المحمدية بواسطة أم المؤمنين زوج النبي صلى الله عليه وسلم السيدة أم سلمة رضي الله عنها ، فلقد كانت أم الحسن مملوكة للسيدة أم سلمة رضي الله عنها فأعتقتها وزوجتها وأنجبت الحسن ، فكانت تتردد على بيت السيدة أم سلمة رضي الله عنها ، وربما أرسلتها السيدة أم سلمة في بعض حاجاتها وتركت ولدها الحسن عند السيدة أم سلمة فإذا بكى أخذته السيدة أم سلمة إلى صدرها وربما أرضعته فنهل رشحات أمدته بالأسرار والأنوار حتى بلغ ذلك المقام ، ولقد جاء عن عدة من الصحابة قولهم للتابعين ، ومنهم أنس وأبو سعيد الخدري &nbsp;رضي الله عنهما : إنكم لتعملون أعمالاً ، هي أدق في أعينكم من الشعر ، إن كنا لنعدها على عهد النبي صلى الله عليه وسلم من الموبقات &nbsp;! صحيح البخاري كتاب الرقاق فانظر أيها المؤمن في الفرق الكبير بين ما كان عليه الصحابة رضي الله عنهم وبين التابعين الذين هم بعدهم في القرون مباشرة !! فما بال بعض العابدين في زمننا يظنون في أنفسهم أن ما بينهم وبين مقام الصحابة إلا الشيء اليسير ، وربما ظن أحدهم في نفسه أنه كالصحابة في الفضل ، وما هذا إلا جهل في مقام الصحابة رضي الله عنهم الذين هم تعلموا وتربوا وزكت نفوسهم بتعليم سيدنا رسول الله صلى الله عليه وسلم وتربيته لهم ، وشهد لهم سبحانه بالصدق والإخلاص فقال تعالى : { يَبْتَغُونَ فَضْلًا مِنَ اللَّهِ وَرِضْوَانًا }فعلى كل مؤمن أن يعرف حده ، ولا يدعي ما ليس عنده ، ونسأل الله تعالى أن يستر أصلح صالح فينا ولا يؤاخذنا على ما صدر منا .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد سأل بعض الصالحين ربه أن يلحقه بغبار الصالحين ، أي : فلا يفارقهم أبداً لأن الركب حين يمشي يتطاير الغبار من حوله .</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وليعلم كل مؤمن أن الموازين في الآخرة على ثلاث مراتب : منها موازين الأعمال ومنها موازين لكتب الأعمال ومنها موازين لذوات الأشخاص وهو ميزان اعتبار الرجال في الكمال ، ومن ذلك قوله تعالى في الكافرين : { فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا } ، وفي الحديث الذي رواه الشيخان عن أبي هريرة رضي الله عنه ، عن رسول الله صلى الله عليه وسلم قال : &quot; إنه ليأتي الرجل العظيم السمين يوم القيامة ، لا يزن عند الله جناح بعوضة ، وقال : اقرءوا ، فلا نقيم لهم يوم القيامة وزنا &quot;] &nbsp; صحيح البخاري كتاب تفسير القرآن وصحيح مسلم كتاب صفة القيامة والجنة والنار &nbsp;ونسأل الله تعالى أن يجعل موازيننا ثقيلة كما علمنا رسول الله صلى الله عليه وسلم في دعائه :[ وثقل موازيني ] &nbsp; طرف حديث في مستدرك الحاكم عن أم سلمة رضي الله عنها . &nbsp;اللهم آمين ، وخلاصة القول أن الإنسان عبد لله في حقيقته وصفاته فعليه أن يعترف مع نفسه بذلك ، وأن لا يجاوز حد العبودية فيستريح ويسعد ، وأما من جاوز حده وادعى ما ليس عنده فقد عرض نفسه للشقاء والعناء ومثال ذلك أن الله تعالى خلق للإنسان أعضاء ومدارك وجعل لكل منها وظيفة فمن صرف كل عضو في وظيفته التي خلقه الله تعالى لها فقد استراح ، ومن تصرف في عضو خلاف وظيفته أتعب نفسه وأتعب أعضاءه أيضاً .&nbsp;</span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : ثم انقطع التسجيل ولم نتمكن من إتمام بقية كلام الشيخ الإمام رضي الله عنه .</span></span></p>', 'default.png', 1, 20721, 0, 1, 0, 1, 1, '2009-12-22', 0, 1, 0, '', '', '', '0', 1);
COMMIT;

