-- ----------------------------
-- Table structure for st_article_vote
-- ----------------------------
DROP TABLE IF EXISTS `st_article_vote`;
CREATE TABLE `st_article_vote` (
  `vote_id` int(8) unsigned NOT NULL AUTO_INCREMENT,
