-- ----------------------------
-- Table structure for st_pages
-- ----------------------------
DROP TABLE IF EXISTS `st_pages`;
CREATE TABLE `st_pages` (
  `pages_id` int(8) unsigned NOT NULL AUTO_INCREMENT,
  `pages_menus` int(8) NOT NULL DEFAULT '0',
  `pages_title` varchar(100) NOT NULL DEFAULT '',
  `pages_content` text,
  `pages_lan` varchar(10) NOT NULL DEFAULT 'ar',
  `pages_visitor` int(8) unsigned NOT NULL DEFAULT '0',
  `pages_priority` tinyint(8) DEFAULT NULL,
  `pages_date` date NOT NULL DEFAULT '0000-00-00',
  `pages_active` tinyint(1) unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`pages_id`),
  KEY `pages_id` (`pages_id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of st_pages
-- ----------------------------
BEGIN;
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (30, -2, 'اتصل بنا', '<p dir=\"rtl\"><span style=\"font-size:14px\"><span style=\"font-family:shadows-it,tahoma\"><strong>لمزيد من المعلومات , الرجاء ملئ النموذج التالي</strong></span></span></p>', 'ar', 1, 1, '2008-12-27', 0);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (31, 0, 'افتتاحية الموقع', '<p style=\"text-align:justify\"><span style=\"font-size:22px\"><span style=\"font-family:shadows-it\">أهلاً بكم في الموقع الرسمي الوحيد للإمام الشيخ عبد الله سراج الدين، والذي أسسه عام ١٤٣١ هـ ولده المهندس الشيخ محمد محيي الدين رحمهما الله تعالى ورضي عنهما، ونرجو منكم إهداءهما ثواب قراءة سورة الفاتحة.<br />\r\nوندعوكم إلى تحميل كتب الشيخ الإمام بشكل سهل ومباشر مِن<span style=\"color:#c0392b\"> </span><a class=\"LINK\" href=\"index.php?page=Ym9va19jYXRlZ29yeQ==&amp;op=ZGlzcGxheV9ib29rX2NhdA==&amp;id=MQ==&amp;lan=YXI=\"><span style=\"color:#e74c3c\">هذا الرابط</span></a><span style=\"color:#FF000\"> </span>&nbsp;<br />\r\nكما ندعوكم إلى تحميل أبحاث مختارة -عدد صفحاتها قليل ويَكْثُرُ السؤال عنها- اخترناها لكم من مؤلفات الشيخ الإمام رضي الله عنه، وهي في <a class=\"LINK\" href=\"index.php?page=Ym9va19jYXRlZ29yeQ==&amp;op=ZGlzcGxheV9ib29rX2NhdA==&amp;id=Mg==&amp;lan=YXI=\"><span style=\"color:#e74c3c\">هذا الرابط</span></a><span style=\"color:#FF000\"> </span>&nbsp;<br />\r\nونرجو مِن مواقع تحميل الكتب ومِن القراء أيضاً نشر عِلم الشيخ الإمام لِيَعُمَّ النفع، فالدال على الخير له مثل أجر فاعله .</span></span></p>\r\n\r\n<p style=\"text-align:left\"><span style=\"font-family:shadows-it\"><span style=\"font-size:22px\">مدير الموقع: الشيخ عبد الله محمد محيي الدين سراج الدين</span></span></p>\r\n\r\n<p style=\"text-align:left\"><span style=\"font-family:shadows-it\"><span style=\"font-size:22px\">المشرف العام: الدكتور بكري بريمو السمان&nbsp;</span></span></p>', 'ar', 0, 10, '2019-04-19', 0);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (32, 46, 'ولادته ونشأته العلمية', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولد الشيخ الإمام سيدي الوالد عبد الله بن محمد نجيب سراج الدين &nbsp;رضي الله عنه &nbsp;في بيت عرف ببيت الفضل والكرم والعلم وذلك لما اشتهر عن والده &nbsp;رضي الله عنه &nbsp; بحلِ &nbsp;المعضلات العلمية وبيان ما التبس فهمه واشتبه أمره من العلوم والمعارف العالية &nbsp;حيث إن كبار علماء ذلك الوقت كانوا يقصدونه فإذا قال لهم قولاً أذعنوا له وكان قوله هو القول الفصل ، ولذلك كانوا يتساءلون فيما بينهم : ماذا قال الشيخ محمد نجيب في ذلك ؟<br />\r\n&nbsp;رضي الله عنه ونفعنا الله بعلومه وبركاته .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد عرف عن الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;علو المكانة ورفعة المقام والمنزلة في قلوب أهل عصره فقد درج على ألسنة كثير منهم كلمات التكريم والتعظيم لمقام الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;إن هم ذكروه أو سمعوا شيئاً من كلامه أو عن مناقبه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">في هذا البيت العامر باليمن والبركة المشهور بالعلم والمعرفة كانت ولادة مولانا الإمام الشيخ عبد الله &nbsp;رضي الله عنه &nbsp;سنة / 1342/ للهجرة الشريفة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي هذا البيت الفاضل المعروف بالنسب والحسب نشأ شيخنا الإمام &nbsp;رضي الله عنه &nbsp;وتربى في أحضان والده العارف الكبير الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;ووالدته السيدة خديجة المكتبي بنت الشيخ وحيد المكتبي الذي استشهد في أيام الحرب العالمية الأولى فكفلها عمها العلامة الكبير فقيه عصره السيد الشيخ أحمد المكتبي رحمه الله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد حظي شيخنا الإمام &nbsp;رضي الله عنه &nbsp;منذ صغره بدعوات وبركات من العلماء والأولياء والصلحاء الذين كانوا يزورون مولانا الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;أو يزورهم لأنه كان بصحبته في غالب الأحيان .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تعلم شيخنا الإمام &nbsp;رضي الله عنه &nbsp;تلاوة القرآن الكريم وتجويده في كتاب جامع سليمان الأيوبي عند الشيخ عثمان المصري رحمه الله تعالى ويقع قريباً من دار الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><strong><span style=\"font-family:Lotus\">كما قرأ عند الشيخ المذكور رحمه الله تعالى شيئاً من قواعد اللغة العربية .</span></strong></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما أتقن تجويد القرآن الكريم حبب إليه والده &nbsp;رضي الله عنه &nbsp;استظهار القرآن &ndash; يعني &nbsp;حفظه عن ظهر قلب &ndash; فشرع شيخنا الإمام في ذلك عند الشيخ عبد الوهاب المصري رحمه الله تعالى &nbsp;في كتاب قريب من جامع العثمانية فاستظهر القرآن الكريم وله من العمر اثنتا عشر سنة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان في تلك الفترة يذهب إلى معهد الفلاح في جامع السلطانية الذي كان يديره الأستاذ الكبير الشيخ محمد خير الدين إسبير وقد تعلم في تلك السنوات القراءة والكتابة وتوسع قليلاً في علوم اللغة العربية وحفظ نصوصاً في البلاغة والشعر كقصيدة :[ بانت سعاد ] للصحابي الجليل &nbsp;كعب بن زهير &nbsp;رضي الله عنه &nbsp;وقصيدة البردة للبوصيري رحمه الله تعالى ، وحفظ شيئاً من القصائد والمدائح النبوية كما حفظ طائفة كبيرة من أحاديث المصطفى &nbsp; صلى الله عليه وسلم وكان في ذلك كله يحوز على الدرجة الأولى ويتفوق على من معه بأسبقية شهد بها كل من درسه أو سمع له .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><strong><span style=\"font-family:Lotus\">سلوكه طريق العبادة والتقرب إلى الله تعالى&nbsp;</span></strong></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لقد حبب الله تعالى إليه منذ صغره تلاوة القرآن الكريم وقراءة [ دلائل الخيرات ] في الصلاة على النبي &nbsp; صلى الله عليه وسلم للإمام الجزولي &nbsp;رضي الله عنه &nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبعد أن استظهر القرآن الكريم &nbsp;وهو ابن اثنتي عشرة سنة كان يختم القرآن كل سبعة أيام ختمة وربما في ثلاث خاصة في الأيام الفاضلة كأيام رمضان وعشر ذي الحجة وهكذا لأنه كان أيضاً يراجع محفوظاته من الأحاديث الشريفة وأمهات المتون .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يقرأ كل يوم أيضاً مجموعة الصلوات الإدريسية وهي عدة منظومات في الصلاة على النبي &nbsp; صلى الله عليه وسلم من نظم الإمام العارف بالله تعالى الشيخ أحمد بن إدريس &nbsp;رضي الله عنه &nbsp;وكانت هذه المجموعة وشروحها موجودة في مكتبة والده الإمام الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;وتعجبه كثيراً وينشرح لقراءتها لما فيها من أسرار ومعان عرفانية &nbsp;عالية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم وفقه الله تعالى إلى قراءة أوراد السادة الرفاعية رضي الله عنهم ، خاصة كتاب :( السير والمساعي في أوراد سيدي أحمد الرفاعي ) &nbsp;رضي الله عنه &nbsp;، وكذلك حزب الفرج لسيدي أحمد الرفاعي &nbsp;رضي الله عنه &nbsp;أيضاً .<br />\r\nثم جمع رسالة في الأذكار والأدعية المأثورة عن سيدنا رسول الله &nbsp; صلى الله عليه وسلم في الصباح والمساء ، وكانت هذه من جملة أوراده اليومية &nbsp;رضي الله عنه &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكانت له أوراد في الصلاة على النبي &nbsp; صلى الله عليه وسلم بأعداد كبيرة ، وأوراد خاصة بباقي الطرق : كالطريقة القادرية ، والطريقة البدوية رضي الله عنهم أجمعين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يدير حلقة الذكر بأسلوب يتفق مع جميع الطرق الموصلة إلى الله تعالى ، وذلك ليلة الثلاثاء من كل أسبوع في جامع سليمان الأيوبي ، &nbsp;ثم نقله إلى جامع العثمانية لاتساعه ، بسبب إقبال الناس على حضور حلقة الذكر .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما عن قيامه في الليل للتهجد ، فلم يدعه منذ صغره حتى آخر أيام عمره المبارك ، كما أخبرتنا بذلك الوالدة الكريمة أمدها الله بمدده وعونه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يجهر في قيامه بتلاوة القرآن ، وبالأدعية المأثورة عن سيدنا رسول الله &nbsp; صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وكثيراً ما كان شيخنا الإمام &nbsp;رضي الله عنه &nbsp;يحرض على قيام الليل ويرغب فيه في مجالسه العامة والخاصة ، ويقول :[ لقد دلت أحاديث رسول الله &nbsp; صلى الله عليه وسلم الواردة في ذلك على أن من أراد خير الدنيا والآخرة ، والوصول السريع إلى مقامات القرب من الله تعالى : فعليه بالمواظبة على قيام الليل ، ولو قبيل&nbsp;الفجر بشيء يسير ، لئلا تفوته ساعة التجلي الأكبر على العباد بالجود والعطاء ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;إذا أراد أن يختم القرآن الكريم جمع من كان في البيت من أولاده وأحفاده وشرع في الختم ثم الدعاء ، وذلك عملاً بما جاء عن رسول الله &nbsp; صلى الله عليه وسلم &nbsp;.) وكان &nbsp;رضي الله عنه &nbsp;في السنوات الأخيرة من عمره المبارك يختم القرآن الكريم كل ثلاثة أو أربعة أيام .ويا ليت عين كل مؤمن تنظر إلى تلألؤ وجهه بالبهاء والنور ، خاصة حينما كان يقرأ القرآن أو يدعو الله تعالى .</span></span></span></p>', 'ar', 12194, 10, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (33, 46, 'اطلاعه على دروس والده', '<p style=\"text-align:center; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><img alt=\"\" src=\"/other_files/Image/pic_006.jpg\" style=\"border-style:solid; border-width:0px; height:349px; width:300px\" /></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">الإمام العلامة الشهير والعارف الكبير فضيلة الشيخ محمد نجيب سراج الدين الحسيني ت 1372 هـ</span></span></span></p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><img alt=\"\" src=\"/other_files/Image/pic_005.jpg\" style=\"height:814px; width:600px\" /></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">قال الشيخ الإمام رضي الله عنه :&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وكنت آخر سني دراستي في الخسروية قد استأذنت والدي رضي الله عنه في قراءة دروسه القديمة التي لم ادركها فأذن لي وتناولتها بالقراءة بفهم ودراسة وذلك مما سهل علي فهم مطولات الكتب في علم التوحيد والتفسير وعلوم الحديث وأصوله أيام خلوتي للمطالعة في غرفة والدي في المدرسة الشعبانية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ومما قاله مولانا الشيخ الإمام رضي الله عنه عن دروس والده :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">أن الشيخ محمد نجيب رضي الله عنه كان يكتب دروسه كلها قبل أن يذهب إلى التدريس ويستظهرها ثم يمضي إلى المسجد ليلقيها وربما أتى بشروح إضافية من عنده لإفهام بعض العامة حيث كان درسه عاما وليس للعوام وكان محتوى دروسه بشكل عام يقتصر على علم التوحيد وقضايا الإيمان ودفع الشبهات وإزالة الضلالات وهناك دروس في الجامع الأموي تتضمن شرح أحاديث سيدنا رسول الله صلى الله عليه وسلم التي ذكرها الإمام البخاري في صحيحه وهناك دروس تضمنت أحاديث سيدنا رسول الله صلى الله عليه وسلم التي ذكرها الإمام السيوطي في الجامع الصغير . اهـ</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وقال رضي الله عنه : كان سيدي الوالد رحمه الله تعالى يفتتح دروسه في الجامع الأموي وجامع بانقوسا &ndash; يفتتح ذلك بالصيغة التالية :&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">بسم الله الرحمن الرحيم ، الحمد لله رب العالمين ، وأفضل الصلاة وأكمل التسليم على سيدنا محمد وعلى آله وصحبه أجمعين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">أما بعد :&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">فإن أصدق الحديث كتاب الله تعالى ، وخير الهدي هدي محمد صلى الله عليه وآله وسلم ، وشر الأمور محدثاتها ، وكل محدثة بدعة ، وكل بدعة ضلالة ، وكل ضلالة في النار - هذا الحديث كثيراً ما كان صلى الله عليه وسلم يفتتح خطبه به ، وكان والدي الكريم يفتتح به دروسه إتباعاً له صلى الله عليه وآله وسلم ، واستفتاحاً وتبركاً -&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ثم يقول : بالسند المتصل إلى الإمام الحافظ أبي عبد الله محمد بن إسماعيل بن إبراهيم ابن المغيرة بن بردزبة ، الجعفي البخاري قال &ndash; أي البخاري - : حدثنا عبيد الله بن موسى ، قال : أخبرنا حنظلة بن أبي سفيان ، عن عكرمة بن خالد ، عن ابن عمر رضي الله عنهما قال : قال رسول الله صلى الله عليه وسلم :[ بني الإسلام على خمس : شهادة أن لا إله إلا الله وأن محمداً رسول الله ، وإقام الصلاة ، وإيتاء الزكاة ، وصوم رمضان ، وحج البيت ] ثم يدخل في بحثه العلمي الذي يريد أن يلقيه ، مع ربطه في البحث الذي قبله ، على وجه متسلسل ، ومترابط ومتناسب.&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وكان إذا ختم الدرس وانتهى من البحث يقول : وسيأتي تمام هذا إن شاء الله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">فإذا قال ذلك ، بدأ الناس المستمعون بالصلاة على النبي صلى الله عليه وآله وسلم جهراً ، بصيغة الصلاة الإبراهيمية ثلاث مرات ، ويقولون في آخر كل صلاة : عدد خلقك ، ورضاء نفسك ، وزنة عرشك ، ومداد كلماتك ، كلما ذكرك وذكره الذاكرون ، وغفل عن ذكرك وذكره الغافلون ثم يقولون عشر مرات : لا إله إلا الله &ndash; جهراً .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ثم يسمع الحاج محمود الحاج كريم رحمه الله تعالى الفواتح ، ثم يدعو سيدي الوالد الكريم رحمه الله تعالى ، وبذلك يكون الختام وكان دعاؤه عقب الدروس وفي خطبة الجمعة كما يلي :<br />\r\nاللهم صل على سيدنا محمد وعلى آله وصحبه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">اللهم أيد الإسلام والمسلمين ، وانصر وأعل يا مولانا كلمة الحق والدين .<br />\r\nاللهم ارفع الكرب والشدائد عن أمة سيدنا محمد صلى الله عليه وآله وسلم .<br />\r\nاللهم ارحم أمة سيدنا محمد صلى الله عليه وآله وسلم .<br />\r\nاللهم أصلح أمة سيدنا محمد صلى الله عليه وآله وسلم .<br />\r\nاللهم احفظ أمة سيدنا محمد صلى الله عليه وآله وسلم .<br />\r\nاللهم اغفر للمؤمنين والمؤمنات ، والمسلمين والمسلمات ، الأحياء منهم والأموات .<br />\r\nوصلى الله على سيدنا محمد وعلى آله وصحبه وسلم تسليماً .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ثم يقول سيدي الوالد الكريم رحمه الله تعالى عند انتهائه من الدعاء وراء دروسه :{ سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ } والمستمعون يقولون ذلك مع سيدي الوالد رحمه الله تعالى جهراً وجماعة .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">قلت : وقد بسط الشيخ الإمام رضي الله عنه الكلام حول ذلك مفصلاً في كتابه :&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">حول ترجمة المرحوم الإمام العلامة الشهير والعارف الكبير فضيلة سيدي الوالد الشيخ محمد نجيب سراج الدين الحسيني رضي الله تعالى عنه ، فارجع إليه تجد ما ينفعك إن شاء الله .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وقد أكرمني مولانا الوالد رضي الله عنه بأن أعطاني بعض أوراق دروس والده الكريم مولانا الشيخ محمد نجيب رضي الله عنه - ولم تكن في مجموعها تتجاوز خمس دروس &nbsp;- وأشار علي بكتابتها من جديد وكان موضوعها حول شرح بعض الأحاديث النبوية التي ذكرها الإمام السيوطي في جامعه وبعض أحاديث صحيح البخاري ونبهني إلى بعض التحويلات والاستدراكات التي كان يكتبها الشيخ محمد نجيب رضي الله عنه على جانب الصفحة أو على روقة مستقلة لتلحق بالأصل فكتبتها بقلمي وكان لي صديق يجيد أنواع الخطوط فكتب شيئاً منها بخط جيد حسن، وكان كل ذلك قد حصل في صيف عام 1397 هـ ثم جاورمولانا الشيخ رضي الله عنه &nbsp;في المدينة المنورة وبعد عودته أعطاني بعضاً منها ولم تزل بقية أوراق الدروس بمجموعها محفوظة في مكتبة مولانا الوالد رضي الله عنه &nbsp;وقد رأيت من الفائدة بمكان أن أنسخ صفحة من مخطوطاته التي خطها بيده المباركة رضي الله عنه وهي مكتوبة بقلم من قصب يستمد الحبر من محبرة إلى جانبه إذ لم تكن الأقلام المعروفة حتى ولا الأوراق المعهودة لدينا متوفرة بسهولة وقتئذ وإليك نموذجاً عنها :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">بسم الله الرحمن الرحيم</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">قوله صلى الله عليه وسلم : [ آل القرآن آل الله ] / عزاه السيوطي في الجامع الصغير للخطيب في رواة مالك / &nbsp;أي أهل القرآن هم أهل الله وخاصته أي المتقربون إلى القرآن هم المقربون إلى الله والمراد أن المتقربين إلى القرآن بالمداومة على تلاوته من المصحف أو عن ظهر قلب مع القيام بأوامره والاجتناب عن نواهيه هم المقربون إلى الله وذلك لأن القرآن كلام الله ، وكلام الله تعالى صفته فيكون التقرب إلى كلامه تقرباً إليه ولهذا ورد في الحديث القدسي : [ أنا جليس من ذكرني ] /عزاه في المقاصد الحسنة للديلمي موقوفا على أبي بن كعب / وفي الحديث القدسي &nbsp;يقول الله تعالى : [ أنا عند ظن عبدي بي وأنا معه إذا ذكرني &ndash; وفي رواية مسلم : حين يذكرني - &nbsp;فإن ذكرني في نفسه ذكرته في نفسي وإن ذكرني في ملأ ذكرته في ملأ خير منهم وإن تقرب إلي بشبر تقربت إليه ذراعاً وإن تقرب إلي ذراعاً تقربت إليه باعاً وإن أتاني يمشي أتيته هرولة ]. صحيح البخاري&nbsp;<br />\r\nولاشك أن أفضل الأذكار وآكدها على الإطلاق تلاوة القرآن قال تعالى : { وَهَذَا ذِكْرٌ مُبَارَكٌ أَنْزَلْنَاهُ أَفَأَنْتُمْ لَهُ مُنْكِرُونَ } .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح مسلم أن النبي صلى الله عليه وسلم قال : [ أفضل الكلام بعد القرآن أربع وهن من القرآن : سبحان الله والحمد لله ولا إله إلا الله والله أكبر ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">فأخبر صلى الله عليه وسلم أن هذه الكلمات الأربع أفضل الكلام بعد القرآن ، فيكون القرآن أفضل منها ، كما أنه أفضل من غيرها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وروى الإمام الترمذي وحسنه أن النبي صلى الله عليه وسلم قال : [ يقول الرب سبحانه وتعالى : &nbsp;من شغله القرآن وذكري عن مسألتي أعطيته أفضل ما أعطي السائلين وفضل كلام &nbsp;الله سبحانه وتعالى على سائر الكلام كفضل الله على خلقه ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث الذي رواه السجزي في الإبانة &nbsp;أن النبي صلى الله عليه وسلم قال :[ القرآن أفضل من كل شيىء ، فمن وقر القرآن فقد وقر الله ، ومن استخف بالقرآن استخف بحق الله ، حملة القرآن هم المحفوفون برحمة الله المعظمون كلام الله ، الملبسون نور الله فمن والاهم فقد &nbsp;والى الله ، ومن عاداهم فقد استخف بحق الله عزوجل ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث الذي رواه النسائي وابن ماجه وغيرهما عن أنس رضي الله عنه قال :قال صلى الله عليه وسلم : إن لله عز وجل أهلين من الناس ، قيل من هم يا رسول الله ؟ قال أهل القرآن هم أهل الله وخاصته.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث الذي رواه أبي نعيم في أخبار أصبهان عن أبي هريرة رضي الله عنه قال : قال رسول الله صلى الله عليه وسلم :[ يا أبا هريرة تعلم القرآن وعلمه الناس ولا تزال كذلك حتى يأتيك الموت فإنه إذا أتاك الموت وأنت كذلك حجت الملائكة إلى قبرك كما يحج المؤمنون إلى بيت الله الحرام ] ورواه الخطيب في تاريخه وجاء في الأربعون البلدانية وذكره السبكي في طبقات الشافعية الكبرى</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث الذي رواه الدارمي : [ اقرؤوا القرآن فإن الله لا يعذب قلباً وعى القرآن ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث الذي رواه أبو يعلى ومحمد بن نصر المروزي : [ القرآن غنى لا فقر بعده ولا غنى دونه ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وروى مسلم في صحيحه أن النبي صلى الله عليه وسلم قال : [ اقرؤوا القرآن فإنه يأتي يوم القيامة شفيعاً لأصحابه ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري :[ خيركم من تعلم القرآن وعلمه ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي رواية للبخاري أيضاً : [ إن أفضلكم من تعلم القرآن وعلمه ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري :[ لا حسد إلا في اثنتين رجل آتاه الله القرآن فهو يقوم به آناء الليل وأطراف النهار ، ورجل آتاه الله مالاً فهو ينفقه آناء الليل وأطراف النهار ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري :[ مثل المؤمن الذي يقرأ القرآن مثل الأترجة طعمها طيب وريحها طيب ، ومثل المؤمن الذي لا يقرأ القرآن كمثل التمرة طعمها طيب ولا ريح لها ، ومثل الفاجر الذي يقرأ القرآن كمثل الريحانة ريحها طيب وطعمها مر ، ومثل الفاجر الذي لا يقرأ القرآن كمثل الحنظلة طعمها مر ، ولا ريح لها ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وهذا كله في القارئ العامل بما في القرآن القائم بأوامره المجتنب عن نواهيه وإلا كان القرآن الكريم حجة عليه لا حجة له .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث الذي رواه أنس موقوفاُ :[ رب تال للقرآن والقرآن يلعنه ] / ذكره الغزالي في الإحياء وذكره العلامة الطيبي موقوفا ، انظر كتاب تلاوة القرآن المجيد للشيخ الإمام /&nbsp;<br />\r\nولهذا قال بعض السلف إن العبد ليتلو القرآن فيلعن نفسه وهو لا يعلم ، يقرأ { ألا لعنة الله على الظالمين } وهو ظالم لنفسه ، و يقرأ { فنجعل &nbsp;لعنة الله على الكاذبين } وهو منهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وقد كان العلماء في صدر الإسلام هم القراء وذلك لأن القراء كانوا مجتهدين فكانوا يستنبطون العلم من القرآن والأحاديث فكان كل من كان أكثر حفظاً للقرآن كان أعلم بالدين ، بالحلال والحرام ، ثم لما مضت قرون السلف الصالح &nbsp;قطعت العلماء الاجتهاد للعجز عنه وأوجبوا على الناس التقليد للسابقين عملاً بقوله تعالى :{ فاسألوا أهل الذكر إن كنتم لا تعلمون } فصار العلم غير لازم للقراء ، &nbsp;بل قد يكون قارئ غير عالم ، وقد يكون عالم غير قارئ ، &nbsp;ولما كان المقصود الأعظم من القرآن والأحاديث التفقه بما فيهما من المعاني والأحكام وليس المقصود منهما حفظ الألفاظ المجردة ، كان الفقه أي العلم والفهم أفضل من الحفظ المجرد عن الفهم ، ولهذا نص العلماء على أن الأحق بالإمامة الأعلم بأحكام الصلاة ثم الأحسن تلاوة للقرآن ، فقدموا العالم على القارئ ولهذا أيضاً نص العلماء على أنه إذا كان في المسجد مجلسان مجلس قرآن ومجلس موعظة فاستماع الموعظة &nbsp;أفضل من استماع القرآن ، أي إذا لم يكن له قدرة على فهم الآيات القرآنية وكذا من باب أولى إذا كان مجلس علم يتعلق بالتوحيد أو بالحلال والحرام ، فإنه أفضل من استماع القرآن ومن استماع الموعظة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ولهذا نص العلماء على أن التبحر في علم الفقه [ أي التوسع فيه ] سواء أكان الفقه الأكبر أي علم التوحيد والإيمان ، أو كان فقه الحلال والحرام أفضل من التفرغ لحفظ جميع القرآن وأفضل أيضاً من قيام الليل ، وأن التفرغ لحفظ جميع القرآن أفضل من قيام الليل . والحاصل أن حفظ جميع القرآن فرض كفاية إذا قام به البعض سقط عن الباقين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وحفظ آية من القرآن فرض عين على كل مسلم بالإجماع لأن الصلاة لا تصح بدون القراءة ولو بقدر آية ، وحفظ الفاتحة فرض عندالشافعية &nbsp;لعدم صحة الصلاة بدونها عندهم ، وواجب عند الحنفية &nbsp;حفظ سورة ولو قصيرة أو ما يقوم مقامها من ثلاث آيات قصار .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">واشتغال الإنسان بحفظ جميع القرآن أفضل من قيام الليل&nbsp;، والتبحر في الفقه أفضل منهما معاً ، &nbsp;والمراد بالفقه : علم أصول الدين أي علم التوحيد والإيمان الذي هو الفقه الأكبر وعلم الحلال والحرام ، هذا كله في التوسع فيهما أي تعلم ما زاد على حاجته منهما وأما تعلم ما يحتاجه من تصحيح عقيدته وإيمانه وتوحيده فهو حتم البتة ، فإنه لا يكون مؤمناً بدونه ، وكذا تعلم ما يحتاجه من الفرائض والواجبات كصلاته وزكاته وصومه وحجه فهو فرض واجب ، &nbsp;ثم إن تحسين الصوت بالقراءة مستحب بالإجماع ما لم يخرج عن حد القراءة بالتمطيط فإن أفرط حتى زاد حرفاً أو أخفى حرفاً فهو حرام بالاتفاق ، &nbsp;وأما القراءة بالألحان أي الأنغام المستفادة من فن الموسيقى فإن كان يخرج أيضاً بسببها عن حد القراءة بتمطيط حرف أو تقصيره فهو حرام بالاتفاق ، &nbsp;فإن كان في الصلاة فهو مفسد لها أيضاً وإن لم يخرج بالأنغام عن الأحكام التجويدية فهذا قد وقع فيه خلاف ، فقيل أنها بدعة مكروهة تحريماً وعليه أكثر القراء المتقدمين والسلف ، وقيل أنها جائزة بل مستحبة في الصلاة وخارجها وعليه أكثر الفقهاء الحنفية والشافعية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">استدل من قال بالكراهة بما رواه حذيفة عن النبي صلى الله عليه وسلم أنه قال :[ اقرؤوا &nbsp;القرآن بلحون العرب وأصواتها وإياكم ولحون أهل الفسق فإنه سيجيء من بعدي أقوام يرجعون بالقرآن ترجيع الغناء والنوح لا يجاوز حناجرهم مفتونة قلوبهم وقلوب من يعجبهم شأنهم ] ./ المعجم الأوسط للطبراني / واحتجوا أيضاً بأن النبي صلى الله عليه وسلم ذكر أشراط الساعة فذكر منها أن يتخذ القرآن مزامير يقدمون أحدهم ليس بأقرئهم ولا أفضلهم إلا ليغنيهم . / مسند أحمد &nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">واحتجوا أيضاً أن النبي صلى الله عليه وسلم منع المؤذن المطرب في أذانه من التطريب وقال له : إن الأذان سهل سمح فإن كان أذانك سهلاً سمحاً وإلا فلا تؤذن. / سنن الدارقطني&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">قالوا : وقراءة القرآن بالألحان ذريعة موصلة إلى الخروج عن حد القراءة وأحكام التجويد من التمطيطات والتلحينات التي يفعلها المغنون الفسقة في أشعارهم فالمنع منه كالمنع من الذرائع المفضية إلى الحرام &nbsp;.&nbsp;<br />\r\nواستدل من قال بالجواز والاستحباب بما في صحيح البخاري أن النبي صلى الله عليه وسلم قال : [ الماهر بالقرآن مع الكرام البررة ، وزينوا القرآن بأصواتكم ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري قال رسول الله صلى الله عليه وسلم :[ لم يأذن الله لشيء ما أذن للنبي صلى الله عليه و سلم يتغنى بالقرآن ] وفيه أيضاً قال صلى الله عليه وسلم : [ ليس منا من لم يتغن بالقرآن ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفيه عن أبي موسى رضي الله عنه أن النبي صلى الله عليه وسلم قال له :[ يا أبا موسى لقد أوتيت مزماراً من مزامير آل داود ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفيه أن النبي صلى الله عليه وسلم استمع ليلة إلى قراءة أبي موسى الأشعري رضي الله عنه فلما أخبره النبي صلى الله عليه وسلم بذلك قال أبو موسى لو كنت أعلم أنك تسمعه لحبرته لك تحبيراً ، أي حسنته لك وزينته بصوتي تزييناً .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث :[ تعلموا القرآن وغنوا به ] / المعجم الكبير للطبراني&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وعن عمر بن الخطاب رضي الله عنه أنه كان يقول لأبي موسى الأشعري رضي الله عنه &nbsp;: &nbsp;ذكرنا ربنا ، فيقرأ أبو موسى ويتلاحن &nbsp;/ صحيح ابن حبان</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وذكر الطحاوي عن أبي حنيفة وأصحابه أنهم كانوا يستمعون القرآن بالألحان ./ انظر شرح صحيح البخاري لابن بطال / &nbsp;وقال محمد بن الحكم رأيت أبي والشافعي ويوسف بن عمرو يستمعون القرآن بالألحان .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">فهذا خلاصة كلام الفريقين .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">والتوفيق بين هاتين الطائفتين وفصل النزاع بينهما ما قاله المحققون : إن التغني بالقرآن على وجهين :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">- أحدهما ما كان على وجه التكلف والتصنع &nbsp;والتمرين والتعلم كما يتعلم أصوات الغناء بأنواع الألحان البسيطة والمركبة على إيقاعات مخصوصة وأوزان محدودة ومعدودة لا تحصل إلا بالتعلم والتكلف فهذه القراءة على هذا الوجه هي التي كرهها السلف وقدماء القراء وعابوها وذموها ومنعوا القراءة بها وأنكروا على من قرأ بها لأنه يكون المقصود الغناء وحسن الصوت لا القراءة وتكون القراءة تبعاً للغناء .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وأدلتهم التي احتجوا بها إنما تدل على هذا الوجه ولا تدل على أكثر من هذا &nbsp;- الوجه الثاني أن يكون التغني بالقرآن على وجه تسمح به الطبيعة من غير تكلف ولا تصنع &nbsp;ولا تمرين ولا تتبع لطريقة الفسقة في أشعارهم وأغانيهم &nbsp;فذلك جائز ، فإن أعان طبيعته بشيء من التحسين والتزيين كما قال أبو موسى للنبي صلى الله عليه وسلم :[ لو علمت أنك تسمع لحبرته لك تحبيراً ] كان ذلك &nbsp;حسناً وهذا هو الذي كان السلف يفعلونه ويستمعونه وهو التغني الممدوح به تكون القراءة أوقع في النفوس وأدعى إلى الاستماع والإصغاء إليه ففيه تنفيذ للفظه إلى الأسماع ومعانيه إلى القلوب وذلك عون على المقصود فيكون التغني على هذا الوجه بمنزلة الحلاوة التي تجعل في الدواء والروائح الطيبة التي تجعل في الطعام ، وبمنزلة تجمل المرأة لبعلها ، فيكون المقصود أولاً هو استماع القرآن ويكون حسن الصوت لأجل القرآن ، لا أن يكون المقصود هو حسن الصوت والتغني ويكون القرآن وسيلة له .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">&nbsp;قال المحققون : ولابد للنفس من طرب واشتياق إلى الغناء فعوضت عن طرب الغناء بطرب القرآن وعن السماع الشيطاني بالسماع الرحماني . قالوا وهكذا شأن الشريعة المحمدية وهو أن تشرع عن كل محرم ومكروه بما هو خير منه قالوا : وهذا من جملة التيسيرات في الشريعة المحمدية وهو أن تشرع في الطاعات ما ترغب فيه الطبيعة البدنية لتكون الطبيعة راغبة فيما يرغب فيه العقل الإيماني فيتعاضد الرغبتان إلى الرغبة الطبيعية والرغبة العقلية الإيمانية ويتم الإقبال على الطاعة من جهتين من جهة البدن ومن جهة العقل وبهذا يتوفر للإنسان التأمل في معاني القرآن والتفتيش على أسراره ورموزه ولاشك أن المقصود الأول من تنزيل القرآن هو التدبر في آياته كما قال تعالى : { كِتَابٌ أَنْزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آَيَاتِهِ وَلِيَتَذَكَّرَ أُولُو الْأَلْبَابِ } &nbsp;وقال تعالى : { أَفَلَا يَتَدَبَّرُونَ الْقُرْآَنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا } &nbsp;وقد اختلف الناس أيهما أفضل هل الترتيل مع قلة القراءة ، أو الحدر أي الإسراع مع كثرة القراءة ، فقالت طائفة : الترتيل مع التدبر أفضل من الإسراع ، قالوا لأن المقصود من قراءة القرآن فهمه والتدبر في آياته والعمل به ، &nbsp;قالوا : ولهذا كان أهل القرآن هم العاملين به والعاملين بما فيه وإن لم يحفظوه عن ظهر قلب أو لم تكن الحروف من تمام مخارجها فأما من حفظه ولم يفهمه ولم يعمل به فليس من آله وإن أقام حروفه إقامة السهم ، قالوا : ولأن الإيمان أفضل الأعمال وفهم القرآن وتدبره هو الذي يثمر الإيمان وأما مجرد التلاوة من غير فهم ولا تدبر فيفعله البر والفاجر والمؤمن والمنافق كما مر في الحديث :&nbsp;<br />\r\nومثل المنافق الذي يقرأ القرآن كمثل الريحانة ريحها طيب وطعمها مر قالوا : وصح أن النبي صلى الله عليه وسلم قام ليلة تامة بآية واحدة يتلوها ويرددها حتى الصباح وهي : { إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ }/ سنن النسائي ، &nbsp;وعن ابن مسعود : لا تهذوا &nbsp;بالقرآن هذ الشعر . / شعب الإيمان للبيهقي ، وقالت طائفة أخرى : &nbsp;كثرة القراءة أفضل ، واحتجوا بحديث ابن مسعود رضي الله عنه قال رسول الله صلى الله عليه و سلم : &nbsp;[ من قرأ حرفا من كتاب الله فله به حسنة والحسنة بعشر أمثالها لا أقول آلم حرف ولكن ألف حرف ولام حرف وميم حرف ] رواه الترمذي وصححه&nbsp;<br />\r\nو<br />\r\nفي صحيح ابن حبان عن أبي هريرة ، عن رسول الله صلى الله عليه وسلم ، قال : &quot; خفف على داود القراءة ، فكان يأمر بدابته أن تسرج ، فيفرغ من قراءة الزبور قبل أن تسرج دابته قالوا ولأن عثمان بن عفان رضي الله عنه قرأ القرآن في ركعة &ndash; كما في سنن الترمذي - واستدلوا أيضاً بآثار كثيرة عن السلف في كثرة القراءة &nbsp;والتحقيق في المسألة أن يقال : إن ذلك يختلف باختلاف الأشخاص فمن كان يظهر له بالتأمل والتدبر لطائف ومعارف فالأفضل في حقه الاقتصار على قدر يتمكن معه من فهم ما يقرأ وكذا من كان مشغولاً بنشر العلم أو بشيء من مهمات الدين ومن لم يكن كذلك فالأفضل في حقه الاستكثار ما أمكنه من غير خروج إلى حد الملل والهذرمة وهذا في الدنيا وأما من جهة الثواب في الآخرة فالتحقيق أيضاً أن ثواب قراءة الترتيل والتدبر أنفع وأجل قدراً وثواب كثرة القراءة أكثر عدداً فالأول كمن تصدق بجوهرة عظيمة أو أعتق عبداً قيمته نفيسة جداً والثاني كمن تصدق بعدد كثير من الدراهم أو أعتق عدداً كبيراً من العبيد الذين قيمتهم رخيصة ، ثم إن القرآن العظيم كما إنه تتفاضل قراءته فإن القراءة بالتدبر أفضل من القراءة بدون تدبر كما قررناه مع أن المقروء واحد وهو القرآن فكذلك أيضاً نفس القرآن يتفاضل فإن بعضه أفضل من بعض وإن كان الكل كلام الله سبحانه وتعالى وذلك من جهتين من جهة المعنى ومن جهة الثواب فقد وردت في فضل سورة الإخلاص { قل هو الله أحد } أحاديث كثيرة وكذا في سورة الكافرون وسورة الزلزلة وسورة الفاتحة وفي آية الكرسي وفي غيرها أما فضل { قل هو الله أحد } ففي صحيح البخاري قال النبي صلى الله عليه و سلم لأصحابه : ( أيعجز أحدكم أن يقرأ ثلث القرآن في ليلة ) . فشق ذلك عليهم وقالوا أينا يطيق ذلك يا رسول الله ؟ فقال (الله الواحد الصمد ثلث القرآن).</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري : : أن رجلا سمع رجلا يقرأ { قل هو الله أحد } . يرددها فلما أصبح جاء إلى رسول الله صلى الله عليه و سلم فذكر ذلك له وكأن الرجل يتقالها فقال رسول الله صلى الله عليه و سلم ( والذي نفسي بيده إنها لتعدل ثلث القرآن ) .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح مسلم قال رسول الله -صلى الله عليه وسلم- &laquo; احشدوا فإنى سأقرأ عليكم ثلث القرآن &raquo;. فحشد من حشد ثم خرج نبى الله -صلى الله عليه وسلم- فقرأ ( قل هو الله أحد).</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وروى مسلم أيضاً أنه صلى الله عليه وسلم قال :[ إن الله جزأ القرآن ثلاثة أجزاء فجعل قل هو الله أحد جزءاً من أجزاء القرآن ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وروى الترمذي عن ابن عباس قال : قال رسول الله صلى الله عليه و سلم إذا زلزلت تعدل نصف القرآن وقل هو الله أحد تعدل ثلث القرآن وقل يا أيها الكافرون تعدل ربع القرآن ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وإنما كانت سورة الإخلاص تعدل ثلث القرآن لأن القرآن إما فيما يتعلق بالخالق أو فيما يتعلق بالمخلوق والثاني إما إنشاء أي أوامر ونواهي وإما إخبار عن أحوال السعداء والأشقياء ولاشك أن { قل هو الله أحد } إخبار عما يتعلق بنعوت الخالق فكانت تعدل ثلث القرآن وذلك لأنها تضمنت إثبات الأحدية المطلقة الكاملة لله تعالى المستلزمة نفي التعدد من جميع الوجوه عنه تعالى فلا يتجزأ ولا ينقسم وإلا لكان متعدداً فلا يكون أحداً وتضمنت أيضاً إثبات الصمدية لله تعالى المطلقة الكاملة ، &nbsp;ومعنى الصمد : &nbsp;المستغني عن غيره المحتاج إليه غيره ، ولاشك أن من استغنى عن كل ما سواه مع احتياج ما عداه إليه يجب أن يكون متصفاً بكل كمال ومنزهاً &nbsp;عن كل نقصان &nbsp;، وإلا فلو كان ناقصاً لاحتاج إلى من يكمله وقد قررنا أنه الصمد أي المستغني عن غيره المحتاج إليه كل ما عداه &nbsp;، وتضمنت هذه السورة أيضاً نفي الولد والوالد وهذا في الحقيقة لازم للأحد الصمد وذلك لأن من كان أحداً حقيقياً فلا يتعدد ولا يتجزأ وإذا كان لا يتجزأ فلا يلد لأن الولد جزء أبيه ومن كان صمداً أي مستغنياً عن غيره فلا يحتاج إلى أب لأنه لو احتاج إلى أب لاحتاج إلى من يلده ويوجده ثم يربيه ويكمله حتى تكمل نشأته فيلزم أنه كان أولاً معدوماً ثم صار موجوداً ناقصاً ثم تكمل وهذا كله مناف لكونه صمداً لأن الصمد هو المستغني عن غيره المحتاج إليه كل ما عداه&nbsp;<br />\r\nوتضمنت هذه السورة أيضاً نفي الكفو أي نفي النظير أي المماثل وهذا أيضاً لازم لمعنى الواحد المطلق أي الواحد من جميع الوجوه لأنه إذا كان واحداً من كل وجه كان واحداً في ذاته فلا يتجزأ ، &nbsp;وواحداً &nbsp;في صفاته فلا يكون له نظير في ذاته ولا في صفاته &nbsp;، ويستلزم ذلك أنه واحد في صفات الألوهية فلا إله غيره &nbsp;فقد تضمنت هذه السورة جميع أصول التوحيد بل أصول التوحيد كلها قد تضمنها قوله تعالى :{ الله أحد الله الصمد } ولهذا اقتصر في بعض أحاديث البخاري على هذه الآية إشارة إلى ذلك ولما كان الإخلاص بالله إما في الاعتقاد وهو معنى { قل هو الله أحد } كما قررناه وإما في العمل وهو معنى { قل يا أيها الكافرون لا أعبد ما تعبدون } فكانت هاتان السورتان كلتاهما للإخلاص إحداهما للإخلاص العلمي والأخرى للإخلاص العملي &nbsp;، ولهذا يستحب قراءتهما في ركعتي الفجر &ndash; أي قبل الفريضة - اللتين هما ابتداء الصلوات ويستحب أيضاً قراءتهما في ثانية الوتر وثالثه الذي هو خاتمة الصلوات فتكون أعمال العبد مفتتحة بالإخلاصين العلمي والعملي ومختتمة بهما ولما كان القرآن شطرين شطر فيما يتعلق بأحكام الدنيا وشطر فيما يتعلق بأحوال الآخرة وسورة الزلزلة قد أخلصت لأحوال الآخرة فكانت تعدل نصف القرآن ولما كان الإخلاص في العلم مقدماً على الإخلاص في العمل كانت سورة الكافرون تعدل ربع القرآن&nbsp;<br />\r\nوأما آية الكرسي فقد ثبت في الصحيح أنها أعظم آية في القرآن ، وفي رواية الترمذي : أنها سيدة آي القرآن ، وفي مسند أحمد: إن لها لساناً وشفتين تقدس الملك عند ساق العرش وروى البخاري عن أبي هريرة رضي الله عنه قال :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وكلني رسول الله صلى الله عليه وسلم بحفظ زكاة رمضان فأتاني آت فجعل يحثو من الطعام فأخذته وقلت والله لأرفعنك إلى رسول الله صلى الله عليه وسلم قال إني محتاج وعلي عيال ولي حاجة شديدة قال فخليت عنه فأصبحت فقال النبي صلى الله عليه وسلم يا أبا هريرة ما فعل أسيرك البارحة قال قلت يا رسول الله شكا حاجة شديدة وعيالا فرحمته فخليت سبيله قال أما إنه قد كذبك وسيعود فعرفت أنه سيعود لقول رسول الله صلى الله عليه وسلم إنه سيعود فرصدته فجاء يحثو من الطعام فأخذته فقلت لأرفعنك إلى رسول الله صلى الله عليه وسلم قال دعني فإني محتاج وعلي عيال لا أعود فرحمته فخليت سبيله فأصبحت فقال لي رسول الله صلى الله عليه وسلم يا أبا هريرة ما فعل أسيرك قلت يا رسول الله شكا حاجة شديدة وعيالا فرحمته فخليت سبيله قال أما إنه قد كذبك وسيعود فرصدته الثالثة فجاء يحثو من الطعام فأخذته فقلت لأرفعنك إلى رسول الله وهذا آخر ثلاث مرات أنك تزعم لا تعود ثم تعود قال دعني أعلمك كلمات ينفعك الله بها قلت ما هي قال إذا أويت إلى فراشك فاقرأ آية الكرسي { الله لا إله إلا هو الحي القيوم } حتى تختم الآية فإنك لن يزال عليك من الله حافظ ولا يقربنك شيطان حتى تصبح فخليت سبيله فأصبحت فقال لي رسول الله صلى الله عليه وسلم : &nbsp;ما فعل أسيرك البارحة ؟ &nbsp;قلت يا رسول الله زعم أنه يعلمني كلمات ينفعني الله بها فخليت سبيله قال ما هي قلت قال لي إذا أويت إلى فراشك فاقرأ آية الكرسي من أولها حتى تختم الآية { الله لا إله إلا هو الحي القيوم } وقال لي لن يزال عليك من الله حافظ ولا يقربك شيطان حتى تصبح ، &nbsp;وكانوا أحرص شيء على الخير فقال النبي صلى الله عليه وسلم أما إنه قد صدقك وهو كذوب تعلم من تخاطب منذ ثلاث ليال يا أبا هريرة ؟ قال لا قال ذاك شيطان<br />\r\nوأما الفاتحة فهي التي لم ينزل في القرآن والتوراة والإنجيل والزبور مثلها كما صرحت بذلك الأحاديث &nbsp;، وهي المتضمنة لجميع معاني كتب الله قال الحسن البصري أنزل الله مئة كتاب وأربعة كتب من السماء أودع علومها أربعة منها التوراة والإنجيل والزبور والفرقان ثم أودع علوم هذه الأربعة &nbsp;الفرقان ثم أودع علوم القرآن المفصل - أي الُسبُعُ الأخير من القرآن الكريم وسمي بالمفصل لقصر سوره وكثرة الفصل بينها ببسم الله الرحمن الرحيم - &nbsp;ثم أودع علوم المفصل فاتحة الكتاب فمن علم تفسيرها كان كمن علم تفسير جميع الكتب المنزلة ومن قرأها فكأنما قرأ التوراة والإنجيل والزبور والفرقان / شعب الإيمان للبيهقي&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وقال المحققون إن معاني الفاتحة مجموعة في قوله تعالى : { إياك نعبد وإياك نستعين } لأن المقصود من الشرائع كلها أن يعبد الله لا غيره وأن يستعان به لا بغيره وهي مشتملة على ذكر أصول أسماء الله تعالى ومجامعها وهي الله والرب والرحمن فإن جميع أسماء الله الحسنى ترجع إلى هذه الثلاث ، وهي المشتملة على ذكر جميع أنواع الثناء والمحامد لله تعالى في قوله تعالى : {الحمد لله } وهي المشتملة على أن كل إنعام وإحسان فهو منه تعالى وذلك في قوله تعالى :{ الرحمن الرحيم } فذكر الرحمة الخاصة والعامة.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وهي مشتملة على توحيد الله تعالى و ذكر الافتقار إلى الرب سبحانه في طلب الإعانة منه في إياك نستعين وطلب الهداية منه في اهدنا الصراط المستقيم صراط الذين أنعمت عليهم ، وهي المشتملة على ذكر أفضل الأدعية على الإطلاق وأنفعها وأفرضها وأحوج شيء إلى العباد وهو الهداية إلى الصراط المستقيم ، ولا تتم الهداية إلى صراطه إلا بكمال معرفته وتوحيده وعبادته بفعل ما أمر به واجتناب ما نهى عنه والاستقامة على ذلك إلى الموت .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وهي المشتملة على ذكر أصناف الخلائق وانقسامهم إلى منعم عليه بمعرفة الحق والعمل به ومغضوب عليه بعدوله عن الحق بعد معرفته وضال لعدم معرفته للحق .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وهذه الأقسام الثلاثة هي أقسام الخليقة وبالجملة فكل ما ورد في القرآن مفصلاً فإنه ورد في الفاتحة مجملاً ولهذا سميت بأم الكتاب وبأم القرآن . وأم الشيء أصله ومادته ولهذا سميت بالقرآن العظيم إشارة إلى أنها جامعة لكل ما في القرآن فسميت باسمه .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري عن أبي سعيد بن المعلى قال : كنت أصلي في المسجد فدعاني رسول الله {صلى الله عليه وسلم} فلم أجبه ثم أتيته فقلت يا رسول الله إني كنت أصلي فقال ألم يقل الله ( استجيبوا لله وللرسول إذا دعاكم ) ثم قال لي لأعلمنك سورة ً هي أعظم السور في القرآن قبل أن تخرج من المسجد ثم أخذ بيدي فلما أراد أن يخرج قلت ألم تقل لأعلمنك سورة ً هي أعظم سورة في القرآن قال ( الحمد لله رب العالمين ) قال هي السبع المثاني والقرآن العظيم الذى أوتيته .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">أشار صلى الله عليه وسلم إلى تفسير قوله تعالى :{ وَلَقَدْ آَتَيْنَاكَ سَبْعًا مِنَ الْمَثَانِي وَالْقُرْآَنَ الْعَظِيمَ } فهي المتضمنة جميع معاني الكتب السماوية ، ثم قال الحسن البصري رضي الله عنه :ومن أسمائها الشفاء وحقيق بسورة هذا بعض شأنها أن تكون شفاء من الأمراض وأن يرقى بها اللديغ .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي الحديث فاتحة الكتاب شفاء من كل داء / سنن الدرامي&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي رواية :شفاء من السم . / شعب الإيمان للبيهقي&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري عن أبي سعيد الخدري رضي الله عنه : أن رهطاً من أصحاب رسول الله صلى الله عليه و سلم انطلقوا في سفرة سافروها حتى نزلوا بحي من أحياء العرب فاستضافوهم فأبوا أن يضيفوهم فلدغ سيد ذلك الحي فسعوا له بكل شيء لا ينفعه شيء فقال بعضهم لو أتيتم هؤلاء الرهط الذين قد نزلوا بكم لعله أن يكون عند بعضهم شيء فأتوهم فقالوا يا أيها الرهط إن سيدنا لدغ فسعينا له بكل شيء لا ينفعه شيء فهل عند أحد منكم شيء ؟ فقال بعضهم نعم والله إني لراق ولكن والله لقد استضفناكم فلم تضيفونا فما أنا براق لكم حتى تجعلوا لنا جعلا ، فصالحوهم على قطيع من الغنم فانطلق فجعل يتفل ويقرأ { الحمد لله رب العالمين } . حتى لكأنما نشط من عقال فانطلق يمشي ما به قلبة &ndash; أي علة - قال فأوفوهم جعلهم الذي صالحوهم عليه فقال بعضهم اقسموا فقال الذي رقى لا تفعلوا حتى نأتي رسول الله صلى الله عليه و سلم فنذكر له الذي كان فننظر ما يأمرنا فقدموا على رسول الله صلى الله عليه و سلم فذكروا له فقال ( وما يدريك أنها رقية ؟ أصبتم اقسموا واضربوا لي معكم بسهم ) .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ويجب أن يعلم أن الاستشفاء بالقرآن والأدعية ونحوها من الرقى يختلف باختلاف أحوال الراقين وأحوال المسترقين فإن الاستشفاء &nbsp;بذلك &nbsp;لا يناسب إلا الأرواح الطيبة والقلوب الحية فليس إذا لم يحصل الشفاء لقصور في الدواء بل قد يكون ذلك من جهة المسترقين لخبث الطبيعة وفساد المحل وقد يكون من جهة الراقين لعدم استيفاء القدر اللازم من صدق التوجه إلى الله وقد كان بعض الشيوخ المتقدمين يرقي نفسه &nbsp;بقل هو الله أحد فكان لها بركة عظيمة فيرقي بها غيره فلا يحصل ذلك فيقول : ليس قل هو الله أحد من كل أحد تنفع كل أحد&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">ومن أسماء الفاتحة الصلاة ففي الحديث الذي رواه الإمام مسلم قال رسول الله صلى الله عليه وسلم &nbsp;قال الله &nbsp;عز وجل : &nbsp;قسمت الصلاة &ndash; أي الفاتحة - بيني وبين عبدي ولعبدي ما سأل فإذا قال العبد الحمد لله رب العالمين قال الله حمدني عبدي فإذا قال الرحمن الرحيم قال الله أثنى علي عبدي فإذا قال مالك يوم الدين قال الله مجدني عبدي أو قال فوض إلي عبدي فإذا قال إياك نعبد وإياك نستعين قال هذه بيني وبين عبدي ولعبدي ما سأل فإذا قال اهدنا الصراط المستقيم صراط الذين أنعمت عليهم غير المغضوب عليهم ولا الضالين . قال هذا لعبدى ولعبدى ما سأل &raquo;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وبالجملة فالفاتحة كما أنها فاتحة الكتاب هي أيضاً فاتحة كل خير دنيوي وأخروي فهي مفتاح لكنوز الآخرة وهي مفتاح لكنوز الدنيا ولكن ليس كل أحد يعرف الفتح بها إلا بتوفيقه تعالى&nbsp;<br />\r\nوهذه الأحاديث التي ذكرناها في فضائل السور تدل على أن القرآن بعضه أفضل من بعض وإن كان الكل كلام الله وهذا هو القول المأثور عند السلف الصالح وهو الذي عليه أئمة الفقهاء من الطوائف الأربعة وغيرهم وهو الذي نطقت به النصوص النبوية كما قدمناه في الأحاديث المارة وهو الذي دلت عليه الآيات القرآنية قال الله تعالى :{ ما ننسخ من آية أو ننسها نأت بخير منها أو مثلها } فأخبر أن بعض الآيات خير من بعض وإن بعضها مثل بعض فهي تارة تتفاضل وتارة تتماثل .&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وقال تعالى :{ وَأَنْزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ مُصَدِّقًا لِمَا بَيْنَ يَدَيْهِ مِنَ الْكِتَابِ وَمُهَيْمِنًا عَلَيْهِ } والمهيمن هو المؤتمن والشاهد والقائم على أمور غيره ولاشك أن يكون أعلى رتبة من ذلك الغير .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وقد أجمع المسلمون على أن القرآن أفضل الكتب السماوية &nbsp;مع أن جميع الكتب السماوية كلام الله وهذا التفضيل يرجع لشيئين من حيث المعنى ومن حيث الثواب ولاشك أن معنى {قل هو الله أحد } أفضل من معنى { تبت يدا أبي لهب } ومعنى { الله لا إله إلا هو الحي القيوم لا تأخذه سنة ولا نوم } أفضل من معنى قوله تعالى { وقالت اليهود يد الله مغلولة غلت أيديهم } &nbsp;وكما أن كلام الله يفضل بعضه بعضاً فكذلك أسماؤه تعالى تتفاضل - أي : من ناحية تضمنها لمعاني أسماء إلهية غيرها - &nbsp;وإن كانت جميع أسماء الله حسنى فالاسم الأعظم أفضل من غيره وإن كانت جميع أسماء الله عظيمة جليلة وكما أن أسماءه تعالى تتفاضل فكذلك صفاته وإن كانت جميع صفاته لا نهاية لكمالها وتمامها&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح البخاري عن أبي هريرة رضي الله عنه قال : سمعت رسول الله صلى الله عليه و سلم يقول [ إن الله كتب كتاباً قبل أن يخلق الخلق إن رحمتي سبقت غضبي ] &nbsp;وفي رواية &nbsp;له أيضاً: [إن رحمتي غلبت غضبي ] &nbsp;وقد فضلت رحمة الله على غضبه بالسبق والغلبة&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وفي صحيح مسلم أن النبي صلى الله عليه وسلم كان يقول في سجوده : اللهم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك وأعوذ بك منك<br />\r\nومعلوم أن المستعاذ به أفضل من المستعاذ منه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"line-height:30px\"><span style=\"font-size:24px\">وسيأتي تمام هذا إن شاء الله تعالى وصلى الله على سيدنا محمد وعلى آله وصحبه وسلم والحمد لله رب العالمين</span></span></span></p>', 'ar', 9281, 20, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (34, 46, 'اشتغاله بالعلوم الشرعية', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان من جملة أنظمة المدرسة الخسروية التي تعنى بتدريس العلوم الشرعية : أن لا يقبل إلا من تجاوز الخامسة عشرة من عمره ويخضع فيها الطالب لامتحان قبول يعرض فيه على لجنة من العلماء والمدرسين &nbsp;بحيث يمتحن الطالب في القراءة والكتابة ومبادئ اللغة العربية وتجويد القرآن الكريم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد قبلت إدارة المدرسة شيخنا الإمام ولم يبلغ الثالثة عشرة من عمره بعد وذلك لما وجدوا فيه من الاستعداد الكامل والأهلية التامة لمتابعة العلوم الشرعية وكان من المتفوقين في فحص القبول .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أمضى ما يقرب من ست سنين في المدرسة الخسروية استمع فيها إلى دروس كبار العلماء والمشايخ منهم : الشيخ محمد سعيد الإدلبي / ولد سنة /1292/ هـ وتوفي سنة /1370/ هـ / والشيخ إبراهيم السلقيني الكبير ، والشيخ أحمد الحجي الكردي أمين الفتوى وقتئذ ، والشيخ عيسى البيانوني ، والشيخ فيض الله الكردي ، والشيخ عمر مارتيني ، والشيخ راغب الطباخ / ولد سنة 1293 هـ وتوفي سنة 1370هـ / &nbsp;، مدير المدرسة الخسروية وقتها ، وغيرهم من المدرسين أهل الفضل والعلم رحمهم الله تعالى ونفعنا بهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان في تحصيل العلم من المتفوقين ، حاز الدرجة الأولى في جميع سني دراسته ، والتفت إلى حفظ &nbsp;متون أمهات العلوم ، وإن لم تكن كلها من مقررات المدرسة وقتها ، إلا أن رغبته الصادقة في تعلم العلوم الشرعية حملته على ذلك ، فحفظ متن الجزرية في علم التجويد ، ومتن الجوهرة ومتن السنوسية في علم التوحيد ، ومتن السلم في علم المنطق ، ومتن البيقونية في علم مصطلح الحديث وألفية ابن مالك في علم النحو والصرف وعقود الجمان في علم البلاغة ثم حفظ ألفية الحافظ العراقي في السيرة والرحبية في علم الفرائض وغيرها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\"><strong>اشتغاله بعلم التفسير والحديث</strong></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام رضي الله عنه &nbsp;:</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ لقد حبب الله تعالى إلي حفظ أحاديث رسول الله صلى الله عليه وسلم &nbsp;منذ صغري ، ولما كنت في الصف الثاني الإعدادي في المدرسة الخسروية رأيت في مكتبة والدي رضي الله عنه &nbsp;كتاب [ تيسير الوصول ] / &nbsp;إلى جامع الأصول وهو مختصر [ جامع الأصول لأحاديث الرسول صلى الله عليه وسلم &nbsp;] للإمام عبد الرحمن بن علي المعروف بابن الديبع الشيباني ، ولد سنة /866/ هـ وتوفي سنة / 944/ هـ رحمه الله تعالى /.<br />\r\n&nbsp; ويقع في أربع مجلدات تناولت المجلد الأول منها في العطلة الصيفية وشرعت في الحفظ حتى حفظت في كل عطلة مجلداً وأنهيت الحفظ في آخر عطلة من دراستي في المدرسة الخسروية وكنت لا أشرع في حفظ شيء جديد حتى أتمكن وأتقن محفوظاتي السابقة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكنت أتناول كتب تفسير القرآن الكريم وأحاول فهم آيات الله تعالى من خلال أحاديث سيدنا رسول الله صلى الله عليه وسلم &nbsp;وهي في الحقيقة بيانات لمعاني القرآن الكريم لأن الله تعالى يقول:{ وَأَنْزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ &nbsp;} ولم يكن يخطر في بالي مرة أني سأتصدر مجلساً للتدريس أو أصعد منبراً للخطبة بل إن الباعث لي على ذلك كله هو حبي لله تعالى ورسوله صلى الله عليه وسلم &nbsp;ورغبتي الشديدة في تعلم آيات الله تعالى وأحاديث رسول الله صلى الله عليه وسلم &nbsp;إلا أنني بعد ذلك وجدت قيمة ذلك وأثره لما استلمت الخطبة والتدريس عن والدي الشيخ محمد نجيب رضي الله عنه &nbsp;وعلمت أن سلاح طالب العلم هو : قال الله وقال رسول الله صلى الله عليه وسلم &nbsp;وبدون ذلك أنى للعالم أن يتكلم ؟!]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وفي ذلك إعداد من الله تعالى لشيخنا &nbsp;الإمام &nbsp;وإمداد له منذ صغره ودليل على صدقه وإخلاصه في طلب العلم فلم يك يبتغي من وراء ذلك منصباً ولا جاهاً ولا وظيفة ، وقد تجلى ذلك لما خرج من المدرسة الخسروية ولم يكمل الصف السادس فيها ، ولم يحصل على شهادة منها وكان ذلك بسبب أن إدارة المدرسة أدخلت جملة واسعة من العلوم الكونية في المقررات وأجبرت طلاب الصف السادس على الرجوع إلى الصف الرابع لدراستها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد حبب الله إليه البحث حول شمائل سيدنا رسول الله صلى الله عليه وسلم وخصاله الشريفة وسيرته الزكية ، وكان يسر غاية السرور لقراءتها والاطلاع عليها ، خاصة منها المؤيد بادلة الكتاب والسنة ومفاهيم العلماء والعارفين رضي الله عنهم ، ومن هذا لما عرض عليه الشيخ رشيد الراشد كتاباً جمعه حول هذا الموضوع وسماه :الدر المنظم في وجوب محبة السيد الأعظم صلى الله عليه وسلم &nbsp;، قرظ له الشيخ بهذه الكلمات :&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">بسم الله الرحمن الرحيم&nbsp;</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">الحمد لله حمداً ليس له عد ولا إحصاء ، والشكر لله شكراً لا حد له ولا استقصاء ، وأشهد أن لا إله إلا الله وحده لا شريك له الحكيم الفعال لما يشاء ، وأشهد أن سيدنا محمداً عبده ورسوله إمام الرسل والأنبياء ، وأصلي وأسلم على من خلقت من نوره جميع الأشياء وعلى آله واصحابه البررة الأصفياء صلاة وسلاماً عدد ما أظلت الخضراء وأقلت الغبراء في كل لمحة ونفس ما دامت الأرض والسماء&nbsp;<br />\r\nوبعد : فقد اطلعت على كتاب الدر المنظم في وجوب محبة السيد الأعظم صلى الله عليه وسلم فرأيت فيه نوراً محمدياً باهراً وضياء نبوياً زاهراً تتجلى فيه أوصافه صلى الله عليه وسلم الكاملة واخلاقه الزكية العالية وهو كتاب يلهب الشوق في قلوب المشتاقين ثم ينعشها بروح رياح تلك الرياحين ، يزداد به الذين اهتدوا هدى ويقيم الحجة على أهل البدعة والردى ، موضوعه البحث في الذات المحمدية وما اتصفت به من الصفات السنية ، قد اغترف جامعه من بحور العارفين الزاخرة وأبحر العلماء الوافرة فالتقى البحران بحر العلم وبحر العرفان ، والله تعالى أسأل وبأفضل أنبيائه أتوسل أن يجزي جامعه خيراً كثيراً وأجراً كبيراً والحمد لله رب العالمين<br />\r\nالفقير لمولاه : عبد الله سراج الدين &nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\"><img alt=\"\" src=\"/other_files/Image/pic_002.jpg\" style=\"width:80%\" /></p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\"><img alt=\"\" src=\"/other_files/Image/pic_004.jpg\" style=\"width:80%\" /></p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\"><img alt=\"\" src=\"/other_files/Image/pic_003.jpg\" style=\"width:80%\" /></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\"><strong>مطالعته وتدريسه</strong></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم إن مولانا الشيخ محمد نجيب رضي الله عنه &nbsp;أشار على شيخنا الإمام أن يقوم بالتدريس بدلاً عنه ، بسبب الوهن والمرض الذي أصاب الشيخ محمد نجيب رضي الله عنه &nbsp;فقام شيخنا الإمام رضي الله عنه &nbsp;بذلك خير قيام مستعيناً بالله تعالى وتوفيقه وتأييده وقد قارب العشرين من عمره ثم إنه حصل على غرفة والده الشيخ محمد نجيب رحمه الله تعالى في المدرسة الشعبانية &ndash; وكان يقال لها : أزهر حلب &ndash; وكان الشيخ محمد نجيب رحمه الله تعالى قد جاور فيها أيام طلبه للعلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبقي شيخنا الإمام يتردد إلى تلك الغرفة يقضي أوقاته في مطالعة الكتب العلمية ، ويتناول المطولات منها في علم التفسير والتوحيد وشروح الحديث والفقه وغيرها وبقي على ذلك ما يقرب &nbsp;من سنتين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما اقتضى الأمر أن تكتسب دروسه صفة رسمية لدى الجهات المسؤولة تقدم إلى مسابقة أعلنت عنها دائرة أوقاف حلب ، لدرس وقفي شاغر ، وكان لشيخنا الإمام الفوز والأسبقية في النجاح .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أما دروسه العامة فنهج فيها نهج والده الشيخ محمد نجيب رضي الله عنه &nbsp;من حيث توقيت الدرس والأبحاث العرفانية العالية التي كان يتناول &nbsp;الكلام عنها ، بأسلوب مبسط يسهل على الحاضرين فهمه ، ويفهمونه على حسب علمهم وفطانتهم ، خاصة أنه يكثر من ذكر الآيات والأحاديث التي تؤيد الموضوع الذي يبحث فيه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فكان هناك درس في جامع بانقوسا بعد صلاة العصر من كل يوم جمعة ، يبحث في القضايا الإيمانية العلمية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهناك درس في الجامع الكبير بعد صلاة الظهر في كل يوم اثنين ، يتناول فيه الكلام حول قضايا الإيمان العملية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">&nbsp;ولا يخفى على من كان يحضر دروسه أنها &nbsp;كانت متسلسلة في الأبحاث يبتدئ الشيخ الإمام فيها بتذكير الحاضرين بالدرس المتقدم ، ليستجمع الحاضر فكره وقلبه إلى ما سيلقي شيخنا الإمام من بيانات وأبحاث .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان له صباح كل يوم عدا يوم الجمعة درس في جامع الحموي ، يقرأ فيه أبحاثاً من السيرة النبوية ، والتفسير ، والحديث ، والفقه وهكذا ، ثم اختصر تلك الدروس على أيام الأحد والأربعاء والخميس ، وذلك بسبب كثرة مشاغله ، خاصة أنه وكل إليه تدريس التفسير ، والحديث وعلومه ، والفقه ، في الثانوية الشرعية &ndash; وكانت تعرف من قبل بالمدرسة الخسروية - .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كما كان شيخنا الإمام يخطب الجمعة في جامع سليمان الأيوبي ، الذي كان يخطب فيه قبله والده الشيخ محمد نجيب رضي الله عنه &nbsp;.</span></span></span></p>', 'ar', 8912, 30, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (35, 46, 'افتتاحه للمدرسة الشعبانية', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لما عدلت مناهج المدرسة الخسروية وقرر فيها دراسة كثير من المواد الكونية على حساب المواد الشرعية تأثر لذلك كثير من العلماء الأفاضل في ذلك العصر ومنهم الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;الذي رأى حضرة النبي &nbsp;صلى الله عليه وسلم &nbsp;في المنام وهو يأمره أن يفتتح مدرسة تخصص لدراسة العلوم الشرعية على النهج القديم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبحث مولانا الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;ذلك الأمر مع أصحابه إلا أن الوهن والمرض الذي أصابه حال دون تحقيق رغبته حتى توفاه الله تعالى سنة /1373/ هـ وبقيت الفكرة قائمة لدى شيخنا الإمام إلى أن وفقه الله تعالى إلى ذلك سنة /1380/ هـ بالتعاون مع بعض المدرسين والعلماء الذين كانوا قد تركوا التدريس في المدرسة الخسروية وكان افتتاح الصف التحضيري والصف الأول في غرفتين في جامع الحموي حتى حصل شيخنا الإمام على المدرسة الشعبانية التي كانت قد أغلقت وألحق طلابها بالمدرسة الخسروية.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان شيخنا الإمام قد أشار على بعض المحسنين الموسرين ممن يحضرون دروسه أن يسعوا لإنشاء جمعية خيرية تقوم بالإنفاق على طلاب العلم الذين يدرسون في المدرسة الشعبانية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تحققت رغبة شيخنا الإمام وأسس جمعية التعليم الشرعي وأشهرت لدى الجهات الرسمية حتى إن المسؤول الذي وافق على ترخيصها وقتئذ &ndash; وقد نظر في أعمالها وأهدافها &ndash; قال : هذا ما أرجو الله تعالى أن ينفعني به إذا صرت في قبري .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما اكتملت صفوف المدرسة ست صفوف من مرحلتين إعدادية وثانوية رأى أحد خاصة تلامذة الشيخ محمد نجيب وأحد خاصة مدرسي المدرسة الشعبانية فضيلة الأستاذ الشيخ محمد بن محمد بن محمد آل الغشيم رحمه الله تعالى &nbsp; رأى في المنام الشيخ نجيب &nbsp;رضي الله عنه &nbsp;وأثر التعب على وجهه والعرق في جبينه</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقال له : مم هذا يا سيدي ؟!</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقال الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;له : [ انظر الآن لقد أتممت لكم رصف الطريق الموصل إلى باب المدرسة الشعبانية ] فنظر الشيخ الغشيم فرأى الطريق معبدة مرصوفة نظيفة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما قص تلك الرؤيا على شيخنا الإمام قال :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ رحم الله تعالى والدي وجزاه عنا خير الجزاء فإن فكرة إنشاء المدرسة كانت بأمر رسول الله &nbsp;صلى الله عليه وسلم &nbsp;له ولا يزال يعمل على تحقيق ذلك حتى حصلت رغبته وحقق الله مراده والحمد لله رب العالمين والأمر كله في كتاب أعماله الصالحة إن شاء الله ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وبقي شيخنا الإمام &nbsp;رضي الله عنه &nbsp;يدير المدرسة ويرعاها بعنايته وتوجيهاته ودعواته حتى توفاه الله تعالى ولا زالت بفضل الله تعالى تخرج طلاب العلم الأكفاء لمتابعة الدراسات العليا في شتى المعاهد والجامعات ومنهم الأئمة والخطباء والمدرسون .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد كان &nbsp;رضي الله عنه &nbsp;يقول : [ لقد تشعب عن المدرسة الشعبانية كل خير والحمد لله فقد تفرع عنها دار لتحفيظ القرآن الكريم وتعليم القراءات وحلقات لقراءة الحديث الشريف وكم من مدرسة شرعية أنشئت بعد المدرسة الشعبانية وقد استعانت بمناهجها والحمد لله ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يقول : [ لقد عمر المدرسة الشعبانية حساً ومعنى أكابر &nbsp;الرجال من العلماء و الأولياء ومنهم من جاور فيها لفترات طويلة ولا تزال بركاتهم وآثار طاعاتهم وعباداتهم لله تعالى مشهودة عند أهل التقى والصفاء ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويقول &nbsp;رضي الله عنه &nbsp;: [ إن المدرسة الشعبانية وإن كانت حسب الظاهر متواضعة بجدرانها وبنيانها إلا أنها شامخة بمن عمرها ودرس أو درس فيها ولها مكانتها وعلو مرتبتها عند الله تعالى ]اهـ</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وكان شيخنا الإمام &nbsp;رضي الله عنه &nbsp;لا يترك في دعائه الدعاء للمدرسة الشعبانية وما يتبعها وللعاملين عليها والمدرسين فيها ولطلابها وإدارتها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يوصي المدرسين فيها كلما زاروه يوصيهم بالاهتمام وببذل الجهد في التعليم وأن يحافظوا على حلقات السلسلة العلمية الشرعية ولا يدعوا النقص والضعف والتفكك يسري إليها فكما أخذوا العلم عن مشايخهم بقوة فعليهم أن يوصلوه إلى من بعدهم بقوة وهكذا .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يشحذ همة المدرسين والطلاب أيضاً ويبشرهم بأن الشعبانية محفوفة بالأنظار المحمدية &nbsp;صلى الله عليه وسلم &nbsp;فمن عمل فيها أو أسدى إليها معروفاً فقد ناله من النفحات والأنظار المحمدية على حسب صدقه وإخلاصه لله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وقد قص شيخنا الإمام مرة أنه رأى حضرة النبي &nbsp;صلى الله عليه وسلم &nbsp;في المنام وهو يصلي إماماً في ساحة المدرسة الشعبانية وقال &nbsp;رضي الله عنه &nbsp;:</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ لقد عمرتها أنوار الحبيب الأعظم &nbsp;صلى الله عليه وسلم &nbsp;وأنوار العلماء والأولياء والصالحين نفعنا الله تعالى بهم أجمعين ]&nbsp;<br />\r\nوكان من عادته &nbsp;رضي الله عنه &nbsp;في شهر رمضان المبارك أن يصلي العشاء والتراويح إماماً في جامع الحموي وبقي على ذلك سنين ثم نقل ذلك إلى جامع المدرسة الشعبانية حباً فيها وإحياء لها وخاصة أيام العشر الأخير من رمضان ويطيل الدعاء بعد الصلاة لما لتلك الليالي المباركة من عظيم الفضل ومضاعفة الأجر .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وجاء في نهر الذهب [ 2-116-117] وإعلام النبلاء [7-438-439] :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">هذه المدرسة بناها شعبان آغا بن أحمد آغا المأمور بتحصيل الأموال في حلب سنة 1085 &nbsp;للهجرة وقد اشترى الأرض الخالية الواسعة الأنحاء من جانبولاد زاوه محمد بك .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">الكائنة في محلة الفرافرة وبنى فيها مسجداً بديعاً من الحجر عليه قبة عالية جسيمة وبنى فيها مدرسة من الحجر ذات قبة عالية لتقرأ فيها مباحث العلوم والفنون وهي مدرسة عظيمة عامرة وتشتمل على صحن واسع يبلغ خمسين ذراعاً في مثلها في وسطه حوض مربع يبلغ بضعة عشر ذراعاً في مثلها قد حف في شماليه وغربيه بحديقة جميلة وفي جنوبي الحوض إلى شرقيه مكان للماء واسع حفره وأنشأه المرحوم تقي الدين باشا سنة 1269 من وصية والده المرحوم عبد الرحمن أفندي المدرس ، وفي غربي الصحن وشرقيه رواقان ممتدان من الشمال إلى الجنوب داخلهما سبع وعشرون حجرة للمجاورين وفي جهته الشمالية دار للتدريس وهي قبة عظيمة واسعة وفي شرقيها حجرة واسعة وفي جنوبي الصحن قبلية في شرقيها رواق واسع .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي غربيها مدفن وقفي ومسجدها تقام فيه الصلوات والجمعة</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">&nbsp;قال الشيخ سامح أفندي العينتابي :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وشيدت رواقاً شرقياً ورواقاً غربياً وداخلهما تسع وعشرون حجرة وخصصت هذه الحجرات لسكن طلبة العلم الشريف ، وفرشت في المسجد المذكور بالحجر المرمر وجعلت في وسطه بالحجر المرمر ، وجعلت في وسطه حوضاً عشراً بعشر ذا صفة أنيقة من المرمر وزينت ثلاثة أطراف هذا الحوض الكبير بحدائق على أن يجري إليها الماء من قناة حلب باستحقاق مقرر عن كتاب واقفه التركي وبنيت مكتباً لطيفاً للأهالي المسلمين جنوبي المدرسة يعلم فيه القراءة ومبادئ الكتابة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال الشيخ راغب الطباخ [ 7-438-439] : ولم أقف على أول من تولى التدريس فيها لكني رأيت في أول حاشية الشيخ محمد المرعشي الملقب بساجقلي ذاده ما نصه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لما وليت تدريس المدرسة الشعبانية المحروسة في قريب من تمام ألف ومائة للهجرة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويظهر من هذا أنه ثاني من تولى التدريس فيها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تولى أمرها على وقف الشعبانية الشيخ أحمد الزويتيني مفتي حلب المتوفى 1316 &nbsp;للهجرة ثم تولى أمرها الشيخ مصطفى ولده بقي من 1316 إلى سنة 1331 للهجرة &nbsp;وفيها أتى إلى حلب أحمد جودة أفندي من أهالي تركيا مصطحباً امرأة هرمة تدعى خديجة وادعى أن هذه المرأة وأخاها الغائب حمدي أفندي هما من ذرية الواقف وانهما المتوليان على هذه المدرسة مقتضى شرط الواقف وطال أمر المحاكمة والمرافقة بينهما وفي النهاية تنازل الشيخ مصطفى عن التولية وحكم بها لهذه المرأة ولأخيها بالوكالة عنهما لأحمد جودة المذكور .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولإهمال بعض شؤونها أقام بعدها مدرس المدرسة الشيخ أحمد الزرقا من نجل أستاذنا الكبير الشيخ محمد الزرقا دعوى على وكيل المتولين يطلب فيها منعه من التشبث بكتابة الوقف المذكور</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي سنة 1342 اهتمت دائرة الأوقاف بأمرها بعض الاهتمام وألزمت وكيل المتولي أن يقبل الطلاب من أهالي حلب وغيرهم وذلك على أثر القرار الذي أعطي من قبل مجلس الأوقاف الأعلى الذي عقد في دمشق سنة 1340.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><br />\r\n<span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فجاور فيها ثلاثون طالباً وصارت تعطى لهم الرواتب غير أنه لم يطبق عليها النظام الموضوع للمدرسة الخسروية &nbsp;. اهـ</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وفي فترة متأخرة تم شق شارع يصل ما بين الطريق الذي يربط بين قلعة حلب ومنطقة السبع بحرات المعروفة الآن وعلى إثر ذلك تهدم جزء من المدرسة وبقيت إطلالته على الشارع كجدار قديم</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي عام 1396 هـ قام المرحوم المحامي سليمان النسر &ndash; مدير أوقاف حلب وقتئذ &ndash; وبإشارة ونصيحة من الشيخ الإمام لعمل خير يبقى في صحيفته إلى يوم الدين &ndash; قام بإنشاء مبنى مؤلف من طابق أرضي وفوقه غرف مبنية كصفوف متممة لما تبقى من صفوف المدرسة في الطابق الأرضي ، وعند انتهائه من البناء عام 1399 هـ قام بتسليمه لإدارة المدرسة الشعبانية فجزاه الله خير الجزاء</span></span></span></p>', 'ar', 8484, 40, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (36, 46, 'إجازات الشيخ الإمام', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\"><span style=\"line-height:30px\">نظراً لما كان يحفظه شيخنا الإمام &nbsp;رضي الله عنه &nbsp;من أحاديث كثيرة ، واطلاعه الواسع على كتب الحديث ، بادر كبار العلماء والمحدثين إلى إجازته للرواية عنهم بما أجازهم به شيوخهم ، واستجازته بما يرويه عن شيوخه ، وكان أول من أجاز شيخنا الإمام &nbsp;رضي الله عنه &nbsp;والده الإمام العارف المحدث الشيخ محمد نجيب سراج الدين رحمه الله تعالى بجميع ما أجازه به شيوخه ، ومنهم الشيخ الكبير المحدث العلامة مسند الديار المغربية ، السيد أبو عبد الله محمد بن جعفر بن إدريس الكتاني الحسني المغربي الفاسي [ 1274-1345هـ ] ومنهم شيخه المحدث &nbsp;العلامة المسند الشيخ بدر الدين محمد بن يوسف الحسني الدمشقي المعروف بالمحدث الأكبر [ 1267- 1354 هـ ] ، ومنهم شيخه المحدث العلامة الشيخ بكري بن أحمد الزبري الحلبي [ 1240هـ - 1312 هـ ] ومنهم شيخه المحدث ، العلامة الشيخ كامل المؤقت الحنبلي الحلبي [ 1270هـ - 1338هـ ] وغيرهم رضي الله عنهم أجمعين ونفعنا بهم آمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\"><span style=\"line-height:30px\">ثم توالت الإجازات على شيخنا الإمام &nbsp;رضي الله عنه &nbsp;، من كبار العلماء والأولياء والمحدثين ، في بلاد الشام والحجاز والمغرب والهند ، كان منهم العلامة المحدث الحبيب عبد القادر بن أحمد بن عبد الرحمن بن علي السقاف والعلامة المحدث الحبيب عيدروس بن عمر الحبشي الحضرمي والعلامة المحدث الحبيب زين العابدين بن إبراهيم بن زين بن سميط الحضرمي ثم المدني والعلامة المحدث الشيخ السيد محمد مكي بن السيد محمد بن جعفر الكتاني الحسني المغربي ثم الدمشقي ، والعارف المحدث الشيخ علوي المالكي الحسني شيخ الحجاز في عصره [ 1325-1391 ] ، والشيخ &nbsp;محمد خير الدين إسبير الحلبي ، &nbsp;والإمام المحدث العلامة الشيخ أبو علي حسن بن محمد بن عباس بن علي المشاط المكي المالكي ، وغيرهم من الأئمة والمحدثين ممن أجاز شيخنا بإجازات خطية وشفهية ، وأجازهم بما أجازه به الإمام العارف المحدث الشيخ محمد نجيب سراج الدين رحمه الله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\"><span style=\"line-height:30px\">&nbsp;ونظراً لعلو أسانيد الشيخ الإمام وكثرة إجازاته من كبار المحدثين في بلاد الشام والحجاز والهند والمغرب فقد أفرد بالتأليف حول إجازات الشيخ وأسانيده العالية المؤرخ الباحث الشيخ أحمد بن محمد سردار الحلبي الشافعي رحمه الله تعالى &nbsp;أفرد مؤلفاً خاصأ بذلك &nbsp;- وكان قد حصل على إجازة من الشيخ الإمام في الحديث الشريف &ndash; مظهراً أسانيد الشيخ الإمام العالية<br />\r\nولما للكتاب من قيمة عالية وتوثيق لأسانيد الشيخ الإمام رضي الله عنه فقد رأيت أن أضع لك &ndash; أيها القارىء الكريم &ndash; الكتاب كاملاً :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\"><a class=\"LINK\" href=\"files/book/book1.pdf\" target=\"_blank\"><span style=\"line-height:30px\">تحميل كتاب أجازات الشيخ وأسانيده</span></a></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\"><span style=\"line-height:30px\">وكان الشيخ الباحث أحمد بن محمد سردار الحلبي الشافعي رحمه الله تعالى &nbsp;الذي أجازه الشيخ بمروياته قد جمع أربعين حديثاً من مرويات الشيخ الإمام في كتاب مستقل ، ذكر فيه أربعين حديثاً من اربعين كتاباً حديثياً وذكر أسانيد الشيخ الإمام إلى أصحاب هذه الكتب&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"font-family:Lotus\"><span style=\"font-size:24px\"><span style=\"line-height:30px\">ولتمام الفائدة رأيت أن أضع لك &ndash; أيها القارىء الكريم &ndash; الكتاب كاملا ً ، لتحميل الكتاب ، <a class=\"LINK\" href=\"index.php?page=Ym9vaw==&amp;op=ZGlzcGxheV9ib29rX2RldGFpbHNfdQ==&amp;book_id=OQ==&amp;lan=YXI=\" target=\"_blank\">انقر هنا</a></span></span></span></p>', 'ar', 10318, 50, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (37, 46, 'من كراماته المتنوعة', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كانت صفة الذل والانكسار لله تعالى ظاهرة عليه ، لا تخفى على من اجتمع به ، وكثيراً ما كان يقول :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ أنا عبد الله اسماً وصفة وتحققاً ، وإن شرفي وعزتي بعبوديتي وعبادتي لله تعالى ، وخدمتي لكتاب الله تعالى وأحاديث رسوله &nbsp;صلى الله عليه وسلم ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان متواضعاً مع عباد الله تعالى ، امتثالاً لأمره سبحانه بقوله :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ واخفض جناحك للمؤمنين } واتباعا لما &nbsp;جاء عن رسول الله &nbsp;صلى الله عليه وسلم أنه قال : [ وما تواضع عبد لله إلا رفعه الله تعالى &nbsp; ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يقول : [ مهما حاول المرء أن يأتي بجملة فيها معنى غاية التواضع للمؤمنين ، لما استطاع أن يقول جملة أبلغ وأفصح وأدق من قوله تعالى : { واخفض جناحك للمؤمنين }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يؤثر الخفاء والتستر على التظاهر والتفاخر ، ويذكر الحديث الذي رواه ابن ماجه والحاكم والبيهقي &nbsp; عن سيدنا معاذ &nbsp;رضي الله عنه &nbsp;أنه قال : قال رسول الله صلى الله عليه وسلم :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ اليسير من الرياء شرك ، ومن عادى أولياء الله فقد بارز الله بالمحاربة ، إن الله يحب الأبرار الأتقياء الأخفياء ، الذين إن غابوا لم يفتقدوا ، وإن حضروا لم يعرفوا ، قلوبهم مصابيح الهدى ، يخرجون من كل غبراء مظلمة ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أي : أن الله تعالى يحفظهم من الفتن التي يضل بها غيرهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان إذا سمع من أحد مدحاً وثناء عليه ، أو ذكراً لبعض كراماته بادر إلى القول :[ اللهم استرنا اللهم استرنا ] ويردد ما جاء عن سيدنا أبي بكر &nbsp;رضي الله عنه &nbsp;:[ اللهم اجعلني خيراً مما يظنون ، ولا تؤاخذني بما يقولون ، واغفر لي ما لا يعلمون ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن كلامه &nbsp;رضي الله عنه &nbsp;: [ إنه من خلال اطلاعي الواسع على حياة الصحابة رضي الله عنهم وسيرتهم ، لم أجد أحداً منهم تظاهر يوماً بكرامة ، أو تحدث عن أمر خارق للعادة ظهر على يده ، بل كان شأنهم الخفاء والتواضع ، لأنهم صادقون مخلصون لله تعالى ، يخافون من الرياء والسمعة ، مع أن الله تعالى شهد لهم بالإخلاص له سبحانه &nbsp;فقال :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ يبتغون فضلاً من الله ورضواناً } فلا غاية ولا قصد لهم إلا فضل الله ، ورضاه سبحانه وتعالى &nbsp;]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : ومن كراماته الشهيرة التي اعترف بها كل من جلس معه ، أنه يحدثك بكلام فيه أجوبة عن كل ما جال في فكرك من أسئلة واستفسارات ، وكثيراً ما يجد طلاب العلم عنده ما التبس عليهم فهمه من أمور علمية ، وقضايا شرعية ، بادرهم بالحديث عنها وبيانها ، قبل أن يسألوه عنها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وقد حصل معي هذا مرات عديدة ، حتى إنه مرة أجابني عن تسعة أسئلة كنت أعد نفسي لسؤاله عنها &nbsp;رضي الله عنه &nbsp;، وكان إذا أخبره أحد عن ذلك يتبسم ويقول :[ اللهم استرنا اللهم استرنا &nbsp;، الفضل كله لله ورسوله &nbsp;صلى الله عليه وسلم ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن كراماته التي تواترت ونقلت عنه ، أن الله تعالى يجيب دعاءه لمن شكا له العقم أو عقر زوجته ، فكم من أشخاص تعبوا وقاسوا ، وعجز الطب عن دوائهم ، حتى يئسوا من الولد ، أمرهم شيخنا الإمام &nbsp;رضي الله عنه &nbsp;بتلاوة بعض الأسماء الإلهية بأعداد معينة ، وبدعوات مأثورة ، فأجابهم الله تعالى ووهبهم أولاداً .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكم من مريض محب شفاه الله تعالى بسبب شربة ماء كان شيخنا الإمام قد قرأ ونفث فيها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : ويضيق المجال بنا في هذه الكلمات اليسيرة الموجزة عن حياة شيخنا الإمام &nbsp;رضي الله عنه &nbsp;أن نستقضي جل ما ظهر على يده من كرامات ، وما أجرى الله على يده من خوارق عادات ، وأكتفي بذكر بعضها ، على أني سأسهب الكلام على ذلك في مؤلف واسع يتضمن ذكر مناقب شيخنا الإمام &nbsp;رضي الله عنه &nbsp;إن شاء الله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">*- خرج مرة كعادته في نزهة مع بعض أصحابه في السيارة ( حول البلدة ) ، وفي طريق العودة أسرعت طفلة لا تتجاوز السادسة من عمرها لتقطع الطريق ، ومرت أمام السيارة ، &nbsp;ولم يتمكن السائق من إيقاف السيارة فدهس الطفلة بالعجلات الأمامية والخلفية ، حتى ذكر من كان مع شيخنا الإمام أنهم سمعوا اختلاف أضلاعها والعجلات تمر فوقها ، وصاح الشيخ &nbsp;رضي الله عنه &nbsp;: الله أكبر ، ولما توقفت السيارة نزلوا منها ، ونظروا فإذا بالطفلة تنهض وتركض ولا بأس بها ، فتزاحم الناس على سيارة الشيخ لما سمعوا صوت المكابح ، ورأوا ما حصل ، وقد أخذتهم الدهشة ، ولما رأوا شيخنا الإمام داخل السيارة جعلوا يسلمون عليه ، ويقبلون يده ، فما كان منه إلا أن حمد الله تعالى على خفي لطفه سبحانه ، ودعا لهم ، وأمر بإكرام الطفلة وأهلها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">*- &nbsp;قدم أحد المهندسين من السودان للعمل في الدراسات والأبحاث الزراعية في شركة أجنبية تعرف باسم ( إيكاردا ) وقد استأجر داراً من رجل صالح محب لشيخنا الإمام ، مواظب على سماع دروسه ومجالسه ، وكان هذا المهندس قد شكا من حصى في إحدى كليتيه وأجمع الأطباء وقتها على صعوبة وخطورة العمل الجراحي لاستئصالها ، فرأى مرة في نومه شيخاً مهيباً ، منير الوجه ، حسن السمت ، يناوله كوب ماء ، ويأمره بشربه فشربه ، فاستيقظ من نومه حاقناً ، وأسرع لقضاء حاجته ، فاندفعت الحصى ولم يبقى في كليته شيء منها ، فأخبر جاره الرجل الصالح &ndash; مالك الدار &ndash; عن هذه الحادثة ووصف له ذلك الشيخ العظيم الذي رآه في المنام فقال له : سأصحبك معي لتتعرف عليه ، ومضى معه لسماع درس شيخنا الإمام في جامع بانقوسا ، فلما نظر المهندس إلى وجه شيخنا الإمام صاح : الله أكبر ، والتفت إلى جاره وقال له : هذا هو الذي أتاني في المنام ، وناولني كوب ماء ، وشفاني الله تعالى به ولما ذكر ذلك لشيخنا الإمام &nbsp;رضي الله عنه &nbsp;: قال له :[ إنك ممن تحب الله ورسوله &nbsp;صلى الله عليه وسلم ، وتحب الصالحين ، وقد أكرمك الله تعالى بذلك ، اللهم استرنا ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما توجه إلى بلاد الحجاز سنة /1375/ هـ &nbsp;، قاصداً حج بيت الله تعالى وزيارة سيدنا رسول الله &nbsp;صلى الله عليه وسلم ، تواتر عمن كان معه من أصحاب وأحباب كرامات كثيرة ، أكرم الله بها شيخنا الإمام &nbsp;رضي الله عنه &nbsp;، أكتفي بذكر واحدة منها : وهي أن واحداً من أصحابه المتقدمين ، ألم به مرض شديد ، فخشي عليه أهله أن يموت معهم في الطريق ، وشكوا أمرهم إلى شيخنا الإمام ، فدعا الله متوسلاً بسيدنا محمد رسول الله &nbsp;صلى الله عليه وسلم أن يرفع عنه هذا البلاء ، ويرده إلى أهله وبلده سالماً غانماً ، فبات تلك الليلة فرأى النبي &nbsp;صلى الله عليه وسلم في المنام وقدم إليه صحيفة فيها أسماء .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام :[ فنظرت فيها فقرأت فيها أسماء أصحابي الذين قدموا معي وسيعودون معي ، وبينهم ذلك الذي كان يعاني من المرض ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم إن شيخنا الإمام بشر أصحابه بذلك ، وما لبث ذلك الرجل أن عافاه الله تعالى ببركة سيدنا رسول الله &nbsp;صلى الله عليه وسلم وكان ممن عاد مع شيخنا الإمام إلى بلده وأهله .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكذلك لما حج سنة /1385/ هـ وصحبته السيدة الفاضلة والدتي أمدها الله تعالى وأكرمها &ndash; ومعه جمع من أصحابه &ndash; وجدوا أيضاً من الكرامات المتعددة ما أدهشهم وزادهم إيماناً ، كان أولها : أنهم لما كانوا في الطائرة ، وكانت من النوع القديم ، وتبلغ مدة الطيران من دمشق إلى جدة خمس أو ست ساعات زمنية ، تضررت بعض أسلاك الكهرباء في الطائرة ، وكان قائد الطائرة وأعوانه من الأوربيين ، حتى جعل بعضهم يمس سقف الطائرة فيجد فيه التوتر الكهربائي ، وظهر عليه الفزع والقلق ، وأعلم الركاب بذلك ، وأنهم على خطر ، فما كان من شيخنا الإمام إلا أن أخذ بالدعاء والتضرع إلى اله &nbsp;تعالى ، والتوسل برسول الله &nbsp;صلى الله عليه وسلم ، وقال لأصحابه : لا تفزعوا فإن الرسول &nbsp;صلى الله عليه وسلم قد قال : (( الحجاج والعمار وفد الله &ndash; أي : ضيوف الله &ndash; إن دعوه أجابهم ، وإن استغفروه غفر لهم &nbsp;))</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال شيخنا الإمام : [ وحقاً على المزور أن يكرم الزائر ، فكيف بمن قصد حج البيت الحرام ، وزيارة خير الأنام &nbsp;صلى الله عليه وسلم ؟!!!].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم إن الطائرة هبطت بسلام في مطار جدة ، وخرج قائدها من غرفته وقال للركاب : إن فيكم رجلاً عظيماً ذا شأن أنجانا الله تعالى بسببه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقبل وفاته &nbsp;رضي الله عنه &nbsp;بثلاث سنوات ، قدم إليه وفد من دولة بعيدة ، وشكوا إليه أن ابناً لأحد وجهاء البلد قد أصيب بمرض نفسي ، أعيا الأطباء علاجه ، وقد طاف به أهل البلاد ، حتى بلغوا بلاد الحجاز ومصر وغيرها ، فلم يسمعوا من علماء وفضلاء هذه البلاد إلا قولهم : ما عليكم إلا أن تقصدوا رجلاً في حلب ، لو أنه بصق عليه أو نظر إليه لشفاه الله تعالى ، وهو العلامة العارف الشيخ عبد الله سراج الدين رضي الله عنه ، وقد جئناك لهذا الغرض .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فقال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;: [ اللهم استرنا وأكرمنا وأكرم ضيوفنا ، ومن حسن ظنه بنا ، ولا تخيبنا ] ثم قرأ على ماء وأمرهم أن يشرب منها ، وأوصاهم بتلاوة بعض الآيات القرآنية ، والأدعية المأثورة عن سيدنا رسول الله &nbsp;صلى الله عليه وسلم في أوقات معينة مع المواظبة . ومضت عدة أشهر ، ما لبث فيها أن تماثل الولد للشفاء . والحمد لله رب العالمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نفحات محمدية &nbsp;صلى الله عليه وآله وسلم آثارها &ndash; بركاتها</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;:</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ كان سيدي الوالد &nbsp;رضي الله عنه &nbsp;قد قص علينا أنه رأى النبي &nbsp;صلى الله عليه وسلم في المنام ، وأمره أن يفتح فمه ، فتفل &nbsp;صلى الله عليه وسلم في فيه ريقاً من فمه الشريف &nbsp;صلى الله عليه وسلم ثم أمره &nbsp;صلى الله عليه وسلم أن يفتح فمه مرة أخرى ، فأخرج &nbsp;صلى الله عليه وسلم من صدره الشريف نخامة وتفلها في فم سيدي الوالد فابتلعها ، ثم ضرب على ظهر سيدي الوالد وقال له &nbsp;صلى الله عليه وسلم :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لا بأس عليك يا شيخ نجيب ، لا بأس عليك يا شيخ نجيب .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;يتأول هذه التفلات المحمدية بالعلوم الشرعية الظاهرة ، والعلوم العرفانية العالية ، وهي ما يعرف بعلم الحقائق والمعارف الإلهية ، وقد اشتهر عن الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;براعته فيها وتمكنه منها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;:[ وإن لهذه التفلات المحمدية آثاراً نورانية ، تسري في ذرية الشيخ محمد نجيب &nbsp;رضي الله عنه &nbsp;وقد أكرمني الله تعالى بأني رأيت النبي &nbsp;صلى الله عليه وسلم في المنام ، وذلك بعد وفاة والدي &nbsp;رضي الله عنه &nbsp;بفترة وجيزة ، رأيت والدي الكريم وقد أخذ بيدي ضمن حشد من العلماء والأولياء ، وكلهم ينتظرون قدومه &nbsp;صلى الله عليه وسلم ليتشرفوا بالسلام عليه &nbsp;صلى الله عليه وسلم ، فلما أقبل الرسول &nbsp;صلى الله عليه وسلم بطلعته البهية ، وأنواره الزهية ، ومعه عدد من صحابته الكرام ، وإلى جانبه السيدة عائشة أم المؤمنين رضي الله عنها ، وهي في غاية الحشمة والوقار ، فلما سلمت عليه &nbsp;صلى الله عليه وسلم تفل فوقعت التفلة المباركة على كتف السيدة عائشة رضي الله عنها ، فتقدمت وأخذتها وابتلعتها ، والحمد لله تعالى على ذلك ، ثم التفت فلم أر سيدي الوالد &nbsp;رضي الله عنه &nbsp; ثم استيقظت فرحاً مستبشراً وعلمت أن سيدي الوالد رضي الله عنه &nbsp;هو الذي قد أوصلني إلى حضرة النبي الأعظم &nbsp; صلى الله عليه وسلم &nbsp;، ونلت تلك التفلة المحمدية بأسرارها وأنوارها ، وفي ذلك قلت :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">صلاة الله تترى كل حين &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; على من حبه روح لروحي<br />\r\nويصحبها السلام بلا انتهاء &nbsp; &nbsp; &nbsp; على من ريقه منه فتوحي</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">خصائص وفضائل</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لقد غرس الشيخ الإمام &nbsp;رضي الله عنه &nbsp;محبة سيدنا رسول الله &nbsp;صلى الله عليه وسلم في قلوبنا وقلوب كل من لزمه ، أو لزم دروسه ومجالسه ، وحرضنا وحرضهم على بذل الجهد لاتباعه &nbsp;صلى الله عليه وسلم وإكثار الصلاة والسلام عليه &nbsp;صلى الله عليه وسلم ، كلمات جرت على لسان كل من استمع إلى دروس شيخنا الإمام رضي الله عنه أو حضر مجالسه أو قرأ بعضاً من كتبه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإذا كانت ألسنة الخلق أقلام الحق فلقد كان الشيخ الإمام &nbsp;رضي الله عنه &nbsp;حقاً من المحبين الصادقين الذين كانت محبة رسول الله &nbsp;صلى الله عليه وسلم في قلوبهم فوق محبة كل مخلوق وقد ظهر ذلك في أقواله وأفعاله وسائر شؤوناته فلم يك يخلو مجلس من مجالسه عن ذكر بعض شمائل سيدنا رسول الله &nbsp;صلى الله عليه وسلم وخصائصه وفضائله كما أنه لم يدع موضوعاً أو بحثاً من الأبحاث التي تكلم عنها في كتبه إلا وضمنها ذكر بعض صفاته وخصاله &nbsp;صلى الله عليه وسلم حسب ما تقتضيه المناسبة وهكذا .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يعتبر ذلك من مقتضيات الإيمان الصحيح إذ قال &nbsp;صلى الله عليه وسلم :[ لا يؤمن أحدكم حتى أكون أحب إليه من نفسه ووالده وولده والناس أجمعين &nbsp;]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد أسهب &nbsp;رضي الله عنه &nbsp;في الكلام على محبة سيدنا رسول الله &nbsp;صلى الله عليه وسلم في عدد من كتبه منها : كتاب ( حول تفسير سورة الكوثر ) وكتاب ( الصلاة على النبي &nbsp;صلى الله عليه وسلم ) وكتاب ( حول تفسير سورة الحجرات ) وغيرها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وذكر فيها وجوب محبة الرسول &nbsp;صلى الله عليه وسلم على كل مؤمن وفضائلها وآثارها وسرد في ذلك أدلة كثيرة من الكتاب والسنة وما كان عليه سلف هذه الأمة من المحبة لرسول الله &nbsp;صلى الله عليه وسلم والأدب معه &nbsp;صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يقول : [ من زعم أننا بالغنا في محبة رسول الله &nbsp;صلى الله عليه وسلم وتعظيمه والأدب معه &nbsp;صلى الله عليه وسلم فقد أخطأ خطأ كبيراً وكشف عن جهله بمقام رسول الله &nbsp;صلى الله عليه وسلم وإننا لم نبلغ الحد الأدنى المطلوب منا في محبته وتوقيره والأدب معه &nbsp;صلى الله عليه وسلم حتى يقال : لقد بالغنا ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">واعلم أن قضايا الإيمان كلها إنما هي معقولة مقبولة عند أصحاب العقول المجردة من الأهواء والشبهات إن هم تفكروا وتبصروا ولما كانت محبة رسول الله &nbsp;صلى الله عليه وسلم فوق محبة كل مخلوق أمراً هاماً من قضايا الإيمان : سلم به وأذعن له العقلاء والفطناء لأنهم علموا وأدركوا أن سبب المحبة يعود إلى أمرين هما الكمال والنوال فلو بحث العاقل عن صفات الكمال كلها لوجدها مجتمعة في رسول الله &nbsp;صلى الله عليه وسلم على وجه فريد لا يساويه فيها غيره ، بل إن الرسول &nbsp;صلى الله عليه وسلم جاء يفيض على الناس صفات الكمال والمحاسن وهذا مقتضى قوله تعالى :{ ويزكيكم } والتزكية هي التخلي عن النقائص والرذائل والتحلي بالكمالات والفضائل .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما صفة النوال وهو الكرم والجود والسخاء وهي صفات محبوبة لدى كل إنسان فإن خير من جاء بها وأمر بها هو سيدنا رسول الله &nbsp;صلى الله عليه وسلم الذي قال الله فيه :{ وما أرسلناك إلا رحمة للعالمين } أي : لكل العالمين في جميع العالمين أي : العوالم التي يمر عليها كل إنسان .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإذا وجد هناك إنسان عظيم يريد لك الخير أكثر مما تريده لنفسك ويحرص على سعادتك ويشق ويصعب عليه ما فيه إحراج ومشقة عليك ألا يجب أن تحبه أكثر من محبتك لنفسك ؟</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">بلى إن هذا أمر معقول مقبول عند من أنصف وتفكر وفي هذا يقول تعالى :{ لقد جاءكم رسول من أنفسكم عزيز عليه ما عنتم } أي : يصعب عليه ما فيه عنت لكم { حريص عليكم } أي : على هدايتكم وصلاحكم ونفعكم وسعادتكم في الدنيا والآخرة { بالمؤمنين رؤوف رحيم } أي : يسعى في دفع الأذى والضر عنهم ويجلب الخير بأنواعه لهم &nbsp;وقال تعالى :{ النبي أولى بالمؤمنين من أنفسهم } أي :- أحق بهم من أنفسهم وأرحم بهم من أنفسهم &ndash; ولذلك قال &nbsp;صلى الله عليه وسلم &nbsp;لما نزلت هذه الآية :[ ما من مؤمن وإلا وأنا أولى الناس به في الدنيا والآخرة ، اقرؤوا إن شئتم :{ النبي أولى بالمؤمنين من أنفسهم } فأيما مؤمن ترك مالاً فليرثه عصبته من كانوا وإن ترك ديناً أو ضياعاً فليأتني فأنا مولاه ].&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد نال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;مقامات كبيرة في محبة سيدنا رسول الله &nbsp;صلى الله عليه وسلم واتباعه في الأقوال والأفعال والأخلاق والآداب لأن المحبة الصادقة وإن كانت من أعمال القلوب لابد أن يظهر أثرها على الجوارح وذلك باتباع المحبوب في جميع ما ورد عنه &nbsp;صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد جعل &nbsp;رضي الله عنه &nbsp;نفسه رهن إشارة سيدنا رسول الله &nbsp;صلى الله عليه وسلم فكان لا يقدم على أمر ذي بال حتى يأتيه إذن صريح به من سيدنا رسول الله &nbsp;صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;كثيراً ما يحرض ويدعو إلى قراءة كتابه [ سيدنا محمد رسول الله &nbsp;صلى الله عليه وسلم شمائله الحميدة &ndash; خصاله المجيدة ] ويقول :[ لا لأنه كتاب من جمعي وتأليفي بل لأني ذكرت فيه جوانب متعددة من شمائله &nbsp;صلى الله عليه وسلم وخصاله وفضائله وخصائصه والتي يجب على كل مؤمن أن يتعرف عليها لتزداد محبته لسيدنا رسول الله &nbsp;صلى الله عليه وسلم ويصح ويكمل إيمانه برسول الله &nbsp;صلى الله عليه وسلم ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كما كان &nbsp;رضي الله عنه &nbsp;كثيراً ما يحرض الناس على الإكثار من الصلاة والسلام على سيدنا رسول الله &nbsp;صلى الله عليه وسلم لما لها من فوائد وآثار وفضائل وأن يجعلوا ذلك من جملة أورادهم اليومية بالإضافة إلى قراءة جزء من القرآن الكريم وبقية الأذكار التي ندب إليها سيدنا رسول الله &nbsp;صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يقرأ قصة المولد النبوي الشريف للإمام البرزنجي &nbsp;رضي الله عنه &nbsp;بمناسبة ولادته &nbsp;صلى الله عليه وسلم في شهر ربيع الأنور وذلك وقت الدرس في جامع بانقوسا والجامع الكبير وجامع الحموي وفي جلسة خاصة لطلاب العلم في المدرسة الشعبانية ويرغب الناس في إقامة تلك الحفلات التي تعبر عن الابتهاج والفرح بمولد الرسول &nbsp;صلى الله عليه وسلم مع مراعاة الآداب الشرعية في تلك المجالس لأنها مجالس عبادة تنطوي على تلاوة آيات من القرآن الكريم وذكر لله تعالى وصلاة على النبي &nbsp;صلى الله عليه وسلم وسماع لدرر من شمائله وأخلاقه الشريفة &nbsp; صلى الله عليه وسلم فينبغي على كل مؤمن أن يلتزم جانب الأدب في تلك المجالس .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن نظم الصلاة على النبي &nbsp;صلى الله عليه وسلم المأثورة عنه &nbsp;رضي الله عنه &nbsp;: [ اللهم صل على سيدنا محمد عبدك ورسولك النبي الأمي وعلى آله وصحبه وسلم تسليماً ، اللهم صل على سيدنا محمد صلاة ترضيك وترضيه وترضى بها عنا يارب العالمين ، وعلى آله وصحبه وسلم تسليماً . اللهم صل على سيدنا محمد بقدر حبك فيه ، وفرج عني وعن المسلمين ما نحن فيه ، وعلى آله وصحبه وسلم تسليماً ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والفرج يتضمن معنى رفع الكرب والشدائد والمصاعب والهموم والغموم . ومنها :&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ اللهم صل على سيدنا محمد صلاة تغفر بها ذنوبنا وتشرح بها صدورنا وتفرج بها كروبنا وتنور بها قلوبنا وتلهمنا بها رشدنا وتحفظنا بها من كل سوء ومكروه في الدنيا والآخرة يا رب العالمين وعلى آله وصحبه وسلم تسليماً ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومنها :[ اللهم يا دائم الفضل على البرية يا باسط اليدين بالعطية يا صاحب المواهب السنية يا غافر الذنب والخطية صل وسلم وبارك على سيدنا محمد خير الورى سجية وعلى آله وأصحابه البررة النقية في كل لمحة ونفس وغدوة وعشية وفرج عنا كل شدة ورزية بجاه إشراقات الطلعة المحمدية &nbsp;صلى الله عليه وآله وسلم وأسرارها البهية يا رب البرية ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومنها : [ اللهم صل على سيدنا محمد مفتاح خزائنك اللهم افتح لنا بسيدنا محمد صلى الله عليه وآله وسلم ما أغلق علينا من خزائن أسرارك وأنوارك ومشاهداتك وتجلياتك يا رب العالمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم صل على سيدنا محمد النبي الأمي وعلى آله وصحبه وسلم تسليماً ].<br />\r\nومنها :[ اللهم صل على سيدنا محمد حق قدره ومقداره العظيم صلاة دائمة مقبولة تؤدي بها عنا حقه العظيم وعلى آله وصحبه وسلم تسليماً ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومنها : [ اللهم صل على سيدنا محمد الذي أرسلته رحمة للعالمين وبالمؤمنين رؤوف رحيم ، وعلى آله وصحبه وسلم تسليماً ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">بشائر و حقائق</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان شيخنا الإمام &nbsp;رضي الله عنه &nbsp;كثيراً ما يقول في مجالسه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">( إنما نحن وقوف على باب سيدنا رسول الله &nbsp;صلى الله عليه وسلم ، نلتمس من أسراره وأنواره ، وبركاته ونفحاته &nbsp;صلى الله عليه وسلم ) ويشير إلى صورة المواجهة الشريفة للحجرة النبوية وهي معلقة فوق أريكة جلوسه ، ويردد هذه الأبيات :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عبد بالباب يرتجي لثم الأعتاب &nbsp; &nbsp; &nbsp; &nbsp; جد بالجواب مرحباً قد قبلناك</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;حريصاً كل الحرص على اتباع سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;والعمل بسنته ، فيما جاء عنه من أقوال وأفعال وأخلاق وآداب ، وأخبرنا مرة أنه كان يضع العمة على رأسه دون أن يضع فوقها طيلسان ، فرأى النبي &nbsp;صلى الله عليه وسلم في المنام وعلى رأسه العمة الشريفة وفوقها الطيلسان ، وقال لشيخنا :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">( هكذا ) ، قال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;: ( فلم أدع وضعه فوق العمة شتاء ولا صيفاً ). قلت : فكان الطيلسان أيام الشتاء من الصوف ، وأيام الصيف من القطن الرقيق ، وكان قد أخبر قبل وفاته &nbsp;رضي الله عنه &nbsp;بسنوات قليلة أنه رأى النبي &nbsp;صلى الله عليه وسلم في المنام وهو يقول له :[ إني مسافر إلى المدينة المنورة ومتى فرغت من عملك فاتبعني ] قال شيخنا الإمام :[ وكنت وقتئذ مشغولاً ببعض الأمور ، وقد استبشرت لتلك الرؤيا ، وسألت الله تعالى أن أكون متبعاً لرسول الله &nbsp;صلى الله عليه وسلم ، وأن أكون معه &nbsp;صلى الله عليه وسلم في جميع العوالم ] وأخبر شيخنا الإمام &nbsp;رضي الله عنه &nbsp;قبل وفاته بأشهر قليلة أنه رأى النبي &nbsp;صلى الله عليه وسلم يقظة ، وقد دخل عليه من الباب الغربي لغرفته التي كان يجلس فيها وهي تطل على الجهة الجنوبية القبلية ، ثم استبطأ الكلام وغلبه البكاء، وقد منعنا الحياء والأدب من سؤاله مرة أخرى عن تفصيل ذلك إلا أنه &nbsp;رضي الله عنه &nbsp;أكد على أن الأمر كان يقظة وكان قد رآه &nbsp;صلى الله عليه وسلم يقظة قبل سفره إلى المدينة المنورة بنحو سنتين وكان يردد هذه الأبيات من نظمه :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">يا ليت عيني تنظرا &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;جمال ذاك المظهرا<br />\r\nحتى أكون نيرا &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; مهللاً مستبشرا<br />\r\nفجر الضيا تفجرا &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;من ثغر سيد الورى&nbsp;<br />\r\nوالشمس فيه أشرقت &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;أنواره بلا امترا<br />\r\nسار الجمال تائهاً &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;لما بدا تحيرا<br />\r\nخر ذليلاً ساجداً &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;مهللاً مكبرا<br />\r\nيا ربنا بجاهه &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;أسعد فقير الفقرا<br />\r\nوامنحه دوماً عطفه &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; والطف إلهي واسترا<br />\r\nبفضل من أرسلته &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;خير رسول للورى<br />\r\nثم الصلاة دائماً &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;عليه ما تال قرا<br />\r\nوآله وصحبه &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ساداتنا غر الذرى</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عطايا إلهية ومنح محمدية &nbsp;صلى الله عليه وسلم</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان شيخنا الإمام &nbsp;رضي الله عنه &nbsp;كثيراً ما يتردد على لسانه الدعاء المأثور عن سيدنا رسول الله &nbsp;صلى الله عليه وسلم :[ وتولني فيمن توليت ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والدعاء :[ ولا تكلني إلى نفسي &nbsp;ولا إلى أحد من خلقك &nbsp;طرفة عين ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن دعائه المشهور في ختم المجالس :[ وتولنا بما توليت به عبادك الصالحين بقولك :{ وهو يتولى الصالحين } .<br />\r\nفلقد كان &nbsp;رضي الله عنه &nbsp;يتوجه إلى الله تعالى في أموره كلها ، ويعتمد عليه ويتوكل عليه ، ويولي أمره كله إليه ، فتولاه الله تعالى بعنايته ورعايته الخاصة ، فترى أن حركاته وأقواله وأفعاله كلها صائبة سديدة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إذ كان لا يقدم على أمر له شأنه إلا بإذن صريح من سيدنا رسول الله &nbsp;صلى الله عليه وسلم يأتيه ذلك إما بإشارة غيبية أو برؤيا منامية صالحة صادقة ولقد رهن نفسه وحياته لخدمة كتاب الله تعالى وسنة رسوله &nbsp;صلى الله عليه وسلم فكان يكثر من الدعاء :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم واجعلنا أنصاراً لدينك وشريعتك وسنة نبيك سيدنا محمد &nbsp;صلى الله عليه وسلم</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد كانت منن الله تعالى عليه عظيمة وهباته جليلة ظهر ذلك في فيض الله تعالى عليه بالمعارف إلهية ورسوخه في العلوم الدينية وأن أيده سبحانه ببراهين وأدلة الكتاب والسنة وألقى محبته وإجلاله في قلوب العباد فلا يذكر عند أحد إلا ترافق ذلك بالمدح والثناء ونال ثقة الناس كلهم فإذا تكلم أنصتوا وإذا أمرهم امتثلوا وقد ذاع صيته في شتى البلدان وجرى ذكره على لسان أهل العلم والعرفان تصديقاً لقول النبي الأعظم &nbsp;صلى الله عليه وسلم :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ إن المقة من الله والصيت من السماء ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكثيراً ما يلجأ إليه العلماء لحل معضلات ، وبيان شبهات .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد أكرمه الله تعالى بنيل مراتب متعددة ، بشرف خدمته للنبي الأعظم سيدنا محمد &nbsp;صلى الله عليه وسلم ، جاء ذلك في عدة مناسبات رأى فيها حضرة النبي الأعظم &nbsp;صلى الله عليه وسلم &nbsp;في المنام ، وقد وظفه خادماً له &nbsp;صلى الله عليه وسلم ، ولمن يلوذ به &nbsp;صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">خدمته لماء وضوئه وغسله &nbsp;صلى الله عليه وسلم</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">رأى شيخنا الإمام النبي &nbsp;صلى الله عليه وسلم في المنام ، وقد وظفه خادماً لماء غسله ووضوئه &nbsp;صلى الله عليه وسلم ، وقد استلم شيخنا الإمام هذه الوظيفة وقام بها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إذ رأى في المنام أن النبي &nbsp;صلى الله عليه وسلم قدم مع أصحابه من سفر ، وعليه غيار السفر ، فأمر شيخنا الإمام وأحد الصحابة معه أن يحضرا له ماء ليغتسل به &nbsp;صلى الله عليه وسلم ، قال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;:[ فانطلقت مع الصحابي ، وغالب ظني أنه سيدنا ربيعة بن كعب الأسلمي &nbsp;رضي الله عنه &nbsp;، الذي كان يخدم النبي &nbsp;صلى الله عليه وسلم في الحياة الدنيوية ، كما دلت على ذلك الأحاديث الصحيحة ]&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال : [ فانطلقنا إلى طست ماء كبير ، وحملناه على مرجل حتى إذا صارت حرارته مناسبة ، جئنا به إلى رسول الله &nbsp;صلى الله عليه وسلم ، فنظر إليه وأعجبه ، فالتفت إلي وقال : أنت خادم لي ملازم ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام &nbsp;رضي الله عنه &nbsp;: [ فقلت في نفسي : يالها من سعادة وكرامة محمدية ، إن الناس يتمنى أحدهم لو يخدم النبي &nbsp;صلى الله عليه وسلم ولو ساعة ، وقد وظفني رسول الله &nbsp;صلى الله عليه وسلم خادماً ملازماً له !! ولم يكن فرحي برسول الله &nbsp;صلى الله عليه وسلم يعادله شيء ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">خدمته لحجرات سيدنا رسول الله &nbsp;صلى الله عليه وسلم وتعهده بيت المؤنة</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">رأى النبي &nbsp;صلى الله عليه وسلم في المنام وقد وظفه خادماً عنده لبيت المؤنة ، فاستلم تلك الوظيفة ، وقام بها خير قيام ، فأقبل &nbsp;صلى الله عليه وسلم ونظر في المكان المخصص للمؤنة ، وسره ما فيه ، فنظر إلى شيخنا الإمام متبسماً ، وعلى وجهه الشريف &nbsp;صلى الله عليه وسلم علامة القبول والرضا.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">خدمته للبيت الذي يجتمع فيه الأنبياء عليهم صلاة الله وسلامه</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ورأى النبي &nbsp;صلى الله عليه وسلم في المنام وقد وظفه خادماً لبيت يجتمع فيه الأنبياء عليهم الصلاة والسلام ، فقام بتلك الوظيفة ، وهيأ البيت وأعده ، واجتمع الأنبياء عليهم السلام ينتظرون تشريفه &nbsp;صلى الله عليه وسلم ، فلما أقبل &nbsp;صلى الله عليه وسلم بطلعته البهية ، وأنواره الزهية ، قام شيخنا الإمام لاستقباله ، ومشى بين يديه مشية الخادم بين يدي سيده .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام : فنظرت في المكان فرأيت سلة فيها أشياء مهملة ، فقلت في نفسي : من أين أتت هذه ؟ فأسرعت ورميتها بعيداً من نافذة المكان .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم جلس رسول الله &nbsp;صلى الله عليه وسلم وقال لي : أين خليل الله إبراهيم ؟</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : لما يأت ، ثم طرق الباب ، فنهض رسول الله &nbsp;صلى الله عليه وسلم لاستقبال خليل الله عليه السلام وأنا خلفه ، فسلم عليه وعانقه ، وطال الحديث بينهما ، ثم التفت إلي &nbsp;صلى الله عليه وسلم وقال لي : سلم على خليل الله ثم اتبعني ، فأقبلت إليه وكان وضيء الوجه &nbsp;، مهيباً جليلاً ، فقبلت يده ، ووجهي عند صدره ، أتمسح به ، وأطلب منه الدعاء ، حتى غلبني البكاء فانتبهت ] .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وقد نظم شيخنا الإمام رضي الله عنه أبياتاً يذكر فيها نعمة الله عليه ، ويشكر فضل الله عليه بهذه المراتب في خدمة النبي &nbsp;صلى الله عليه وسلم ، ومنها :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عبد ذليل تحت راية مجدكم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;من شأنه الإطراق والإصغاء<br />\r\nلا تحرموني فضل جودكم الذي &nbsp; &nbsp; &nbsp; شهدت به الخضراء والغبراء<br />\r\nأرجوكم يا سيدي من فضلكم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;نفحات وصل ليس فيه جفاء<br />\r\nلكم الأيادي البيض حيث قبلتموني &nbsp; خادماً شكري لكم وثناء&nbsp;<br />\r\nفلكم وكم أكرمتموني عطفكم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;فلنعم ذاك العطف والإيواء<br />\r\nبجواركم شرفي وغاية منيتي &nbsp; &nbsp; &nbsp; &nbsp; وبقربكم حقاً يزول الداء<br />\r\nأشهدتموني نور وجهكم الذي &nbsp; &nbsp; &nbsp; &nbsp; إشراقه للشمس منه ضياء<br />\r\nأنا خادم لبيوتكم وضيوفكم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;وامنيتي ومسرتي وهناء<br />\r\nعن بابكم لا أنثني طول المدى &nbsp; &nbsp; &nbsp; أرجو القبول فأنتم الكرماء</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;كثيراً ما يقص هذه الرؤى على أصحابه وأحبابه ويقول :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ إن خدمة رسول الله &nbsp;صلى الله عليه وسلم تعني خدمة دينه وسنته &nbsp;صلى الله عليه وسلم ، بنشر العلوم الشرعية وتعليمها للناس على وجه يرضاه الله ورسوله &nbsp;صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإن العلوم الشرعية أمانة في أعناق العلماء ، عليهم أن يؤدوها بصدق وإخلاص ، كما كان عليه الصحابة وسلف هذه الأمة رضي الله عنهم ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وذكر &nbsp;رضي الله عنه &nbsp;أنه رأى النبي &nbsp;صلى الله عليه وسلم في المنام وقد وظفه مؤذناً عنده ، وقد أذن &nbsp;رضي الله عنه &nbsp;لصلاة الظهر بين يدي رسول الله &nbsp;صلى الله عليه وسلم ، وتقدم النبي &nbsp;صلى الله عليه وسلم وصلى إماماً في عدد من الصحابة ، وفيهم سيدنا أبو بكر وسيدنا عمر رضي الله عنهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام :[ ووقفت في الصلاة خلف النبي &nbsp;صلى الله عليه وسلم مباشرة ، وجعلت أنظر إليه &nbsp;، ولما فرغ من الصلاة وسلم يميناً وشمالاً بهرتني أنوار خديه &nbsp;صلى الله عليه وسلم وأنا أنظر إليها ]<br />\r\n&nbsp;<br />\r\nوكان &nbsp;رضي الله عنه &nbsp;يفتخر بتلك الوظيفة المحمدية &nbsp;صلى الله عليه وسلم ويقول :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ الأذان هو دعوة العباد إلى الله تعالى وإلى عبادته بالصلاة ، وإني أدعو الناس إلى الله للتمسك بدينه وسنة نبيه &nbsp;صلى الله عليه وسلم وذلك من خلال الدروس والمجالس العلمية ، وتأليف الكتب التي فيها ما يحتاجه الناس لفهم أمور دينهم ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">-------------------------------------------------------------------------</span></span><br />\r\n<span style=\"font-size:18px\"><span style=\"font-family:Lotus\">1رواه الإمام مسلم في الصحيح /2588/ ( 5/2527) والترمذي في &nbsp;( السنن ) /2030/ ( 6/230 ) عن سيدنا أبي هريرة &nbsp;رضي الله عنه &nbsp;.&nbsp;<br />\r\n2 ابن ماجه /3989/ ( 2/1320 ) والحاكم ( 1/4 ) و ( 3/270) البيهقي في الزهد الكبير (195) .<br />\r\n3 رواه النسائي ( 5/113/ وابن ماجه /2892/ (2/966) وابن خزيمة /2511/.<br />\r\n4 رواه الشيخان والنسائي وأحمد &ndash; واللفظ له &ndash; عن سيدنا أنس &nbsp;رضي الله عنه &nbsp;.<br />\r\n5 رواه الإمام البخاري كتاب التفسير / 4781/ (8/517) .<br />\r\n6 هذا طرف من الحديث الذي علمه سيدنا رسول الله صلى الله عليه وسلم &nbsp;لسيدنا الحسن بن علي رضي الله عنهما ، أن يقوله في الوتر .<br />\r\nوهو عند الترمذي في كتاب الصلاة ، باب ما جاء في القنوت في الوتر [ 464] [2-184] وعند أبي داود والنسائي وابن ماجه وغيرهم .<br />\r\n7 الحديث في [ سنن] أبي داود كتاب الأدب [ 5090] [5-325] ونصه :[ دعوات المكروب : اللهم رحمتك أرجو ، فلا تكلني إلى نفسي طرفة عين ، وأصلح لي شأني كله ، لاإله إلا أنت ].<br />\r\n8 المقة : المحبة وهي بكسر الميم وفتح القاف والحديث رواه الإمام أحمد والطبراني عن سيدنا أبي أمامة &nbsp;رضي الله عنه &nbsp; ( مجمع الزوائد ) (10/271) .<br />\r\n9 ينظر [ صحيح ] مسلم /489/ ( 2/638) و(المسند ) للإمام أحمد (4/59) و( مجمع الزوائد ) (2/249) .</span></span></p>', 'ar', 15244, 60, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (38, 46, 'جواره الحبيب الأعظم', '<p style=\"text-align:center; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\"><img alt=\"\" src=\"/other_files/Image/pic_001.jpg\" style=\"height:164px; width:200px\" /></span></span></span></p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">جواره الحبيب الأعظم &nbsp;صلى الله عليه وسلم &nbsp;في المدينة المنورة بأنواره &nbsp;صلى الله عليه وسلم&nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان ذلك في شهر ربيع الأنور من عام / 1400/ للهجرة الشريفة ، وحتى شهر شعبان من عام / 1403/ للهجرة الشريفة فجاور في المدينة المنورة ما يزيد على ثلاث سنوات ونصف السنة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان سفره للحجاز لأداء العمرة المباركة والزيارة الشريفة لخير خلق الله سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم مكث في المدينة المنورة تلك المدة امتثالاً لأمر سيدنا رسول الله &nbsp;صلى الله عليه وسلم ،&nbsp;جاءه ذلك في رؤيا منامية وإشارات غيبية ، إذ لم يكن يقدم على أمر ذي بال حتى يأتيه الإذن به من سيدنا رسول الله صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد كان فرحه وبهجته بجوار سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;لا يوازيه شيء ، إذ كان ذلك غايته ومنيته ، وكان جوابه إذا سأله أحد من أحبابه عن حاله يقول :[ الحمد لله الذي أحلنا دار المقامة من فضله ، فلا دار بعد دار رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، ولا إقامة ترجى بعد الإقامة بجوار رسول الله &nbsp;صلى الله عليه وسلم &nbsp;].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن أقواله &nbsp;رضي الله عنه &nbsp;في بعض مخطوطاته :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقلت إذ حللت في المدينة المنورة بأنواره الشريفة &nbsp;صلى الله عليه وسلم &nbsp;:</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">يا قلب بشراك أيام الرضا رجعت &nbsp; &nbsp; &nbsp;وهذه الدار للأحباب قد جمعت<br />\r\nأما ترى نفحات الحي قد عبقت &nbsp; &nbsp; &nbsp; &nbsp;من طيبة وبروق القرب قد لمعت<br />\r\nفعش هنيئاً بوصل غير منفصل &nbsp; &nbsp; &nbsp; &nbsp; مع من تحب فحجب الهجر قد رفعت<br />\r\nواشهد جمال الذي من أجل طلعته &nbsp; &nbsp; قلوب عشاقه من نوره انصدعت<br />\r\nوأبشر بنبيل الذي قد كنت تأمله &nbsp; &nbsp; &nbsp;من طلعة المصطفى شمس السما طلعت</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">صلى الله عليه وآله وسلم أبداً أبداً أبداً</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يقول :[ إذا كان جار الكرام لا يضام ، بل يكون في رغد وسلام ، فكيف حال من جاور سيد الكرام سيدنا محمداً &nbsp;صلى الله عليه وسلم &nbsp;، أكرم الأولين والآخرين على رب العالمين ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد حرم رسول الله &nbsp;صلى الله عليه وسلم &nbsp;المدينة المنورة ، ودعا لها ولأهلها بالخير والبركة ، ودفع الشدة والبلوى عنها ، ووعد &nbsp;صلى الله عليه وسلم &nbsp;بالشهادة والشفاعة الخاصة لمن جاور فيها أو مات فيها ، كل ذلك جاء في أحاديث وردت عنه &nbsp;صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد توالت عليه الكرامات والنفحات الإلهية المحمدية ، مما جعله يترقى في مقامات القرب من الله تعالى ، وتواردت عليه البشائر بالرؤى المنامية ، وعلى لسان المحبين الصالحين من أهل المدينة وغيرها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقص علينا عدة رؤى سأذكر تفصيلها في كتاب مستقل حول مناقبه &nbsp;رضي الله عنه &nbsp;إن شاء الله تعالى ، ومنها أنه رأى شهادته بأن لا إله إلا الله محمد رسول الله &nbsp;صلى الله عليه وسلم &nbsp;مقبولة عند الله تعالى وعند رسوله &nbsp;صلى الله عليه وسلم &nbsp;، وقد خط على باب الكعبة المشرفة أن شهادة عبد الله سراج الدين مقبولة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ورأى أنه دخل المسجد النبوي من باب السلام ، فاستقبله جمع من الأولياء رضي الله عنهم ، وأجلسوه في مكان مهيأ لجلوس القطب في غرفة واسعة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ورأى مرة السيدة &nbsp;الكبرى فاطمة رضي الله عنها وقد بسطت لحافها ، وهو لحاف كبير واسع ، ومناد ينادي : من يضم رأسه تحت هذا اللحاف ينال السعادة والأمان ، فتقدم &nbsp;رضي الله عنه &nbsp;والسيدة الزهراء رضي الله عنها تنظر إليه ، وأدخل رأسه وجسمه كله تحت الحاف وارتفعت الأصوات : لقد فاز ... لقد فاز .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ورأى النبي الأعظم &nbsp;صلى الله عليه وسلم &nbsp;في المنام ، وهو يأمر سيدنا علياً &nbsp;رضي الله عنه &nbsp;، أن يأتي بعباءته الشريفة &nbsp;صلى الله عليه وسلم &nbsp;ليخلعها على شيخنا الإمام &nbsp;رضي الله عنه &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تفرغ أيام مجاورته في المدينة المنورة لعبادة الله تعالى ، وتصنيف الكتب العلمية الدينية ، وكم كان رجاؤه عظيماً أن يخدم بلد رسول الله &nbsp;صلى الله عليه وسلم &nbsp;بعمل خير يبقى نفعه وأثره جارياً ، فحقق الله تعالى رجاءه ، إذ جعله سبباً وواسطة في إنشاء مدرسة لتلاوة القرآن الكريم وتحفيظه وقراءاته وقراءة حديث رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، ولا يزال هذا الصرح باقياً ، يقوم عليه خيرة أهل العلم &nbsp;والصلاح ، ويخرج عدداً من طلاب العلم وحفظة القرآن الكريم .والحمد لله رب العالمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يكثر الذهاب إلى مسجد سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;للصلاة فيه ، ولزيارة سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، فيدخل من باب السلام ، ويتوجه إلى الروضة الشريفة ، فيصلي ما يسر الله تعالى له ثم يتقدم ماشياً بأدب وخضوع ، ويقف إلى سارية أمام المواجهة الشريفة ، ويطيل الوقوف بذل وانكسار بين يدي من أرسله الله رحمة للعالمين ،وبالمؤمنين رؤوف رحيم &nbsp;صلى الله عليه وسلم &nbsp;، ويكثر الصلاة والسلام عليه &nbsp;صلى الله عليه وسلم &nbsp;، ويدعو الله متوسلاً به حتى إذا أذن له بالانصراف ، تراجع بأدب وتواضع ناحية الروضة الشريفة ، وصلى فيها وسأل الله تعالى و دعاه ، ثم يتوجه من حيث أتى ، ويخرج من باب السلام وقد اكتسى حلة نورانية محمدية يراها كل ذي بصيرة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وحصل مرة أن تبعه أحد المسؤولين عن خدمة الحجرة الشريفة وما حولها ، تبعه إلى خارج المسجد وسلم عليه وعانقه ، وبذل جهده في تقبيل يده ، لكن شيخنا الإمام لم يمكنه من ذلك أدباً وتواضعاً في مدينة رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، ثم قال هذا الرجل لشيخنا الإمام : والله لقد رأيت نوراً يخرج من الحجرة الشريفة ، ويمتد إليك ، ويمضي معك حيثما توجهت ، ولهذا لحقت بك لأبشرك وأتبرك بك ، فدعا له شيخنا الإمام &nbsp;رضي الله عنه &nbsp;، وسأله الدعاء له خاصة أمام المواجهة الشريفة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولم يكن حديثه في مجالسه يخلو من التذكير بالآداب الواجبة على من أقام في مدينة رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، أو جاور فيها ، أو قصدها لزيارة الحبيب الأعظم &nbsp;صلى الله عليه وسلم &nbsp;، والصلاة في مسجده عليه الصلاة والسلام . ويذكر في هذا السياق ما كان عليه سلفنا الصالح رضي الله عنهم ، ومنهم الإمام مالك بن أنس &nbsp;رضي الله عنه &nbsp;، إمام دار الهجرة ، وأحد الأئمة المجتهدين ، فكان يمشي في سكك المدينة المنورة حافياً ، ولا يركب مركوباً ، وإذا أراد قضاء حاجته ابتعد خارج أسوار المدينة ، أدباً مع سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، وتكريماً لأرض وطئتها أقدامه الشريفة &nbsp;صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإذا أراد التحديث في المسجد النبوي توضأ وتطيب ، ولبس ثياباً جدداً ، ولبس ساجاً وتعمم ، وإذا شرع في رواية الحديث خشع وأخذه الوجل والمهابة ، وتغير لونه إجلالاً لحديث رسول الله &nbsp;صلى الله عليه وسلم &nbsp;.وهكذا سائر علماء السلف رضي الله عنهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولم يرجع شيخنا الإمام &nbsp;رضي الله عنه &nbsp;إلى حلب إلا بعد أن جاءه الإذن من الحضرة المحمدية &nbsp;صلى الله عليه وسلم &nbsp;بالعودة وكان يقول :[ ذهبت بإذن وأقمت بإذن ورجعت بإذن ونسأل الله تعالى أن يتولانا في جميع قضايانا ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد استأنف دروسه المباركة بعد عودته ، وجعلت المدرسة الشعبانية تزهو برعايته وعنايته وإن لم تنقطع توجهاته ودعواته لها وللعاملين فيها طيلة فترة إقامته في المدينة المنورة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد اكتست مدينة حلب بعودته حلة البهاء والجمال ، وشعر أهلها بالأنس وراحة البال ، بعد أن بسط شيخنا الإمام مائدته فيها وأقبل الناس عليها . ويرحم الله تعالى القائل مخاطباً شيخنا &nbsp;رضي الله عنه &nbsp;:</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قدمت قدوم الغيث في المهمه الصعب&nbsp; &nbsp; &nbsp; أبا ابن سراج الدين جئت على الرحب<br />\r\nوهللت الأصحاب فيك وكبرت &nbsp; &nbsp; &nbsp; &nbsp;وزالت عن الأحشاء فادحة الكرب<br />\r\nأضاء على الشهباء نور سراجه &nbsp; &nbsp; &nbsp; &nbsp;ولاح عليها من سناه ضيا الشهب<br />\r\nوعاد عليها خيرها وسرورها &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; بتشريفه يا منية الروح والقلب<br />\r\nفأهلاً وسهلاً فيك ثم ومرحباً &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;فلا زلت مرعياً على البعد والقرب<br />\r\nوصل إلهي دائماً أبداً على &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; رسول الهدى المبعوث للعجم والعرب<br />\r\nوآل وصحب كلما قال قائل &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;قدمت قدوم الغيث في المهمه الصعب</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم إنه اعتزل الدروس العامة في أوائل عام /1410/ هـ بسبب اعتلال صحته ، وكان قد رأى في المنام مرات عديدة ما يشير إلى ذلك ، فالتزم بيته متوجهاً إلى الله تعالى ، واشتغل بجمع الكتب التي تنفع الناس في أمور دينهم .<br />\r\nوكان &nbsp;رضي الله عنه &nbsp;في هذه الفترة يختم القرآن الكريم كل ثلاث أو أربع ليال ، ويكثر من ذكر الله تعالى ، والتفكر والتدبر في كلامه سبحانه ، وقد أخبر أن الله تعالى تجلى عليه بالرؤيا في المنام عدة مرات ، قص علينا إحداها ، وذلك أنه رأى نفسه في بيت الله الحرام ، فألهمه الله تعالى أسماء إلهية راح يذكره بها ، فتجلى سبحانه عليه بالنور فقام وسجد له سبحانه وتعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><strong><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">تبركه بالأثر النبوي الشريف وتعظيمه له</span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان من عادته رضي الله عنه كل ليلة قبل أن يقوم إلى النوم &nbsp;أن يتناول الأثر الشريف بكلتا يديه ويتوجه إلى القبلة ويقبله ويمسح به عينيه ووجهه ورأسه وصدره ثم يبدأ الحاضرون من أولاده وأحفاده بالتقدم لتقبيله والتمسح به والأثر الشريف في يديه رضي الله عنه والألسنة تلهج بالصلاة والسلام على النبي صلى الله عليه وسلم حتى إذا فرغ الحاضرون من تقبيل الأثر الشريف والتبرك به بدأ شيخنا الإمام بالدعاء والتضرع إلى الله تعالى متوسلاً بسيدنا رسول الله صلى الله عليه وسلم وكان من دعائه : اللهم صل وسلم و بارك على سيدنا محمد وأزواجه وذريته وآل بيته وعلينا معهم أجمعين كما صليت وسلمت وباركت على سيدنا إبراهيم وعلى آل سيدنا إبراهيم في العالمين إنك حميد مجيد صلاة تشفينا بها من كل داء وتعافينا بها من كل بلاء وأفض علينا يا مولانا من بركاته صلى الله عليه وسلم وأنواره وأسراره ونفحاته نفحات محمدية تسعدنا بها في الدنيا والآخرة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان إذا اجتهد في الدعاء يردد هذه الأبيات :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إلى بابك العالي مددت يد الرجا &nbsp;ومن جاء ذاك الباب لا يختشي الردى&nbsp;<br />\r\nسألتك يا الله مستشفعاً بمن &nbsp; &nbsp; &nbsp; &nbsp; ضيا وجهه الوضاء يبرق في الدجى</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">صلى الله عليه وسلم أبداً أبداً</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويقول أيضاً:</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">بالذل قد وافيت بابك عالماً &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;أن التذلل عند بابك ينفع&nbsp;<br />\r\nوجعلت معتمدي عليك توكلاً &nbsp; &nbsp; &nbsp; &nbsp; وبسطت كفي سائلاً أتضرع<br />\r\nفبحق من أحببته وبعثته &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; وأجبت دعوة من به يتشفع<br />\r\nاجعل لنا من كل هم مخرجاً &nbsp; &nbsp; &nbsp; &nbsp; والطف بنا يا من إليه المرجع<br />\r\nثم الصلاة على النبي وآله &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;خير الورى ومن بهم يتشفع</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وصل اللهم وسلم على سيدنا محمد وعلى آله وصحبه عدد خلقك ورضاء نفسك وزنة عرشك ومداد كلماتك كلما ذكرك وذكره الذاكرون وغفل عن ذكرك وذكره الغافلون وعلينا معهم أجمعين وعلى والدينا ومشايخنا ومن له حق علينا وعلى جميع المؤمنين والمؤمنات والمسلمين والمسلمات .آمين والحمد لله رب العالمين .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان إذا مرض أو شكا ألماً لجأ إلى الأثر الشريف وقبله وتمسح به ودعا الله تعالى مستشفياً بأثر رسول الله صلى الله عليه وسلم الفياض بالخيرات والبركات .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">والأثر النبوي الشريف هو شعرة من شعر لحيته الشريفة صلى الله عليه وسلم من موضع العنفقة الشريفة لأنها في لونها إلى الشيب أقرب ، وما شاب من شعره الشريف إلا شعرات من &nbsp;عنفقته الشريفة المباركة صلى الله عليه وسلم ، وقد ورثها شيخنا الإمام عن مولانا الشيخ محمد نجيب رضي الله عنهما والتي كان جدي الفاضل السيد الحاج محمد ططري رحمه الله تعالى قد استوهبها من الشيخ عوني خلاصي رحمه الله تعالى وأهداها إلى مولانا الشيخ محمد نجيب رحمه الله تعالى ويؤيد صحة تسلسلها سند مرفق معها وهي موضوعة في زجاجة محكمة الإغلاق وفي نهايتها قليل من الشمع متصل بها ثم إن هذه الزجاجة موضوعة في أسطوانة مصنوعة من الذهب ونقش عليها :[لا إله إلا الله محمد رسول الله ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وهذه الأسطوانة ملفوفة بقطعة قماش أخضر وتفوح منها رائحة العطر الزكية دون أن يمسها أحد بطيب .وإن شيخنا الإمام رضي الله عنه كان يعظم هذا الأثر النبوي الشريف ويضعه في أعلى مكتبته الخاصة به &nbsp; رضي الله عنه &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><br />\r\n<span style=\"font-family:Lotus\">--------------------------------------------------------------------------------------<br />\r\n<span style=\"font-size:18px\">المفازة البعيدة ، والبلد المقفر &nbsp;.</span></span></p>', 'ar', 9217, 70, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (39, 46, 'قالوا عن الشيخ', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان شيخنا الإمام &nbsp; رضي الله عنه &nbsp;يحفظ من الأحاديث النبوية ما يزيد على مئة ألف حديث &nbsp;، فضلاً عن اطلاعه الواسع على كتب الحديث كلها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وحصل مرة أن تلاحى رجلان من أهل العلم من أحباب شيخنا الإمام &nbsp;رضي الله عنه &nbsp;، وممن كان يحضر دروسه ، وهما من أهل مدينة حماة ، حتى قال أحدهما للآخر : امرأتي طالق إن لم يكن شيخنا الإمام &nbsp;رضي الله عنه &nbsp;يحفظ أكثر من مئة ألف حديث ، ثم انطلقا إلى المدرسة الشعبانية ، لسؤال شيخنا الإمام واستفتائه عما جرى بينهما ، فأطرق شيخنا الإمام &nbsp;رضي الله عنه &nbsp;ثم قال للرجل الذي صدر منه لفظ الطلاق :[ امرأتك لا تطلق ، وأعظك أن تجنب لسانك ألفاظ الطلاق والحرام ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد حفظ شيخنا الإمام &nbsp;رضي الله عنه &nbsp;أيام طلبه العلم في المدرسة الخسروية كتاب ( تيسير الوصول إلى جامع الأصول لأحاديث الرسول &nbsp;صلى الله عليه وسلم &nbsp;) بمجلداته الأربع ، إلى أن حصل على كتاب ( جامع الأصول ) وهو كتاب يقع في أحد عشر مجلداً ، جمع فيه صاحبه &nbsp; الموطأ ، والصحيحين ، وسنن أبي داود والترمذي والنسائي ، ثم شرع في الإطلاع على كتب الحديث الأخرى كالسنن والمسانيد والمعاجم ، وحفظ منها جملة واسعة ، وفهرس طائفة واسعة لأحاديث مسند الإمام أحمد &nbsp;رضي الله عنه &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يعتمد في تفسير آيات الله تعالى على أحاديث سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;ويقول : [ إن أحاديثه &nbsp;صلى الله عليه وسلم &nbsp;كلها بيانات لمعاني القرآن الكريم ومقاصده ، لأن الله تعالى يقول : { وَأَنْزَلْنَا إِلَيْكَ الذِّكْرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيْهِمْ }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويسوق لذلك أدلة كثيرة قد ذكرها في بعض مؤلفاته ومحاضراته .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإني أذكر في هذه المناسبة كلمات يسيرة مما امتدحه بها كبار العلماء والمحدثين :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لما حج سنة /1385/ هـ خرج لاستقباله إلى مطار جدة العلامة المحدث الشيخ علوي المالكي وقال :[ هذا رجل يمشى إليه ولو على رموش العين ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولما أرسل كتاب [ سيدنا محمد رسول الله &nbsp;صلى الله عليه وسلم &nbsp;شمائله الحميدة وخصاله المجيدة ] إلى السيد الشيخ محمد أبي عبد العزيز ابن عبد الدائم الفلالي الموريتاني الشنقيطي صاحب كتاب ( النور المحمدي &nbsp;صلى الله عليه وسلم &nbsp;) وكان ممن جاور في المدينة المنورة على ساكنها أفضل الصلاة والسلام ، ثم اجتمع به لما ذهب إلى العمرة والزيارة &ndash; قال له الشيخ محمد أبي عبد العزيز :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ لقد عرفتك من كتابك ] &nbsp;يعني : لقد عرفت مقامك ومحبتك لسيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;من خلال قراءتي لكتابك الذي أرسلته هدية لي .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال الشيخ الكبير ، المحب الزاهد الورع ، السيد محمد أمين الكتبي &nbsp;لما لقي شيخنا في المسجد الحرام &nbsp;وسأله شيخنا الإمام أن يوصيه قال له :[ أوصيك بما أنت عليه ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال السيد الشيخ عبد القادر السقاف :[ يجب على كل عين أن تراه ] يعني : أن ترى شيخنا الإمام &nbsp;رضي الله عنه &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال العارف الكبير الشيخ أحمد الحارون الدمشقي لشيخنا الإمام &nbsp;رضي الله عنه &nbsp;:[ أنت محفوف بأنظار سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال له مرة أخرى : [ شمسك إذا طلعت غطت على الكل ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان المحب الزاهد ، ذو الكرامات الشهيرة ، الشيخ حسين العبد السلام ، المعروف ( بالمجدمي ) [1326 هـ - 1404هـ ] إذا قدم لزيارة شيخنا الإمام &nbsp;رضي الله عنه &nbsp;، ينشد مع أصحابه إذا خرج شيخنا لاستقباله عند باب الدار :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">أتيناكم أتيناكم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; وللأعتاب جئناكم<br />\r\nوفي أمر قصدناكم &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;فشدوا عزمنا بالله</span></span></span></p>\r\n\r\n<p style=\"text-align:center; text-indent:25px\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويكرر ذلك حتى يجلس .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان همه أن يسأل كل من وفد إليه عن صحة شيخنا الإمام &nbsp;رضي الله عنه &nbsp;، ويحمله السلام ، ويسميه : ( سراج حلب ) .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/2.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومما قيل في مناقب الشيخ وآثاره</span></span></span></a></p>', 'ar', 9434, 80, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (40, 46, 'وفاته', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نسيم الوصل يؤذن بكشف الحجاب ولقاء الأحباب &nbsp;</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كان كلامه &nbsp;رضي الله عنه &nbsp;مع أهله وأصحابه في الأسابيع الأخيرة من عمره المبارك يحمل معاني الوصايا والتوجيهات والنتبيهات إلى بعض الأمور والقضايا العائلية الخاصة والعامة ولم يكن أسلوبه في الكلام يشعر أحداً بقرب أجله أو غير ذلك بسبب رقته &nbsp;رضي الله عنه &nbsp;ولطفه العجيب</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولم يغفل يوماً عن كلمات الرضا والتسليم وتفويض أمره كله إلى الله تعالى</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكانت وفاته &nbsp;رضي الله عنه &nbsp;عشية الاثنين في العشرين من شهر ذي الحجة سنة /1422/ من الهجرة الشريفة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد حصلت أيام مرضه ووفاته من العجائب والكرامات ما توجب علينا ذكرها ويضيق بنا المجال لاستقصائها على أننا سنأتي على ذكر جملة واسعة حول ذلك في الكتاب الموعود إن شاء الله تعالى</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن ذلك : أن أحد الأطباء الذين كانوا يشرفون على العناية بشيخنا الإمام &nbsp;رضي الله عنه &nbsp;والرعاية الصحية به وقد قدم من بلد آخر لهذا الغرض &ndash; وجزاه الله خير الجزاء &ndash; هذا الطبيب الماهر لفت نظره بيتان من الشعر كتبا على فراش شيخنا الإمام &nbsp;رضي الله عنه &nbsp;من الجهة اليمنى قريباً من رأسه وهما :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولو كانت الدنيا تدوم لأهلها &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; رأيت رسول الله فيها باقيا<br />\r\nولكنها تفنى ويفنى نعيمها &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;ويلقى المؤمن ربه راضيا</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد استحوذ ذلك على إعجاب ودهشة الأطباء والحاضرين إذ لم يتيسر لأحد أن يمد يده لملامسة شيخنا الإمام &nbsp;رضي الله عنه &nbsp;فكيف حصل ذلك ؟ّ!</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وفي هذا نعي لشيخنا الإمام بخط القدرة الإلهية كما أخبر أحد الصالحين من أهل المدينة المنورة أنه رأى النبي &nbsp;صلى الله عليه وسلم &nbsp;في المنام وهو ينعى شيخنا الإمام لأهل البرزخ .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد أخبرنا أيضاً بعض الصالحين أنه كلما توجه إلى الله تعالى داعياً بشفاء شيخنا الإمام &nbsp;رضي الله عنه &nbsp;رأى شيخنا الإمام بين يدي رسول الله &nbsp;صلى الله عليه وسلم &nbsp;قال فكيف أطلب من هو في الأحضان المحمدية يحيا وينعم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا غرو في ذلك فإن لرسول الله &nbsp;صلى الله عليه وسلم &nbsp;عطفاً وحناناً وعناية خاصة بأحبابه المتقين في جميع العوالم وقد قال رسول الله &nbsp;صلى الله عليه وسلم &nbsp;لمعاذ بن جبل &nbsp;رضي الله عنه &nbsp;لما أرسله والياً إلى اليمن قال له وهو يودعه : [ إن أولى الناس بي المتقون من كانوا وحيث كانوا &nbsp;].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا يخفى على كل مؤمن قول الصحابي الجليل سيدنا بلال &nbsp;رضي الله عنه &nbsp;وهو على فراش الموت وقد رأى من أهله الحزن والبكاء فأنكر عليهم وقال :[ غداً ألقى الأحبة محمداً وصحبه ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد رأى سيدنا عثمان بن عفان &nbsp;رضي الله عنه &nbsp;النبي &nbsp;صلى الله عليه وسلم &nbsp;في المنام قبل أن يستشهد &ndash; وكان &nbsp;رضي الله عنه &nbsp;صائماً &ndash; فقال له الرسول &nbsp;صلى الله عليه وسلم &nbsp;:[ إنك ستفطر عندنا ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولله در القائل :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">عليكم وإلا فالبكاء مضيع &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;وفيكم وإلا فالرجاء قطيع<br />\r\nوعنكم وإلا فالأحاديث ضلة &nbsp; &nbsp; &nbsp; ومنكم وإلا فالنوال وضيع</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد عزى رسول الله &nbsp;صلى الله عليه وسلم &nbsp;أمته في مصائبهم بقوله : [ ليعز الناس في مصائبهم المصيبة بي &nbsp;].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ويرحم الله تعالى القائل :</span></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إمام الرسل أكرمهم خصالاً &nbsp; &nbsp; &nbsp; &nbsp;وأقربهم لدى المولى وصالاً<br />\r\nفيا من هام فيه هوى وحالاً &nbsp; &nbsp; &nbsp; &nbsp;محمد رحمة أجرت نوالاً</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">به لمحبه كمل الكمال</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وقد دفن شيخنا الإمام &nbsp;رضي الله عنه &nbsp;في مدفن جامع المدرسة الشعبانية &ndash; وهذا المدفن وقفي - &nbsp;بناء على وصيته ولما لها من منزلة عنده وقد ازداد المكان بهاء وجلالاً وأنواراً بمرقد شيخنا الإمام فيه ويشعر الزائر له بالأنس والسكينة وكأنه في روضة جنانية وهذا هو شأن عباد الله المتقين المخلصين المحبين لله تعالى ورسوله &nbsp;صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإني أسأل الله العظيم رب العرش العظيم بجاه رسوله ذي القدر العظيم &nbsp;صلى الله عليه وسلم &nbsp;أن يرفع مقام شيخنا الإمام في أعلى المقامات وأن يعلي منزلته في أعلى الدرجات وأن يجمعنا معه في الحضرة المحمدية في جملة الأحباب &nbsp;{ مع الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنَ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا ذَلِكَ الْفَضْلُ مِنَ اللَّهِ وَكَفَى بِاللَّهِ عَلِيمًا} آمين وصلى الله وسلم وبارك على سيدنا محمد وعلى آله وصحبه وسلم كلما ذكره الذاكرون وغفل عن ذكره الغافلون &nbsp;{سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ }</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">الحديث في مسند الإمام أحمد [5/235] .&nbsp;<br />\r\nرواه الإمام مالك في الموطأ .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><a class=\"LINK\" href=\"files/book/4.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">نعي الشيخ الامام في الجريدة الرسمية</span></span></span></a></p>', 'ar', 7490, 90, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (41, 55, 'كلمة حول دروس الشيخ', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كانت مجالس دروسه مجالس صفاء ونقاء وسمو وارتقاء ينشرح لها الصدر ويصفو بها القلب وتسمو النفس في مراتبها ويشعر المرء فيها بالتجافي عن دار الغرور والإنابة إلى دار الخلود إذ تنساب إلى قلبه معاني آيات الله تعالى وأحاديث رسول الله &nbsp;صلى الله عليه وسلم &nbsp;بأسلوب سهل العبارة رقيق الكلمة خاصة أنه &nbsp;رضي الله عنه كان يكثر من ضرب الأمثلة التي تبين للسامع ما أراد ولا يلجأ إلى الكلمات العامية المنتشرة على ألسنة الناس إلا إذا أراد أن يبين غموض كلمة أو توضيح جملة دقيقة المعنى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان أسلوبه في الدرس أسلوب الإلقاء فلا يقرأ من كتاب أمامه ويشرح عباراته بل كان قبل أن يذهب إلى الدرس يجمع في صدره ما يريد إلقاءه ثم يأتي به كالوابل الصيب بكثرة الأحاديث النبوية &ndash; التي يأتي بها على وجهها لفظاً وتخريجاً مع ذكر اسم الصحابي الراوي لها عن سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;وكان يحذر من طريقة كثير من المدرسين والخطباء الذين يأتون بالحديث على معناه ويقولون في آخر الدرس أو الخطبة : أو كما قال رسول الله صلى الله عليه وسلم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">بل كان يستهجن هذا العمل &ndash; يكثر الأحاديث النبوية التي تدور في موضوع المحاضرة وقد أحصى بعضهم عدد الأحاديث التي أتى بها في بعض محاضراته فبلغت سبعاً وعشرين حديثاً برواتها ، &nbsp;وكان في درسه يضع أمامه على الطاولة الصغيرة المعروفة &ndash; بالرحلة - &nbsp;يضع كتاب [ صحيح البخاري ] متبركاً به &nbsp; وليكون موضع نظره خلال سكتاته القليلة حين إلقائه المحاضرة وعلى هذا جرى فضيلة مولانا الشيخ محمد نجيب &nbsp;رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام &nbsp;رضي الله عنه : [ كنت في بداية دروسي قد تناولت البحث في قصص الأنبياء عليهم السلام بدءاً من آدم عليه السلام حتى انتهيت في البحث حول بعثة النبي &nbsp;صلى الله عليه وسلم &nbsp;وسيرته وشمائله ووقفت على بابه &nbsp;صلى الله عليه وسلم &nbsp;ولم أحد عنه ، ووفقني الله تعالى إلى البحث حول مواقفه &nbsp;صلى الله عليه وسلم &nbsp;مع العالم وفصلت الكلام على ذلك ولم أنته بعد .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما أبحاثي حول قصص الأنبياء عليهم السلام فكانت مفصلة أعتمد فيها على ما ذكره سبحانه وتعالى في القرآن الكريم &nbsp;حول قصصهم ومناظراتهم لأقوامهم والأدلة والبينات التي أيدهم الله تعالى بها وكثيراً ما كنت أرد أباطيل وأدفع شبهات ذكرت في بعض الكتب تتنافى مع عصمة الأنبياء وجلالة قدرهم عليهم السلام ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال &nbsp;رضي الله عنه : [ لما رأيت في بداية الأمر تزاحم الناس على سماع دروسي سألت الله تعالى أن يبشرني بأن دروسي مقبولة مرضية عند الله تعالى وعند رسوله &nbsp;صلى الله عليه وسلم &nbsp;خاصة أنني كنت لا أبغي من دروسي أجراً ولا منصباً ولا شهرة بل إن غايتي ومقصدي هو رضا الله تعالى ورسوله &nbsp;صلى الله عليه وسلم &nbsp;بتعليم الناس أمور دينهم ونشر وبيان شريعة الله تعالى ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال &nbsp;رضي الله عنه : [ فنمت تلك الليلة فرأيت نفسي إلى جانب بستان كبير تحيطه أشجار خضراء زاهية ، ووقع في نفسي أن رسول الله &nbsp;صلى الله عليه وسلم &nbsp;داخل غرفة في البستان يدرس أصحابه فجعلت أبحث عن باب الدخول فإذا أنا بسيدنا أبي بكر &nbsp;رضي الله عنه يقبل علي ويقول لي :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">هيا بنا نحضر مجلس رسول الله &nbsp;صلى الله عليه وسلم &nbsp;فأخذني ودخلت البستان ولما أردنا الاستئذان على رسول الله &nbsp;صلى الله عليه وسلم &nbsp;سمعناه يقول :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ ادخلا &nbsp;، ادخلا ] فدخل أبو بكر &nbsp;رضي الله عنه فنهض رسول الله &nbsp;صلى الله عليه وسلم &nbsp;من مجلسه ورد عليه السلام ثم تقدمت وسلمت على حضرته الشريفة &nbsp;صلى الله عليه وسلم &nbsp;، وكان أمامه &nbsp;صلى الله عليه وسلم &nbsp;طاولة صغيرة ، تشبه تلك التي توضع أمامي أثناء الدرس ، والبهاء والأنوار مشرقة في وجهه الشريف &nbsp;صلى الله عليه وسلم &nbsp;، حتى إنني لم أتمكن من التحديق في وجهه الشريف &nbsp;صلى الله عليه وسلم &nbsp;...</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فارتميت على أقدامه الشريفة &nbsp;صلى الله عليه وسلم &nbsp;، وجعلت أقبل هذه وهذه ، وأكرر ذلك وأقول في نفسي : هاتان القدمان شرفتا السموات ليلة المعراج &ndash; وغلبني البكاء حتى استيقظت فرحاً مستبشراً مطمئناً ، وقلت في نفسي : إن انكبابي على أقدامه الشريفة &nbsp;صلى الله عليه وسلم &nbsp;دليل الاتباع الصادق إن شاء الله تعالى ، ونسأل الله التوفيق لما يحبه ويرضاه ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولقد كانت محاضراته في جامع بانقوسا تدور حول أبحاث التوحيد والقضايا الإيمانية العلمية الاعتقادية ، وبقي يبحث حول مواقف سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;مع العالم ما يزيد على عشرين سنة &ndash; أي حتى عام /1399/ هـ&nbsp;<br />\r\nولما رجع من المدينة المنورة التي جاور فيها ثلاث سنوات ونصف السنة ، افتتح محاضراته في جامع بانقوسا بالكلام حول &nbsp;تفسير سورة الفاتحة ، على أثر بشارة كان قد رآها أيام مجاورته في المدينة المنورة ، وبقي واستمر يبحث حول تفسير سورة الفاتحة ما يزيد على سنتين ، ثم شرع في تدريسه حول تفسير خواتيم سورة البقرة ، وخواتيم سورة آل عمران ، إلى أن توقف عن التدريس في جامع بانقوسا بسبب اعتلال صحته ، ووهن جسمه ، واقتصر على التدريس في الجامع الكبير المعروف بجامع سيدنا زكريا عليه السلام .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">واستمر في التدريس فيه حتى عام /1410/ هـ ، وكانت أبحاثه فيه تدور حول قضايا الإيمان العملية ، ويفتتح الدرس &ndash; في هذا الجامع من حين ابتدائه التدريس به &ndash; بقول سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;:</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ بني الإسلام على خمس شهادة أن لا إله إلا الله وأن محمدا رسول الله وإقام الصلاة وإيتاء الزكاة والحج وصوم رمضان &nbsp;] &nbsp;<br />\r\nوكان يرويه بإسناد الإمام البخاري رحمه الله تعالى ، فيقول : أما بعد : فبالسند المتصل إلى الإمام أبي عبد الله ، محمد ابن إسماعيل بن إبراهيم بن المغيرة بن بردزبه الجعفي البخاري رضي الله عنه ، قال : حدثنا ...</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقال شيخنا الإمام &nbsp;رضي الله عنه : [ ولقد لمست في الناس في السنوات الأخيرة جهلاً شديداً في أمور دينهم حتى صارت القضايا الفطرية السليمة تحتاج إلى دليل وبيان وسبب ذلك قلة مجالس العلم والتفات الناس إلى أمور الدنيا وزينتها كل ذلك جعلني أقتصر في دروسي على بيان أمور الدين الضرورية التي لابد للمؤمن من معرفتها والإحاطة بها اعتقاداً وعملاً وتخلقاً وأدباً وتناولت ذلك بأسلوب سهل وكلمات مألوفة لأن قصدي انتفاع الناس بما يسمعون ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ثم لزم البيت واعتزل فيه لأمر يريده الله تعالى وعكف على &nbsp;جمع وتصنيف الكتب العلمية الدينية وفيها ما يحتاجه الناس لفهم أمور دينهم .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان شيخنا الإمام &nbsp;رضي الله عنه &nbsp;يجلس في الدرس كهيئة جلوسه في الصلاة وذلك في مقدمة السدة المعروفة في كل من جامع بانقوسا والجامع الكبير ويجلس متوجهاً إلى القبلة وأمامه رحلة صغيرة كتلك التي يوضع عليها المصحف أثناء التلاوة في المسجد .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان إذا شرع في الدرس استغرق فيه وارتفع صوته واحمر وجهه ولا يشعر بمرور الوقت فلا يتعب ولا يسأم لكنه يراعي أحوال الحاضرين في الدرس وكان قد كلف بعض أصحابه أن يمر أمام المحراب إذا مضى من الوقت خمسون دقيقة فإذا وقع بصره عليه راح يشرع في ختم الدرس وكثيراً ما كانت تتجاوز فترة الدرس الساعة وربع الساعة ولا أحد من الحاضرين يمل أو يكل بل يراهم الناظر مصغين خاشعين متوجهين بقلوبهم إلى كلام الشيخ &nbsp;رضي الله عنه وبأبصارهم إلى وجهه المنير &nbsp;رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام &nbsp;رضي الله عنه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">&nbsp;[ وكنت قد رأيت سيدنا زكريا عليه السلام في المنام فقال لي : إنك إذا جلست إلى الدرس &nbsp;جعلت أنظر إليك حتى تنتهي من درسك ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قال شيخنا الإمام &nbsp;رضي الله عنه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ وهذه من البشائر المتوالية علي بفضل الله تعالى وأننا محفوفون بأنظار سيدنا زكريا عليه السلام كما أن أنظار خير البرية وإمام الأنبياء والمرسلين سيدنا محمد &nbsp;صلى الله عليه وسلم &nbsp;لا تنقطع عنا كما أتتني البشارة بذلك في عدة مناسبات وعلى لسان من لقينا من أهل الله تعالى ومنهم السيد الكبير العارف بالله تعالى الشيخ أحمد الحارون الدمشقي وغيره رضي الله عنهم أجمعين ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وأما دروسه في جامع الحموي فكانت مجالس تفسير وحديث ، وقد اقتصرت على أيام الأحد والأربعاء والخميس بعد شروق الشمس بنصف ساعة تقريباً .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فيقرأ صباح الأحد درس تفسير لكلام الله تعالى ، أما صباح الأربعاء فيقرأ من صحيح الإمام البخاري &nbsp;رضي الله عنه ما تيسر له من أحاديث على حسب الأبواب ، ثم يشرع في بيانها ، وكذلك صباح الخميس فيقرأ عدة أحاديث من كتاب رياض الصالحين للإمام النووي &nbsp;رضي الله عنه ، ثم يتناول البحث في معانيها ومقاصدها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قلت : وكان يحضر مجالس تدريسه عدد من مشاهير العلماء آنذاك ، فضلاً عن طلاب العلم ، وصلحاء الناس على اختلاف مراتبهم ، وذلك لأن دروسه وأبحاثه فيها تميزت بأنها عامة وليست لعوام الناس فقط ، وكان كل من الحاضرين ينهل من هذا المعين الفياض على حسب طاقته وفهمه وعلمه</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">حضر درسه يوماً العلامة المحدث الشيخ عبد القادر السقاف الحضرمي أمتع الله به ، وكان قد قدم من بلاد الحجاز لزيارة شيخنا الإمام صيف سنة /1396/ هـ فكان من كلامه لأصحابه لما فرغ شيخنا الإمام من درسه :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ لقد سمعت من هذا السيد العارف بالله تعالى كلاماً لم أسمعه من أحد قبله ، ولم أقرأه في كتاب ] اهـ &nbsp;<br />\r\nإنه فتح من الله تعالى ، وفيض منه سبحانه على هذا الشيخ الإمام ، خاصة أنه يأتي بالمعاني العرفانية العالية ، ويدلل عليها ، ويؤيد &nbsp;كلامه بآيات من كلام الله تعالى ، وأحاديث من كلام سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;.<br />\r\nولا يعرف قدر هذا إلا من كان من أهل العلم والمعرفة والصفاء والتقى ..<br />\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;<br />\r\n&nbsp;مجالس تذكير ونصح</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">لما اعتزل شيخنا الإمام &nbsp;رضي الله عنه في بيته في السنوات الأخيرة من عمره المبارك لم يعد يستقبل إلا بعض أهل العلم والأحباب والأصحاب ، ومن وفد عليه من خارج مدينة حلب للتبرك به ، والسماع لموعظته ، أو استجازته في الحديث الشريف وأوراد الطريق وغيرذلك .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا يتيسر لأحد من هؤلاء لقاؤه إلا من كان ذا حظ وافر ، لما سيناله من دعوات وبركات ، ونظرات من شيخنا الإمام &nbsp;رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ولا يطول حديثه &nbsp;رضي الله عنه في المجلس عن نصف ساعة تقريباً ، ثم يختم بالدعاء وقراءة الفاتحة ، ويتقدم الحاضرون للسلام عليه ، وربما شكا إليه أحدهم أمراً أهمه ، أو استفتاه في حكم شرعي ، أو استفهمه عن مسألة علمية ، فيجيب &nbsp;رضي الله عنه كل سائل عن مسألته ، ويجد عند شيخنا الإمام &nbsp;رضي الله عنه ما يطمئن به قلبه ، وتسكن إليه نفسه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان جل كلامه &nbsp;رضي الله عنه يدور حول وجوب التمسك بكتاب الله تعالى وسنة رسوله &nbsp;صلى الله عليه وسلم &nbsp;، وما كان عليه الصحابة رضي الله عنهم وسلف هذه الأمة ، ثم يذكر الحاضرين بالأخلاق الفاضلة التي جاء بها رسول الله &nbsp;صلى الله عليه وسلم &nbsp;والآداب والمحاسن والكمالات التي ندب إليها رسول الله &nbsp;صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكثيراً ما كان يحرض الناس على المواظبة على قراءة القرآن الكريم ، ويذكر لهم بعض الأحاديث الواردة في ذلك .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">ومن عادته &nbsp;رضي الله عنه أن يكرم أهل الشيبة في الإسلام ، عملاً بما جاء عن سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;ويجلسهم إلى جانبه أو أمامه ، ويكرمهم ويجعلهم موضع نظره ، ويذكر قول الرسول &nbsp;صلى الله عليه وسلم &nbsp;:[ من شاب شيبة في الإسلام كانت له نوراً يوم القيامة ] &nbsp;ويقول :[ من كثر شيبه في الإسلام أضاء له ولغيره ] ويقول لهم : [ كيف حالكم يا شباب ؟ كلنا شباب في طاعة الله تعالى ] ولا يترك في مجلس من مجالسه أن يذكر الحاضرين بكثرة الصلاة والسلام على خير الأنام سيدنا محمد &nbsp;صلى الله عليه وسلم &nbsp;بأي صيغة كانت ، ويقول :[ من كان يريد أن يكون بينه وبين رسول الله &nbsp;صلى الله عليه وسلم &nbsp;صلة فليكثر من الصلاة والسلام عليه &nbsp;صلى الله عليه وسلم &nbsp;، لأن الرسول &nbsp;صلى الله عليه وسلم &nbsp;قال :[ من صلى علي بلغتني صلاته وصليت عليه ] &nbsp; ، فأنت تصلي على رسول الله &nbsp;صلى الله عليه وسلم &nbsp;وهو يصلي عليك ، وكفاك بهذا شرفاً وفضلاً وفوزاً وقرباً من حضرته &nbsp;صلى الله عليه وسلم &nbsp;]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كما كان يذكر الحاضرين بالاشتغال بالدعاء والإكثار منه ، وأن لا يقتصر أحدهم على الدعاء لنفسه فقط ، بل يدعو لنفسه وأهله وأحبابه والمسلمين أجمعين في مشارق الأرض ومغاربها .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يختم المجلس بالدعاء ومن جملته : [ اللهم صل على سيدنا محمد صلاة ترضيك وترضيه وترضى بها عنا يا رب العالمين ، لأنك يا مولانا قلت وقولك الحق :{ والله ورسوله أحق أن يرضوه إن كانوا مؤمنين}فنسألك اللهم رضاك ورضا رسولك &nbsp;صلى الله عليه وسلم &nbsp;رضاً لا سخط بعده .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">اللهم &nbsp;صلاة تفيض بها علينا من أسرار رسول الله &nbsp; صلى الله عليه وسلم &nbsp;ومن أنواره ونفحاته وبركاته ، صلاة تعطف &nbsp;بها علينا قلبه الشريف ، اللهم واجمع بيننا وبينه كما جمعت بين الروح والنفس ظاهراً وباطناً ، يقظة ومناماً ، واجعله يا ربنا يا ربنا يا ربنا روحاً لذاتنا من جميع الوجوه في الدنيا قبل الآخرة يا عظيم ].</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وإذا أطال في الدعاء كان يستمر فيه بقوله :[ يا عظيماً &nbsp;يرجى لكل عظيم ، قد سألناك وتوسلنا إليك بسيدنا محمد &nbsp;صلى الله عليه وسلم &nbsp;ذي الخلق العظيم ، أن تفرج عنا الكرب العظيم ، وأن تحقق رجانا يا مولانا ، وتتولانا في جميع قضايانا بما توليت به عبادك الصالحين بقولك :{ وهو يتولى الصالحين }، يا من لا يرد سائله ولا يخيب آمله .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">إلهي : يا خير من مدت إليه الأيادي ، سألناك بخير من مد يديه إليك &nbsp;صلى الله عليه وسلم &nbsp;فأعطنا منانا ، وحقق رجانا ، وقد بلغنا عن سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;أنه قال :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[إن ربكم حيي كريم يستحي أن يبسط العبد يديه إليه فيردهما صفراً خائبتين &nbsp;] ، وها نحن قد رفعنا إليك أكفنا ، سائلين متوسلين بسيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;أن تستجيب دعانا ، فإنك قلت وقولك الحق ، ووعدت ووعدك الصدق :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{ وقال ربكم ادعوني أستجب لكم }فقد دعوناك كما أمرتنا فاستجب لنا كما وعدتنا إنك لا تخلف الميعاد .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وصل اللهم وسلم على سيدنا محمد وعلى أزواجه ، وأصحابه ، وآل بيته ، وعلينا معهم أجمعين وعلى والدينا ومشايخنا ومن له حق علينا وعلى جميع المؤمنين والمؤمنات والمسلمين والمسلمات الأحياء منهم والأموات في كل لمحة ونفس عدد ما وسعه علم الله العظيم . آمين</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">{سُبْحَانَ رَبِّكَ رَبِّ الْعِزَّةِ عَمَّا يَصِفُونَ وَسَلَامٌ عَلَى الْمُرْسَلِينَ وَالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ } والخاتمة إلى رسول الله &nbsp;صلى الله عليه وسلم &nbsp;ويقرأ الحاضرون الفاتحة ثم يمسح وجهه بيديه المباركتين ، ويلتفت إلى الحاضرين ليؤانسهم بكلمات البشر والرجاء ، ثم يتقدمون للسلام عليه ووداعه ، وكلهم رجاء وشوق إلى لقاء آخر معه &nbsp;رضي الله عنه .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify\"><br />\r\n<span style=\"font-family:Lotus\">----------------------------------------------------------------<br />\r\n<span style=\"font-size:18px\">1رواه البخاري ومسلم وغيرهما عن غير واحد من الصحابة رضوان الله عليهم .<br />\r\n2 عزاه في ( مجمع الزوائد ) (5/158 ) إلى البزار والطبراني عن سيدنا فضالة بن عبيد &nbsp;رضي الله عنه &nbsp;.<br />\r\n3عزاه في ( مجمع الزوائد ) (10/162 ) إلى الطبراني عن سيدنا أنس &nbsp;رضي الله عنه &nbsp;.<br />\r\n4 رواه أبو داوود في ( السنن ) ، كتاب الصلاة ، باب الدعاء /1488/ (2/165 ) ، والترمذي في الدعوات ، باب /118/ حديث /3551/ ( 9/205 ) .</span></span></p>', 'ar', 6439, 10, '2019-05-13', 1);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (42, 21, 'كلمة حول كتب الشيخ', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">&nbsp;لقد تنوعت مؤلفاته ، في مختلف قضايا الإيمان الاعتقادية والعملية والقولية والخلقية والأدبية ، وقد تصدر هذه المؤلفات كتابه الشهير :[ سيدنا محمد رسول الله &nbsp;صلى الله عليه وسلم &nbsp;شمائله الحميدة وخصاله المجيدة] الذي كان شيخنا الإمام &nbsp;رضي الله عنه &nbsp; يفخر به ، ويحتسبه من أعظم الذخائر عند الله تعالى ، وعند رسوله &nbsp;صلى الله عليه وسلم &nbsp;ويقول :</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">[ يجب على كل مؤمن أن يقرأ هذا الكتاب ، لأني ذكرت فيه ما لابد منه لكل مؤمن أن يعرفه عن خصال وأخلاق سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد نال هذا الكتاب العظيم انتشاراً واسعاً في شتى البلاد ، وأقبل المسلمون على قراءته رغبة في التعرف والاطلاع على بعض شمائل سيدنا محمد &nbsp;صلى الله عليه وسلم &nbsp;، وخصاله المجيدة &nbsp;صلى الله عليه وسلم &nbsp;، وقد تطرق شيخنا الإمام &nbsp;رضي الله عنه &nbsp;في هذا الكتاب إلى دفع شبهات بأدلة قاطعة حول عصمة سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;من الخطأ والخطيئة ، ولما فرغ من جمع هذا الكتاب المبارك ، حظي بإكرام كبير من سيدنا رسول الله &nbsp;صلى الله عليه وسلم &nbsp;، إذ رآه في المنام وقد وظفه خادماً ملازماً له &nbsp;صلى الله عليه وسلم &nbsp;، وسأبين ذلك في الكتاب الموسع حول شيخنا الإمام إن شاء الله تعالى .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد توالت مؤلفاته &nbsp;رضي الله عنه &nbsp;، وانتشرت بين المسلمين في شتى بقاع الأرض ، حتى إن بعضها ترجم إلى لغات أجنبية ، لأهمية أبحاثها ومكانتها العلمية .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان كلما فرغ من جمع كتاب جاءته البشائر والمكرمات من الله تعالى ، ونال من العطايا والنفحات المحمدية المتواصلة &nbsp;ما يجعله يترقى في مقامات القرب والمحبة .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وقد تميزت مؤلفاته بسهولة العبارة ورقة الكلمة ، بحيث يتيح للقارئ مهما كانت درجة فهمه وعلمه أن يعي ما يقرأ .</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان يقول : [ غايتي وقصدي أن ينتفع الناس بها على مختلف طبقاتهم ، ولو تكلفت صياغة العبارة وانتقاء الكلمة ، لكان الفهم والنفع مقتصراً على أهل العلم فقط ]</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">كما تميزت كتبه بكثرة سرد الآيات القرآنية والأحاديث النبوية ، حتى يقرأ الناس آيات الله تعالى ويفهموا معانيها ببيانات رسول الله &nbsp;صلى الله عليه وسلم &nbsp;.</span></span></span></p>\r\n\r\n<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">وكان &nbsp;رضي الله عنه &nbsp;يقول :[ إني دوماً أسأل الله تعالى أن يجعل في كتبي نوراً محمدياً &nbsp; صلى الله عليه وسلم &nbsp;يجده القارئ لها في قلبه ، فيزداد إيماناً وهدى وصلاحاً ، وقرباً من الله تعالى ورسوله &nbsp;صلى الله عليه وسلم &nbsp;]&nbsp;</span></span></span></p>', 'ar', 7387, 10, '2019-05-13', 0);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (43, 21, 'قبسات من المؤلفات - تم الايقاف مؤقتا', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">هذه الأبحاث مسائل علمية للشيخ الإمام فيها تحقيق متميز مؤيد بالكتاب والسنة اخترناها لك من كتب الشيخ الإمام رضي الله عنه :</span></span></span></p>\r\n\r\n<ul style=\"margin-right:80px\">\r\n	<li style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/5.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">جواب أهل العلم والرشاد حول ذكر بعض أحاديث فيها ضعف</span></span></span></a></li>\r\n	<li style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/6.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">حفظ الله تعالى رسوله صلى الله عليه وسلم من الخطأ والباطل</span></span></span></a></li>\r\n	<li style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/7.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">رفع ملام ودفع أوهام حول ذكر الشيخ الإمام بعض المنامات</span></span></span></a></li>\r\n	<li style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/8.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">قصة الملكين هاروت وماروت وهل إبليس أول الجن</span></span></span></a></li>\r\n	<li style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/9.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">من قرأ سورة الإخلاص مائة ألف مرة فهو عتيق الله تعالى</span></span></span></a></li>\r\n</ul>', 'ar', 1712, 20, '2019-05-13', 0);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (44, 21, 'تحميل فهارس المؤلفات', '<p style=\"text-align:justify\"><a class=\"LINK\" href=\"files/index_all.zip\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">الفهرس العام والكامل لجميع مؤلفات الشيخ الإمام</span></span></span></a></p>\r\n\r\n<p style=\"text-align:justify\"><a class=\"LINK\" href=\"files/index.zip\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">فهرس جميع مؤلفات الشيخ الإمام كل مؤلف على حدة</span></span></span></a></p>', 'ar', 8426, 30, '2019-05-13', 0);
INSERT INTO `st_pages` (`pages_id`, `pages_menus`, `pages_title`, `pages_content`, `pages_lan`, `pages_visitor`, `pages_priority`, `pages_date`, `pages_active`) VALUES (45, 21, 'قبسات من المؤلفات', '<p style=\"text-align:justify; text-indent:25px\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">هذه الأبحاث مسائل علمية للشيخ الإمام فيها تحقيق متميز مؤيد بالكتاب والسنة اخترناها لك من كتب الشيخ الإمام رضي الله عنه :</span></span></span></p>\r\n\r\n<ul style=\"margin-right:80px\">\r\n	<li style=\"text-align:justify\"><a class=\"LINK\" href=\"files/book/61.pdf\" target=\"_blank\"><span style=\"line-height:30px\"><span style=\"font-size:24px\"><span style=\"font-family:Lotus\">حُكْمُ أَبَوَيْ سيِّدنا محمد ﷺ الشَّريفَين</span></span></span></a></li>\r\n</ul>', 'ar', 600, 20, '2020-09-10', 0);
COMMIT;

