INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (78, 30, '16 - حول قوله تعالى : إن الذين يغضون أصواتهم عند رسول الله أولئك الذين امتحن الله قلوبهم للتقوى', NULL, 'حول قوله تعالى : إن الذين يغضون أصواتهم عند رسول الله أولئك الذين امتحن الله قلوبهم للتقوى لهم مغفرة وأجر عظيم', '<p align=\\\"justify\\\"><font size=\\\"5\\\">حول قوله تعالى : إن الذين يغضون أصواتهم عند رسول الله أولئك الذين امتحن الله قلوبهم للتقوى لهم مغفرة وأجر عظيم </font></p>', 'default.jpg', 1, 5390, 0, 0, 0, 0, 1, '2010-05-06 23:48:54', 0, 0, 0, NULL, NULL, NULL, '23.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (79, 30, '17 - حول قوله تعالى : لهم مغفرة وأجر عظيم', NULL, 'حول قوله تعالى : لهم مغفرة وأجر عظيم', '', 'default.jpg', 1, 8287, 0, 0, 0, 0, 1, '2010-05-06 23:48:55', 0, 0, 0, NULL, NULL, NULL, '24.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (80, 36, 'مولد البزنجي', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\">سجل هذا المولد عام 1406 هـ&nbsp; <br /><br />وكان من عادة الشيخ الإمام رضي الله عنه في شهر ربيع الأنوار أن يقرأ قصة مولد سيدنا رسول الله صلى الله عليه وسلم التي نظمها السيد جعفر البرزنجي , يقرؤها في الجامع الكبير وجامع بانقوسا وجامع الحموي&nbsp; ، وانظر كلام الشيخ الإمام حول مشروعية المولد في كتابه :سيدنا محمد رسول الله شمائله الحميدة &ndash; خصاله المجيدة </font></p>', 'default.jpg', 1, 14878, 0, 0, 0, 0, 1, '2010-05-06 23:49:09', 0, 0, 0, NULL, NULL, NULL, '25.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (82, 37, 'تسجيل نادر لصلاة الشيخ الإمام التراويح في المدرسة الشعبانبة', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"4\\\" face=\\\"Arial\\\">الطرف الأخير من صلاة التراويح . في الساحة الخارجية&nbsp; للمدرسة الشعبانية وقد سجلت&nbsp; في 28 رمضان سنة 1397 هـ&nbsp; حيث كان الزمن صيفاً حاراً ويلاحظ أن الشيخ رضي الله عنه قد تجوز في صلاته قليلاً مراعاة لامتلاء المكان بالمصلين وضيقه بهم وشدة الحر وقصر الليل .</font></p>', 'default.jpg', 1, 7422, 0, 0, 0, 0, 1, '2010-08-26 12:40:09', 0, 0, 0, NULL, NULL, NULL, 'taraweh_01.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (83, 38, 'ما تيسر من سورة الحجرات و ق والطارق والغاشية والإخلاص', NULL, '', '<font size=\\\"4\\\" face=\\\"Arial\\\">تلاوة نادرة للشيخ مصطفى إسماعيل لما تيسر من سورة الحجرات وسورة ق والطارق والغاشية والإخلاص ثم الأذان بصوته رحمه الله </font>', 'default.jpg', 1, 5530, 0, 0, 0, 0, 1, '2010-08-26 12:43:38', 0, 0, 0, NULL, NULL, NULL, 'kaaf.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (84, 38, 'تلاوة نادرة للشيخ مصطفى إسماعيل لسورة الإسراء', NULL, '', '', 'default.jpg', 1, 6774, 0, 0, 0, 0, 1, '2010-08-26 14:05:40', 0, 0, 0, NULL, NULL, NULL, 'al_esraa.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (85, 39, 'بيان ما ينبغي أن يكون موقف المؤمن تجاه هدي النبي صلى الله عليه وسلم له', NULL, '', '<p style=\\\"MARGIN: 0cm 0cm 10pt\\\" dir=\\\"rtl\\\" class=\\\"MsoNormal\\\"><span style=\\\"LINE-HEIGHT: 115%; FONT-FAMILY: &quot;Times New Roman&quot;, &quot;serif&quot;; FONT-SIZE: 18pt; mso-ascii-theme-font: major-bidi; mso-hansi-theme-font: major-bidi; mso-bidi-theme-font: major-bidi\\\" lang=\\\"AR-SA\\\">من مواقفه صلى الله عليه وسلم مع العالم ما جاء في<span style=\\\"mso-spacerun: yes\\\">&nbsp; </span>قوله تعالى { وإنك لتهدي إلى صراط مستقيم } <o:p></o:p></span></p>\r\n<p style=\\\"MARGIN: 0cm 0cm 10pt\\\" dir=\\\"rtl\\\" class=\\\"MsoNormal\\\"><span style=\\\"LINE-HEIGHT: 115%; FONT-FAMILY: &quot;Times New Roman&quot;, &quot;serif&quot;; FONT-SIZE: 18pt; mso-ascii-theme-font: major-bidi; mso-hansi-theme-font: major-bidi; mso-bidi-theme-font: major-bidi\\\" lang=\\\"AR-SA\\\">وبيان ما ينبغي أن يكون موقف المؤمن تجاه هدي النبي صلى الله عليه وسلم له <o:p></o:p></span></p>', 'default.jpg', 1, 4226, 0, 0, 0, 0, 1, '2011-09-24 23:26:54', 0, 0, 0, NULL, NULL, NULL, '27.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (86, 39, 'بيان أنواع الهدي من الله تعالى', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">حول قوله تعالى { وإنك لتهدي إلى صراط مستقيم } وفيه بيان أنواع الهدي من الله تعالى :الهدي العام وهدي البيان وهدي التوفيق ثم الحديث عن مراتب الهداية بالتفصيل</font></p>', 'default.jpg', 1, 3284, 0, 0, 0, 0, 1, '2011-09-24 23:26:56', 0, 0, 0, NULL, NULL, NULL, '28.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (87, 39, 'بيان  طريقته صلى الله عليه وسلم في هداية الناس', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">حول قوله تعالى { إنا هديناه السبيل إما شاكراً وإما كفوراً&nbsp; } وإلى ماذا هدانا سيدنا رسول الله صلى الله عليه وسلم وبيان&nbsp; طريقته صلى الله عليه وسلم في هداية الناس ثم فضل مجالس العلم , وأن الخير والهدي كله في : قال الله تعالى , قال رسول الله صلى الله عليه وسلم&nbsp; . </font></p>', 'default.jpg', 1, 3527, 0, 0, 0, 0, 1, '2011-09-24 23:26:58', 0, 0, 0, NULL, NULL, NULL, '29.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (88, 39, 'بيان أن توفيق الله تعالى وهدايته العبد إلى لإيمان هو أعظم النعم على هذا العبد', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">بيان أن توفيق الله تعالى وهدايته العبد إلى لإيمان هو أعظم النعم على هذا العبد فينبغي عليه شكر الله تعالى ليزيده هداية كما قال سبحانه : { لئن شكرتم لأزيدنكم } <br /></font></p>', 'default.jpg', 1, 3343, 0, 0, 0, 0, 1, '2011-09-24 23:27:02', 0, 0, 0, NULL, NULL, NULL, '30.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (89, 39, 'بيان أن من آثار نعمة الله على العبد بالهداية', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">تتمة الدرس السابق وفيه بيان أن من آثار نعمة الله على العبد بالهداية من آثار ذلك أن الله يجعل له وداً كما في قوله تعالى : { إن الذين آمنوا وعملوا الصالحات سيجعل لهم الرحمن وداً } وأن الله تعالى&nbsp; يثني عليه في الملأ الأعلى ويشرفه بجواره في الجنة&nbsp; والتجلي عليه بالرؤيا </font></p>', 'default.jpg', 1, 3882, 0, 0, 0, 0, 1, '2011-09-24 23:27:06', 0, 0, 0, NULL, NULL, NULL, '31.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (90, 39, 'بيان أن على الإنسان أن يسأل الله الزيادة من الهداية', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">بيان أن على الإنسان أن يسأل الله الزيادة من الهداية كما علمنا الله تعالى أن نقول : { اهدنا الصراط المستقيم } أي زدنا هداية وثبت إيماننا , وأن الإنسان إما في زيادة هدي وإيمان وإما في نقصان وفيه الكلام عن عرش الله تعالى وحملته عليهم السلام والكلام عن قول الله تعالى : { إليه يصعد الكلم الطيب والعمل الصالح يرفعه }</font></p>', 'default.jpg', 1, 3418, 0, 0, 0, 0, 1, '2011-09-24 23:27:05', 0, 0, 0, NULL, NULL, NULL, '32.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (91, 39, 'الكلام حول قوله تعالى  إليه يصعد الكلم الطيب والعمل الصالح يرفعه', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">الكلام حول قوله تعالى : { إليه يصعد الكلم الطيب والعمل الصالح يرفعه } وعن عرض الأعمال على الأقارب في عالم البرزخ ثم الحديث عن معية سيدنا رسول الله صلى الله عليه وسلم وذكر حديث سيدنا ربيعة بن كعب الأسلمي خادم سيدنا رسول الله صلى الله عليه وسلم</font></p>', 'default.jpg', 1, 3489, 0, 0, 0, 0, 1, '2011-09-24 23:27:05', 0, 0, 0, NULL, NULL, NULL, '33.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (92, 39, 'الكلام حول قوله  تعالى وإن من شيء إلا يسبح بحمده', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">الكلام حول قوله&nbsp; تعالى { وإن من شيء إلا يسبح بحمده }&nbsp; والحديث عن تسبيح الماء والطعام بحضرة سيدنا رسول الله صلى الله عليه وسلم وإطلاع الله بعض أوليائه على ذلك والتحذير من إنكار هذا ثم الكلام عن قوله تعالى :{ يوم تشهد عليهم ألسنتهم وأيديهم وأرجلهم بما كانوا يعملون } والكلام عن نطق الطيور وتسليم الحجر والشجر والمدر على سيدنا رسول الله صلى الله عليه وسلم وأن هذا ثابت لا ريب&nbsp; فيه </font></p>', 'default.jpg', 1, 3479, 0, 0, 0, 0, 1, '2011-09-24 23:27:09', 0, 0, 0, NULL, NULL, NULL, '34.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (93, 39, 'بيان عظيم نعمة الله على عبده بالإيمان', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">بيان عظيم نعمة الله على عبده بالإيمان وأن الله تعالى امتن على عباده بذلك فقال جل وعلا :&nbsp; { قل لا تمنوا علي إسلامكم بل الله يمن عليكم أن هداكم للإيمان إن كنتم صادقين } <br />وأن من آثار نعمة الله تعالى عليك بالإيمان أن يكرمك بجواره في الجنة وزيارته&nbsp; ثم الكلام عن قوله تعالى في الحديث القدسي لسيدنا محمد صلى الله عليه وسلم : { لا اذكر إلا ذكرت معي } وذكر الله تعالى لعبده إن هو ذكره قال تعالى { فاذكروني أذكركم }<br /></font></p>', 'default.jpg', 1, 3384, 0, 0, 0, 0, 1, '2011-09-24 23:40:03', 0, 0, 0, NULL, NULL, NULL, '35.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (94, 39, 'بيان عظيم نعمة الله على عبده أن وفقه للإيمان وجعل قلبه مشكاة لنوره', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">بيان عظيم نعمة الله على عبده أن وفقه للإيمان وجعل قلبه مشكاة لنوره كما قال تعالى : { مثل نوره كمشكاة فيها مصباح } وبيان طريق التقرب إلى الله تعالى وأن أقرب ما يكون العبد من ربه وهو ساجد </font></p>', 'default.jpg', 1, 3487, 0, 0, 0, 0, 1, '2011-09-24 23:40:03', 0, 0, 0, NULL, NULL, NULL, '36.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (95, 39, 'أنواع القربات التي يتقرب بها المؤمن إلى حضرة الله تبارك وتعالى', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">تتمة الكلام عن أنواع القربات التي يتقرب بها المؤمن إلى حضرة الله تبارك وتعالى وأن منها القولية التي أعلاها وأعظمها تلاوة القرآن الكريم ومنها العملية وأعظمها قيام الليل شعار الصالحين&nbsp; </font></p>', 'default.jpg', 1, 5454, 0, 0, 0, 0, 1, '2011-09-24 23:40:03', 0, 0, 0, NULL, NULL, NULL, '37.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (96, 39, 'الإسراء والمعراج 1', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">بيان أن البحث في الإسراء والمعراج فيه أمور عرفانية وعلمية تعود على الأمة بالخير وأن الإسراء كان بقدرة الله تعالى ثم الدليل على أن الإسراء كان بجسد سيدنا محمد صلى الله عليه وسلم وروحه , والحديث عن أمور ثانية تتعلق بالإسراء والمعراج </font></p>', 'default.jpg', 1, 3822, 0, 0, 0, 0, 1, '2011-09-24 23:40:05', 0, 0, 0, NULL, NULL, NULL, '38.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (97, 39, 'الإسراء والمعراج 2', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">تتمة الكلام و ذكر واقعة المعراج ولقائه صلى الله عليه وسلم مع الأنبياء الكرام عليهم السلام وذكر سلام سيدنا إبراهيم عليه الصلاة والسلام على الأمة المحمدية وأنه ينبغي على كل مؤمن رد هذا السلام&nbsp; ثم الكلام عن البيت المعمور وسدرة المنتهى وعن رؤية الملائكة حضرة سيدنا رسول الله صلى الله عليه وسلم </font></p>', 'default.jpg', 1, 3539, 0, 0, 0, 0, 1, '2011-09-24 23:40:06', 0, 0, 0, NULL, NULL, NULL, '39.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (98, 39, 'الإسراء والمعراج 3', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">البحث حول رؤية سيدنا محمد صلى الله عليه وسلم لرب العزة جل وعلا وإثبات ذلك بالأدلة القاطعة من الكتاب والسنة والحديث عن سدرة المنتهى والملائكة الكرام عليهم السلام </font></p>', 'default.jpg', 1, 3360, 0, 0, 0, 0, 1, '2011-09-24 23:40:06', 0, 0, 0, NULL, NULL, NULL, '40.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (99, 39, 'الإسراء والمعراج 4', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">الحديث عن سيدنا جبريل عليه السلام وعن قوته التي أعطاه الله إياها ورؤية سيدنا محمد صلى اله عليه وسلم له بالحقيقة الجبريلية وأن ذلك من آيات الله الكبرى </font></p>', 'default.jpg', 1, 3631, 0, 0, 0, 0, 1, '2011-09-24 23:51:59', 0, 0, 0, NULL, NULL, NULL, '41.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (100, 39, 'درس الهجرة 1', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">ذكر إجماع الصحابة رضي الله عنهم أن&nbsp; تكون الهجرة مبدأ التاريخ الإسلامي والكلام عن هجرة النبي صلى الله عليه وسلم حتى الوصول إلى غار ثور </font></p>', 'default.jpg', 1, 3934, 0, 0, 0, 0, 1, '2011-09-24 23:51:59', 0, 0, 0, NULL, NULL, NULL, '44.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (101, 39, 'درس الهجرة 2', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">تتمة الكلام عن الهجرة الشريفة وذكر حديث أم معبد الذي وصفت فيه سيدنا رسول الله صلى الله عليه وسلم وأن الواجب على المؤمن أن يتوجه بقلبه إلى سيدنا رسول الله صلى الله عليه وسلم&nbsp; ليستنير بأنواره</font></p>', 'default.jpg', 1, 3869, 0, 0, 0, 0, 1, '2011-09-24 23:52:00', 0, 0, 0, NULL, NULL, NULL, '45.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (102, 39, 'درس الهجرة 3', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">الكلام عن هجرة بعض الصحابيات رضي الله عنهن إلى المدينة المنورة ثم بيان فضل المهاجرين والأنصار رضي الله عنهم أجمعين </font></p>', 'default.jpg', 1, 3841, 0, 0, 0, 0, 1, '2011-09-24 23:52:01', 0, 0, 0, NULL, NULL, NULL, '46.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (103, 39, 'درس الهجرة 4', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">الكلام حول خطر الغل والحقد ثم الحديث عن حوض النبي صلى الله عليه وسلم وعن قوله صلى الله عليه وسلم : ( إني أرى ما لا ترون وأسمع ما لا تسمعون&nbsp; ) </font></p>', 'default.jpg', 1, 4772, 0, 0, 0, 0, 1, '2011-09-24 23:52:02', 0, 0, 0, NULL, NULL, NULL, '47.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (104, 39, 'درس الهجرة 5', NULL, '', '<font size=\\\"5\\\" face=\\\"Arial\\\">الكلام حول حديث : ( إنما الأعمال بالنيات ) والتنبيه إلى بعض حكم الهجرة وأسرارها </font>', 'default.jpg', 1, 4604, 0, 0, 0, 0, 1, '2011-09-24 23:52:06', 0, 0, 0, NULL, NULL, NULL, '48.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (105, 39, 'درس الهجرة 6', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">الحديث عن دخول سيدنا محمد صلى الله عليه وسلم المدينة المنورة وعن الإيماءات النبوية والأسرار العالية في جلوس الناقة موضع المسجد النبوي الشريف وموضع دار أبي أيوب الأنصاري رضي الله عنه </font></p>', 'default.jpg', 1, 4617, 0, 0, 0, 0, 1, '2011-09-24 23:53:10', 0, 0, 0, NULL, NULL, NULL, '49.mp3', 1);
INSERT INTO `st_sound` (`sound_id`, `sound_cat_id`, `sound_title`, `sound_ts`, `sound_summary`, `sound_des`, `sound_pic`, `sound_pic_pos`, `sound_visitor`, `sound_is_new`, `sound_priority`, `sound_active_vote`, `sound_active_hint`, `sound_active`, `sound_date`, `sound_pic_active`, `sound_last_sound`, `sound_publisher_id`, `sound_source`, `sound_source_url`, `sound_youtube_id`, `sound_file`, `sound_user_add_hint_nsup`) VALUES (106, 39, 'درس الهجرة 7', NULL, '', '<p align=\\\"justify\\\"><font size=\\\"5\\\" face=\\\"Arial\\\">ذكر مؤاخاة النبي صلى الله عليه وسلم بين المهاجرين والأنصار وكيف قاسم الأنصار المهاجرين جميع ما لديهم ثم الحديث عن الإيمان الحق وصفات المتحققين به&nbsp; </font></p>', 'default.jpg', 1, 5345, 0, 0, 0, 0, 1, '2011-09-24 23:53:11', 0, 0, 0, NULL, NULL, NULL, '50.mp3', 1);
