-- ----------------------------
-- Table structure for st_sound_caption
-- ----------------------------
DROP TABLE IF EXISTS `st_sound_caption`;
CREATE TABLE `st_sound_caption` (
  `cap_id` int(8) unsigned NOT NULL AUTO_INCREMENT,
  `cap_ref_id` int(8) unsigned DEFAULT NULL,
  `cap_user_id` int(8) unsigned DEFAULT NULL,
  `cap_date` date DEFAULT '0000-00-00',
  `cap_title` varchar(100) DEFAULT NULL,
  `cap_name` varchar(100) DEFAULT NULL,
  `cap_email` varchar(100) DEFAULT NULL,
  `cap_address` varchar(150) DEFAULT NULL,
  `cap_text` text,
  `cap_isnew` tinyint(1) unsigned DEFAULT '1',
  `cap_active` tinyint(1) unsigned DEFAULT '0',
  PRIMARY KEY (`cap_id`),
  KEY `cap_id` (`cap_id`)
) ENGINE=MyISAM AUTO_INCREMENT=15 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of st_sound_caption
-- ----------------------------
BEGIN;
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (1, 62, 2, '2010-01-16', 'جزاكم الله كل خير', 'محب الشيخ', 'albakkaro@hotmail.com', '', 'جزاكم الله كل خير', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (2, 64, 2, '2010-02-08', 'جزاكم الله خيرا', 'محمود بوظو', 'mahbozo@scs-net.org', 'دمشق', 'سيدي الأستاذ الشيخ محي الدين \r\nالسلام عليكم و رحمة الله و بركاته \r\nجزاكم الله كل خير بما تنعشون به قلوب المحبين بهذه الكنوز من آثار سيدنا الشيخ رضي الله عنه، فتطالع الأرواح مشارق الأنوار و تطير القلوب بآثار سيدنا .', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (3, 74, 2, '2010-03-23', 'الله يجزيكم الخير', 'محمود بوظو', 'mahbozo@scs-net.org', 'دمشق', 'أحييتم قلوبنا و أرواحنا و أنفسنا بأنفاس الشيح رحمه الله تعالى ، رزقنا الله و إياكم رضاه و ألحقنا به يا سيدي الشيخ محي الدين و جميع من يعمل معكم في هذا الموقع المبارك', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (4, 74, 2, '2010-03-26', 'خاطرة', 'ابراهيم  منصور', '', 'aleppo', 'رحم الله الٍامام ورضي الله عنه اللهم ارحمنا به وادم ظله في ذريته الى يوم الساعة ونشكر كل من ساهم في اظهار هذا النز العظيم وصلى الله على سيدنا محمد وعلى اله وصحبه وسلم', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (5, 73, 2, '2010-04-06', '3abdullahduroos sayidna shekh', 'abdul hakim ksseibi', 'aks-1958@hotmail.com', 'madrid', 'arju an  taj3aloo minal mumken tasjeel duroos shaykhna mumken ta7meelaha fi mp3    salam shukran arjuu minkom addu3a a', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (6, 74, 2, '2010-04-13', 'شكزا لكم', 'احمد', '', 'aleppo', 'شكرا لكم على كل ماجاء في الموقع ونرجو من ادارة الموقع وضع رابط لامكانية تحميل الأناشيد وشكرا', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (7, 75, 2, '2010-05-06', 'دعاء', 'محب له', 'hmza1970@hotmail.com', 'حلب', 'اللهم انفعنا به وبعلومه آمين', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (8, 74, 2, '2010-06-15', 'الشكر لاال السراج جميعا', 'محمد عبد الرحمن', 'love19842011@hotmel.com', 'المملكه العربيه السعوديه', 'ارجو من سيادتكم مواصلتي على الايميل وتقديم النصائح جزاكم الله خير الجزاءورحم شيخنا العارف بلله عبد الله سراج واعلى مراتبه في علين وشكراا', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (9, 75, 2, '2010-08-21', 'thanks for all', 'Ahmed Balalo', 'ahmedbalalo@hotmail.com', '', 'i will thanks all the people who work to make this website and thanks his son Mohe aldin seraj al din for all word he do for islam and muslims in all the world.', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (10, 74, 2, '2011-06-23', 'من عشاق الشيخ عبد الله', 'احمد كبة', 'ahmadkba1949@hotaamil.com', 'حلب', 'انا احبك الشيخ عبد الله وربي يغفر لي ان الشيخ عبد الله جارنا', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (11, 74, 2, '2011-11-06', '', 'المكتبي الصغير', 'serag1988@gmail.com', 'سوريا حلب', 'بارك الله فيكم وجزاكم خيراً على هذه المدائح المتميزة', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (12, 108, 2, '2013-08-20', 'شكر', 'بكري حجار', 'b.hajjar@hotmail.com', 'الجمهورية العربية السورية - حلب', 'بسم الله الرحمن الرحيم - الحمد لله رب العالمين وصلى الله وسلم وبارك على سيدنا محمد وعلى آله وصحبه أجمعين\r\nأشكرإدارة الموقع على هذا العمل الرائع راجياً من الله عز وجل أن يوفقكم لكل خير .\r\nوأسأل الله العلي القدير أن يرحم سيدنا الشيخ عبد الله سراج الدين وأن يبارك بذريته وان يديم الهدي النبوي في ذريته وأحبابه إنه سميع مجيب\r\nوصلى الله على سيدنا محمد وعلى آله وصحبه أجمعين', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (13, 108, 2, '2013-12-05', 'جزاكم الله عنا و عن المسلمين أباء و أجدادا و أبناء كل خير', 'محمد كامل قطان', 'mk.kattan@hotmail.com', 'مدريد . اسبانيا', 'نظرا لصعوبة الحصول على ترجمة كتاب &quot; سيدنا محمد صلى الله عليه و على أله و صحبه و سلم . من تأليف شيخنا العلامة فضيلة الوالد الكريم الشيخ عبد الله سراج الدين الحسيني رضي الله تعالى عنه و عن والديه الكريمين و عن أله و ذرياته و عنا معكم وعن جميع المسلمين بجاه سيدنا محمد سيد الأولين و الآخرين صلى الله عليه و على آله و صحبه أجمعين . يرجى ادراج الترجمة في قسم المؤلفات المكتوبة ليستفاد منها بالتعريف بسيد المرسلين صلوات ربي و سلاماته عليه و على آله و صحبه و سلم .في البلاد الأجنبية من خلال ترجمة أمينة لكتاب شيخنا الجليل فضيلة الشيخ عبد الله سراج الدين الحسيني رضي الله تعالى عنه و أعلى مقامه و مقام و الديه الكريمين و وأهليكم أجمعين و مقامكم و مقامناو أهلينا في عليين مع النبيين و الصديقين و الشهداء و الصالحين و حسن أولئك رفيقاً&quot; . اللهم آمين . و جزى الله الأباء و الأجداد و الأبناء كل خير و جزى نبيننا سيدنا محمداً صلى الله عليه و على آله و صحبه و سلم خير ما جزى نبياً عن أمته و رسولاً عن دعوته صلى الله عليه و على أله و صحبه و سلم و جزاكم الله كل خير مشايخنا الكرام و لا تنسونا من دعواتكم الطيبة بظهر الغيب.', 1, 0);
INSERT INTO `st_sound_caption` (`cap_id`, `cap_ref_id`, `cap_user_id`, `cap_date`, `cap_title`, `cap_name`, `cap_email`, `cap_address`, `cap_text`, `cap_isnew`, `cap_active`) VALUES (14, 73, 2, '2018-01-04', 'هذه القصيدة مليئة بالشرك والعياذ بالله', 'عمر الفاروق', 'moatadel_123@yahoo.com', 'حلب الحرة', 'الشيخ سراج الدين كان يشرك بالله ويسمح بالشرك يقال أمامه  ومات وهو غاش لرعيته ولقد اخبر النبي صلى الله عليه وسلم :   ما من عبدٍ يسترعيهِ اللَّهُ رعيَّةً يموتُ يومَ يموتُ وَهوَ غاشٌّ لرعيَّتِهِ إلَّا حرَّمَ اللَّهُ عليهِ الجنَّةَ - صحيح مسلم', 1, 0);
COMMIT;

-- ----------------------------
-- Table structure for st_sound_category
-- ----------------------------
DROP TABLE IF EXISTS `st_sound_category`;
CREATE TABLE `st_sound_category` (
  `cat_id` int(8) unsigned NOT NULL AUTO_INCREMENT,
  `cat_father_id` int(8) unsigned NOT NULL DEFAULT '0',
  `cat_menus` int(8) unsigned DEFAULT NULL,
  `cat_title` varchar(50) NOT NULL DEFAULT '',
  `cat_note` text,
  `cat_pic` varchar(100) DEFAULT NULL,
  `cat_sup` int(8) unsigned NOT NULL DEFAULT '0',
  `cat_date` date DEFAULT NULL,
  `cat_pic_active` tinyint(1) unsigned DEFAULT '1',
  `cat_lan` varchar(10) NOT NULL DEFAULT 'ar',
  `cat_pos` int(8) unsigned NOT NULL DEFAULT '1',
  `cat_active` tinyint(1) unsigned NOT NULL DEFAULT '1',
  `cat_show_menu` tinyint(1) DEFAULT '1',
  `cat_show_main` tinyint(1) DEFAULT '1',
  `cat_agent` text,
  PRIMARY KEY (`cat_id`),
  KEY `adver_id` (`cat_id`)
) ENGINE=MyISAM AUTO_INCREMENT=47 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of st_sound_category
-- ----------------------------
BEGIN;
