INSERT INTO `st_sound_category` (`cat_id`, `cat_father_id`, `cat_menus`, `cat_title`, `cat_note`, `cat_pic`, `cat_sup`, `cat_date`, `cat_pic_active`, `cat_lan`, `cat_pos`, `cat_active`, `cat_show_menu`, `cat_show_main`, `cat_agent`) VALUES (37, 0, 55, 'جزء من صلاة التراويح للشيخ الإمام', '', 'defaut.jpg', 0, '2010-08-26', 0, 'ar', 70, 1, 1, 1, '');
INSERT INTO `st_sound_category` (`cat_id`, `cat_father_id`, `cat_menus`, `cat_title`, `cat_note`, `cat_pic`, `cat_sup`, `cat_date`, `cat_pic_active`, `cat_lan`, `cat_pos`, `cat_active`, `cat_show_menu`, `cat_show_main`, `cat_agent`) VALUES (38, 0, 55, 'تلاوتان نادرتان للشيخ مصطفى إسماعيل', 'قدم الشيخ مصطفى إسماعيل إلى  حلب سنة 1377 هـ واستقبله وجهاء حلب ومنهم المرحوم الشيخ عبد اللطيف بن الشيخ محمد آل باذنجكي ( المتوفى سنة 1390 هـ رحمه الله ) استقبله في كرم له ناحية الشرق من حلب , وكان سيدي الوالد ممن رحب بالشيخ مصطفى وحضر معه مأدبة العشاء في الكرم وقرأ الشيخ مصطفى حتى أخذ بقلوب الحاضرين \r\nقلت : وقد كان الشيخ مصطفى إسماعيل رحمه الله يتقن علم الألحان ويتغنى في تلاوته للقرآن دونما خروج عن أحكام التجويد ويأتي بالحروف من مخارجها ويلفظها بصفاتها التي نص عليها علماء القراءات \r\nوقد قرأ الشيخ مصطفى إسماعيل في الجامع الأموي الكبير سورة { ق } بصوت شجي ندي وألحان متنوعة حضر لسماعها كثير من أهالي حلب وقتها , كما قرأ في جامع بانقوسا شيئاً من سورة الإسراء وأذن لصلاة المغرب عند ختم قراءته\r\nوهاتان من القراءات النادرة , ولما غادر الشيخ مصطفى إسماعيل مدينة حلب مودعاً من أهلها بالحفاوة التي استقبل بها قال للحاضرين كلمته المشهورة : لقد قرأت كثيراً في مناسبات دينية عديدة وفي بلدان كثيرة لكني لم أجد آذاناً تتذوق الصوت الندي واللحن الشجي كآذان أهل حلب – قالها بلهجته المصرية  – ( وقد توفي سنة  1402 هـ رحمه الله ) .', 'defaut.jpg', 0, '2010-08-26', 0, 'ar', 80, 1, 1, 1, '');
INSERT INTO `st_sound_category` (`cat_id`, `cat_father_id`, `cat_menus`, `cat_title`, `cat_note`, `cat_pic`, `cat_sup`, `cat_date`, `cat_pic_active`, `cat_lan`, `cat_pos`, `cat_active`, `cat_show_menu`, `cat_show_main`, `cat_agent`) VALUES (39, 0, 55, 'دروس سنة 1398 للهجرة النبوية الشريفة', 'سجلت هذه الدروس سنة 1398 للهجرة النبوية الشريفة , وقد حرصت على انتقاء أنقاها صوتاً من حيث التقنية والصفاء لإيصالها للسامع على وجه يسهل عليه الفهم والإصغاء مع مراعاة أن معظم الدروس مجزأ إلى قسمين فعلى المستمع الكريم متابعة الاستماع لتتم له الفائدة \r\nونسال الله التوفيق لنشر المزيد من تراث شيخنا الإمام رضي الله عنه \r\nمن مسموعات ومقروءات  والحمد لله رب العالمين', 'defaut.jpg', 0, '2011-09-24', 0, 'ar', 30, 1, 1, 1, '');
INSERT INTO `st_sound_category` (`cat_id`, `cat_father_id`, `cat_menus`, `cat_title`, `cat_note`, `cat_pic`, `cat_sup`, `cat_date`, `cat_pic_active`, `cat_lan`, `cat_pos`, `cat_active`, `cat_show_menu`, `cat_show_main`, `cat_agent`) VALUES (46, 42, 0, 'كتاب تفسير سورة الملك', 'سجل هذا الكتاب بصوت أحد طلبة العلم جزاه الله خيرا', 'defaut.jpg', 1, '2014-03-25', 0, 'ar', 4, 1, 0, 0, '');
INSERT INTO `st_sound_category` (`cat_id`, `cat_father_id`, `cat_menus`, `cat_title`, `cat_note`, `cat_pic`, `cat_sup`, `cat_date`, `cat_pic_active`, `cat_lan`, `cat_pos`, `cat_active`, `cat_show_menu`, `cat_show_main`, `cat_agent`) VALUES (42, 0, 21, 'الاستماع إلى بعض الكتب المسجلة', '', 'defaut.jpg', 0, '2013-10-26', 0, 'ar', 10, 0, 1, 1, '');
